INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C1','math',3,1,'u5',2,'1 mm 알기 — 1 cm를 똑같이 10칸으로 나눈 한 칸이 1 mm(1 밀리미터)임을 알고, 1 cm = 10 mm 관계로 자의 mm 눈금을 읽기',ARRAY['4수03-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C2','math',3,1,'u5',2,'몇 cm 몇 mm와 몇 mm — 같은 길이를 몇 cm 몇 mm와 몇 mm 두 가지로 바꾸어 나타내고, 두 길이를 견주기',ARRAY['4수03-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C3','math',3,1,'u5',3,'mm·cm 길이 어림하고 재기 — 엄지 너비(약 1 cm)·아는 길이 이어 붙이기로 길이를 「약 ○○」로 어림하고, 자로 재어(0이 아닌 눈금에서 시작해도) 확인하기',ARRAY['4수03-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C4','math',3,1,'u5',4,'1 km 알기 — 1000 m가 1 km(1 킬로미터)임을 알고, 거리를 몇 km 몇 m와 몇 m 두 가지로 바꾸어 나타내고 견주기',ARRAY['4수03-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C5','math',3,1,'u5',5,'거리 어림과 알맞은 단위 — 단위 거리(약 500 m 등)가 몇 번 들어가는지로 먼 거리를 어림하고, 대상의 크기에 알맞은 단위(mm·cm·m·km)를 고르기',ARRAY['4수03-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C6','math',3,1,'u5',6,'1초 알기 — 초바늘이 작은 눈금 한 칸 가는 동안이 1초, 한 바퀴가 60초 = 1분임을 알고, 몇 시 몇 분 몇 초를 읽고 분과 초를 바꾸어 나타내기',ARRAY['4수03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C7','math',3,1,'u5',7,'시간의 덧셈 — 시·분·초를 같은 단위끼리 더하고 60이 넘으면 받아올림하며, 시작 시각 + 걸린 시간으로 끝난 시각 구하기',ARRAY['4수03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C8','math',3,1,'u5',8,'시간의 뺄셈 — 시·분·초를 같은 단위끼리 빼고 모자라면 1분(60초)·1시간(60분)을 빌려 오며, 끝난 시각 − 시작 시각으로 걸린 시간 구하기',ARRAY['4수03-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u5-C9','math',3,1,'u5',9,'길이와 시간 단서로 문제 해결 — 알맞은 길이 단위를 고르고 걸린 시간을 구해, 여러 단서를 모두 만족하는 답을 찾기',ARRAY['4수03-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X01','math',3,'u5',ARRAY['M3-1-u5-C1','M3-1-u5-C2','M3-1-u5-C4']::text[],'단위 사이의 관계 수를 잘못 안다(1 cm = 100 mm, 1 km = 100 m처럼 10배·1000배를 헷갈린다)','1 cm = 10 mm, 1 km = 1000 m') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X02','math',3,'u5',ARRAY['M3-1-u5-C2','M3-1-u5-C4','M3-1-u5-C6']::text[],'큰 단위의 수와 작은 단위의 수를 그냥 더한다(6 cm 7 mm → 13 mm, 1분 30초 → 31초)','큰 단위를 먼저 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X03','math',3,'u5',ARRAY['M3-1-u5-C2','M3-1-u5-C4']::text[],'바꾸어 쓸 때 자리를 맞추지 못해 0을 끼우거나 빠뜨린다(6 cm 7 mm → 607 mm, 2 km 15 m → 215 m)','2 km = 2000 m부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X04','math',3,'u5',ARRAY['M3-1-u5-C2','M3-1-u5-C4','M3-1-u5-C6']::text[],'작은 단위의 수를 큰 단위와 작은 단위로 나눌 때 자리를 잘못 나누거나 단위를 그대로 둔다(71 mm → 71 cm, 3750 m → 37 km 50 m)','10씩·1000씩·60씩 묶기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X05','math',3,'u5',ARRAY['M3-1-u5-C1','M3-1-u5-C3']::text[],'자의 mm 눈금을 잘못 세거나, 0이 아닌 눈금에서 시작한 물건의 끝 눈금을 그대로 길이로 읽는다','시작 눈금부터 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X06','math',3,'u5',ARRAY['M3-1-u5-C3','M3-1-u5-C5','M3-1-u5-C9']::text[],'대상의 크기에 맞지 않는 단위로 어림한다(발 길이 약 220 cm, 한라산 높이 약 1950 km)','손톱 mm·책상 cm·건물 m·도시 km') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X07','math',3,'u5',ARRAY['M3-1-u5-C3','M3-1-u5-C5']::text[],'어림한 길이에 「약」을 붙이지 않거나, 어림도 꼭 자로 정확히 재야 한다고 생각한다','짐작한 길이는 「약」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X08','math',3,'u5',ARRAY['M3-1-u5-C5']::text[],'단위 거리가 몇 번 들어가는지로 어림할 때 단위 거리를 그 횟수만큼 더하지 않는다(약 500 m가 3번 → 약 3 km·약 150 m)','500 m + 500 m + 500 m') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X09','math',3,'u5',ARRAY['M3-1-u5-C6','M3-1-u5-C7','M3-1-u5-C8']::text[],'1분을 100초로 생각해 분과 초를 바꾸거나 빌려 온다(1분 30초 = 130초, 185초 = 1분 85초)','1분 = 60초') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X10','math',3,'u5',ARRAY['M3-1-u5-C6','M3-1-u5-C9']::text[],'시계의 바늘을 바꾸어 읽는다(긴바늘과 초바늘, 짧은바늘과 긴바늘)','짧은 시·긴 분·가는 빨간 초') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X11','math',3,'u5',ARRAY['M3-1-u5-C6']::text[],'초바늘이 가리키는 숫자를 그대로 초로 읽는다(숫자 6 → 6초)','숫자 한 칸은 5초') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X12','math',3,'u5',ARRAY['M3-1-u5-C6','M3-1-u5-C7','M3-1-u5-C8']::text[],'시각(때)과 시간(동안)을 구별하지 못한다','「~에」 시각, 「~동안」 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X13','math',3,'u5',ARRAY['M3-1-u5-C7']::text[],'시간을 더해 60이 넘어도 받아올림하지 않는다(2분 50초 + 30초 = 2분 80초)','60초는 1분으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X14','math',3,'u5',ARRAY['M3-1-u5-C7']::text[],'받아올림하면서 60은 뺐지만 윗단위에 1을 더하지 않거나 두 번 더한다(50초 + 30초 → 20초)','올린 1을 윗단위에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X15','math',3,'u5',ARRAY['M3-1-u5-C7','M3-1-u5-C8']::text[],'같은 단위끼리 자리를 맞추지 않고 더하거나 뺀다(10시 20분 + 11분 → 21시 20분)','시는 시끼리·분은 분끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X16','math',3,'u5',ARRAY['M3-1-u5-C8','M3-1-u5-C9']::text[],'받아내림을 하고 빌려준 윗단위를 1 줄이지 않는다(9시간 20분 30초 − 7시간 10분 40초 → 2시간 10분 50초)','빌려준 자리는 1 줄이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X17','math',3,'u5',ARRAY['M3-1-u5-C8']::text[],'작은 단위가 모자랄 때 큰 수에서 작은 수를 거꾸로 뺀다(30초 − 40초 → 10초)','모자라면 60 빌려 오기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X18','math',3,'u5',ARRAY['M3-1-u5-C8','M3-1-u5-C9']::text[],'걸린 시간을 시계의 시 숫자 개수로 센다(1시부터 4시까지 → 4시간·5시간)','끝난 시각 − 시작 시각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X19','math',3,'u5',ARRAY['M3-1-u5-C9']::text[],'여러 단서 중 하나만 맞는 답을 고른다','단서를 하나씩 모두 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X20','math',3,'u5',ARRAY['M3-1-u5-C1','M3-1-u5-C2','M3-1-u5-C3','M3-1-u5-C4','M3-1-u5-C5','M3-1-u5-C6','M3-1-u5-C7','M3-1-u5-C8','M3-1-u5-C9']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 짧은↔긴, 빠른↔느린','물음의 핵심 말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u5-X21','math',3,'u5',ARRAY['M3-1-u5-C6','M3-1-u5-C7','M3-1-u5-C8','M3-1-u5-C9']::text[],'같은 단위끼리 더하거나 빼는 계산에서 실수해 답이 조금 크거나 작다','초부터 차례로 다시 셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#1','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C1',1,'sa','auto','씨앗의 길이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u5-C1","difficulty":1,"kind":"sa","stem":"씨앗의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","씨앗 끝은 3 cm에서 작은 눈금 5칸 더 간 곳이에요.","3 cm 5 mm = 35 mm예요."],"asset":{"type":"mmruler","len":35,"label":"씨앗"},"variant_rule":{"alt":[{"stem":"나뭇잎의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["79"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","나뭇잎 끝은 7 cm에서 작은 눈금 9칸 더 간 곳이에요.","7 cm 9 mm = 79 mm예요."],"asset":{"type":"mmruler","len":79,"label":"나뭇잎"}},{"stem":"솔방울의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","솔방울 끝은 4 cm에서 작은 눈금 6칸 더 간 곳이에요.","4 cm 6 mm = 46 mm예요."],"asset":{"type":"mmruler","len":46,"label":"솔방울"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#2','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C1',1,'mc','auto','1 cm는 몇 mm인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X21']::text[],true,'{"seq":2,"concept":"M3-1-u5-C1","difficulty":1,"kind":"mc","stem":"1 cm는 몇 mm인가요?","options":[{"t":"10 mm","correct":true},{"t":"100 mm","mis":"M3-1-u5-X01"},{"t":"1 mm","mis":"M3-1-u5-X01"},{"t":"12 mm","mis":"M3-1-u5-X21"}],"explanation":["1 cm를 똑같이 10칸으로 나눈 작은 눈금 한 칸이 1 mm예요.","1 mm는 「1 밀리미터」라고 읽어요.","그래서 1 cm = 10 mm예요."],"variant_rule":{"alt":[{"stem":"1 cm를 똑같이 몇 칸으로 나눈 한 칸의 길이가 1 mm인가요?","options":[{"t":"10칸","correct":true},{"t":"100칸","mis":"M3-1-u5-X01"},{"t":"5칸","mis":"M3-1-u5-X05"},{"t":"2칸","mis":"M3-1-u5-X05"}],"explanation":["1 cm를 똑같이 10칸으로 나눈 작은 눈금 한 칸이 1 mm예요.","1 mm는 「1 밀리미터」라고 읽어요.","그래서 1 cm = 10 mm예요."],"asset":null},{"stem":"「4 mm」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"4 밀리미터","correct":true},{"t":"4 센티미터","mis":"M3-1-u5-X01"},{"t":"4 미터","mis":"M3-1-u5-X06"},{"t":"4 킬로미터","mis":"M3-1-u5-X06"}],"explanation":["1 cm를 똑같이 10칸으로 나눈 작은 눈금 한 칸이 1 mm예요.","1 mm는 「1 밀리미터」라고 읽어요.","그래서 1 cm = 10 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#3','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C2',1,'sa','auto','6 cm 7 mm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u5-C2","difficulty":1,"kind":"sa","stem":"6 cm 7 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["67"],"explanation":["1 cm = 10 mm예요.","6 cm = 60 mm, 여기에 7 mm를 더해요.","6 cm 7 mm = 67 mm예요."],"variant_rule":{"alt":[{"stem":"8 cm 7 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["1 cm = 10 mm예요.","8 cm = 80 mm, 여기에 7 mm를 더해요.","8 cm 7 mm = 87 mm예요."],"asset":null},{"stem":"7 cm 2 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["1 cm = 10 mm예요.","7 cm = 70 mm, 여기에 2 mm를 더해요.","7 cm 2 mm = 72 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#4','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C2',1,'mc','auto','리본의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?',ARRAY['M3-1-u5-X04','M3-1-u5-X03']::text[],true,'{"seq":4,"concept":"M3-1-u5-C2","difficulty":1,"kind":"mc","stem":"리본의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?","options":[{"t":"2 cm 7 mm","correct":true},{"t":"7 cm 2 mm","mis":"M3-1-u5-X04"},{"t":"27 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 70 mm","mis":"M3-1-u5-X03"}],"explanation":["큰 눈금 숫자를 먼저 읽어요 — 2 cm.","그다음 작은 눈금 7칸 — 7 mm.","리본의 길이는 2 cm 7 mm예요."],"asset":{"type":"mmruler","len":27,"label":"리본"},"variant_rule":{"alt":[{"stem":"색 테이프의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?","options":[{"t":"9 cm 4 mm","correct":true},{"t":"4 cm 9 mm","mis":"M3-1-u5-X04"},{"t":"94 cm","mis":"M3-1-u5-X04"},{"t":"9 cm 40 mm","mis":"M3-1-u5-X03"}],"explanation":["큰 눈금 숫자를 먼저 읽어요 — 9 cm.","그다음 작은 눈금 4칸 — 4 mm.","색 테이프의 길이는 9 cm 4 mm예요."],"asset":{"type":"mmruler","len":94,"label":"색 테이프"}},{"stem":"잎자루의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?","options":[{"t":"8 cm 7 mm","correct":true},{"t":"7 cm 8 mm","mis":"M3-1-u5-X04"},{"t":"87 cm","mis":"M3-1-u5-X04"},{"t":"8 cm 70 mm","mis":"M3-1-u5-X03"}],"explanation":["큰 눈금 숫자를 먼저 읽어요 — 8 cm.","그다음 작은 눈금 7칸 — 7 mm.","잎자루의 길이는 8 cm 7 mm예요."],"asset":{"type":"mmruler","len":87,"label":"잎자루"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#5','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C2',2,'mc','auto','8 cm 9 mm는 몇 mm인가요?',ARRAY['M3-1-u5-X03','M3-1-u5-X02','M3-1-u5-X04']::text[],true,'{"seq":5,"concept":"M3-1-u5-C2","difficulty":2,"kind":"mc","stem":"8 cm 9 mm는 몇 mm인가요?","options":[{"t":"89 mm","correct":true},{"t":"809 mm","mis":"M3-1-u5-X03"},{"t":"17 mm","mis":"M3-1-u5-X02"},{"t":"98 mm","mis":"M3-1-u5-X04"}],"explanation":["1 cm = 10 mm예요.","8 cm = 80 mm, 여기에 9 mm를 더해요.","8 cm 9 mm = 89 mm예요."],"variant_rule":{"alt":[{"stem":"6 cm 1 mm는 몇 mm인가요?","options":[{"t":"61 mm","correct":true},{"t":"601 mm","mis":"M3-1-u5-X03"},{"t":"7 mm","mis":"M3-1-u5-X02"},{"t":"16 mm","mis":"M3-1-u5-X04"}],"explanation":["1 cm = 10 mm예요.","6 cm = 60 mm, 여기에 1 mm를 더해요.","6 cm 1 mm = 61 mm예요."],"asset":null},{"stem":"7 cm 3 mm는 몇 mm인가요?","options":[{"t":"73 mm","correct":true},{"t":"703 mm","mis":"M3-1-u5-X03"},{"t":"10 mm","mis":"M3-1-u5-X02"},{"t":"37 mm","mis":"M3-1-u5-X04"}],"explanation":["1 cm = 10 mm예요.","7 cm = 70 mm, 여기에 3 mm를 더해요.","7 cm 3 mm = 73 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#6','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C2',2,'mc','auto','71 mm는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X04']::text[],true,'{"seq":6,"concept":"M3-1-u5-C2","difficulty":2,"kind":"mc","stem":"71 mm는 몇 cm 몇 mm인가요?","options":[{"t":"7 cm 1 mm","correct":true},{"t":"1 cm 7 mm","mis":"M3-1-u5-X04"},{"t":"71 cm","mis":"M3-1-u5-X04"},{"t":"6 cm 11 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","71 mm = 70 mm + 1 mm.","71 mm = 7 cm 1 mm예요."],"variant_rule":{"alt":[{"stem":"81 mm는 몇 cm 몇 mm인가요?","options":[{"t":"8 cm 1 mm","correct":true},{"t":"1 cm 8 mm","mis":"M3-1-u5-X04"},{"t":"81 cm","mis":"M3-1-u5-X04"},{"t":"7 cm 11 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","81 mm = 80 mm + 1 mm.","81 mm = 8 cm 1 mm예요."],"asset":null},{"stem":"15 mm는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 5 mm","correct":true},{"t":"5 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"15 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 5 mm","mis":"M3-1-u5-X21"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","15 mm = 10 mm + 5 mm.","15 mm = 1 cm 5 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#7','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C2',2,'ox','auto','서윤이 8 cm 3 mm를 83 cm라고 썼어요. 바르게 썼어요.',ARRAY['M3-1-u5-X04']::text[],true,'{"seq":7,"concept":"M3-1-u5-C2","difficulty":2,"kind":"ox","stem":"서윤이 8 cm 3 mm를 83 cm라고 썼어요. 바르게 썼어요.","answer":"X","reason_options":[{"t":"8 cm 3 mm는 83 mm라서 단위가 mm여야 해서","correct":true},{"t":"수만 맞으면 단위는 아무거나 써도 되어서","mis":"M3-1-u5-X04"}],"mis":"M3-1-u5-X04","explanation":["8 cm 3 mm = 83 mm예요.","83 cm는 83 mm의 10배인 아주 긴 길이예요.","그래서 틀렸어요 — 83 mm라고 써야 해요."],"variant_rule":{"alt":[{"stem":"하린이 8 cm 6 mm를 86 cm라고 썼어요. 바르게 썼어요.","answer":"X","reason_options":[{"t":"8 cm 6 mm는 86 mm라서 단위가 mm여야 해서","correct":true},{"t":"수만 맞으면 단위는 아무거나 써도 되어서","mis":"M3-1-u5-X04"}],"explanation":["8 cm 6 mm = 86 mm예요.","86 cm는 86 mm의 10배인 아주 긴 길이예요.","그래서 틀렸어요 — 86 mm라고 써야 해요."],"asset":null},{"stem":"은우가 1 cm 8 mm를 18 cm라고 썼어요. 바르게 썼어요.","answer":"X","reason_options":[{"t":"1 cm 8 mm는 18 mm라서 단위가 mm여야 해서","correct":true},{"t":"수만 맞으면 단위는 아무거나 써도 되어서","mis":"M3-1-u5-X04"}],"explanation":["1 cm 8 mm = 18 mm예요.","18 cm는 18 mm의 10배인 아주 긴 길이예요.","그래서 틀렸어요 — 18 mm라고 써야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#8','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C1',2,'mc','auto','잎자루의 길이가 8 cm보다 3 mm 더 길어요. 잎자루의 길이는 얼마인가요?',ARRAY['M3-1-u5-X02','M3-1-u5-X04']::text[],true,'{"seq":8,"concept":"M3-1-u5-C1","difficulty":2,"kind":"mc","stem":"잎자루의 길이가 8 cm보다 3 mm 더 길어요. 잎자루의 길이는 얼마인가요?","options":[{"t":"8 cm 3 mm","correct":true},{"t":"11 mm","mis":"M3-1-u5-X02"},{"t":"3 cm 8 mm","mis":"M3-1-u5-X04"},{"t":"11 cm","mis":"M3-1-u5-X02"}],"explanation":["8 cm보다 3 mm 더 길면 8 cm 3 mm라고 써요.","「8 센티미터 3 밀리미터」라고 읽어요.","8 cm 3 mm = 83 mm예요."],"variant_rule":{"alt":[{"stem":"씨앗의 길이가 9 cm보다 1 mm 더 길어요. 씨앗의 길이는 얼마인가요?","options":[{"t":"9 cm 1 mm","correct":true},{"t":"10 mm","mis":"M3-1-u5-X02"},{"t":"1 cm 9 mm","mis":"M3-1-u5-X04"},{"t":"10 cm","mis":"M3-1-u5-X02"}],"explanation":["9 cm보다 1 mm 더 길면 9 cm 1 mm라고 써요.","「9 센티미터 1 밀리미터」라고 읽어요.","9 cm 1 mm = 91 mm예요."],"asset":null},{"stem":"나뭇잎의 길이가 7 cm보다 7 mm 더 길어요. 나뭇잎의 길이는 얼마인가요?","options":[{"t":"7 cm 7 mm","correct":true},{"t":"14 mm","mis":"M3-1-u5-X02"},{"t":"14 cm","mis":"M3-1-u5-X02"},{"t":"7 cm 70 mm","mis":"M3-1-u5-X03"}],"explanation":["7 cm보다 7 mm 더 길면 7 cm 7 mm라고 써요.","「7 센티미터 7 밀리미터」라고 읽어요.","7 cm 7 mm = 77 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#9','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C2',2,'match','auto','같은 길이끼리 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u5-C2","difficulty":2,"kind":"match","stem":"같은 길이끼리 이으세요.","pairs":[{"l":"2 cm 5 mm","r":"25 mm"},{"l":"2 cm 8 mm","r":"28 mm"},{"l":"2 cm 3 mm","r":"23 mm"}],"mis":"M3-1-u5-X03","explanation":["1 cm = 10 mm라 몇 cm는 몇십 mm예요.","2 cm 5 mm = 25 mm, 2 cm 8 mm = 28 mm, 2 cm 3 mm = 23 mm.","수의 순서를 바꾸면 다른 길이가 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 같은 길이끼리 이으세요.","pairs":[{"l":"1 cm 7 mm","r":"17 mm"},{"l":"7 cm 5 mm","r":"75 mm"},{"l":"5 cm 6 mm","r":"56 mm"}],"explanation":["1 cm = 10 mm라 몇 cm는 몇십 mm예요.","1 cm 7 mm = 17 mm, 7 cm 5 mm = 75 mm, 5 cm 6 mm = 56 mm.","수의 순서를 바꾸면 다른 길이가 돼요."],"asset":null},{"stem":"이번에는 다른 문제예요. 같은 길이끼리 이으세요.","pairs":[{"l":"4 cm 9 mm","r":"49 mm"},{"l":"1 cm 3 mm","r":"13 mm"},{"l":"1 cm 6 mm","r":"16 mm"}],"explanation":["1 cm = 10 mm라 몇 cm는 몇십 mm예요.","4 cm 9 mm = 49 mm, 1 cm 3 mm = 13 mm, 1 cm 6 mm = 16 mm.","수의 순서를 바꾸면 다른 길이가 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_basic#10','math',3,1,'u5','L02','g3_1_math_u5_L02_basic','lesson_basic','M3-1-u5-C2',3,'error','auto','2 cm 5 mm를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X03','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C2","difficulty":3,"kind":"error","stem":"2 cm 5 mm를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「2 cm 5 mm = 205 mm」","correct":true,"mis_target":"M3-1-u5-X03"},{"t":"하은 — 「2 cm 5 mm = 25 mm야」","mis":"M3-1-u5-X20"},{"t":"민준 — 「1 cm = 10 mm야」","mis":"M3-1-u5-X20"}],"explanation":["2 cm = 20 mm예요.","20 mm + 5 mm = 25 mm예요.","도윤은 2와 5 사이에 0을 끼워 넣었어요."],"variant_rule":{"alt":[{"stem":"6 cm 1 mm를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「6 cm 1 mm = 601 mm」","correct":true,"mis_target":"M3-1-u5-X03"},{"t":"하린 — 「6 cm 1 mm = 61 mm야」","mis":"M3-1-u5-X20"},{"t":"시우 — 「6 cm보다 1 mm 더 길어」","mis":"M3-1-u5-X20"}],"explanation":["6 cm = 60 mm예요.","60 mm + 1 mm = 61 mm예요.","도윤은 6과 1 사이에 0을 끼워 넣었어요."],"asset":null},{"stem":"9 cm 2 mm를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「9 cm 2 mm = 902 mm」","correct":true,"mis_target":"M3-1-u5-X03"},{"t":"하랑 — 「9 cm 2 mm = 92 mm야」","mis":"M3-1-u5-X20"},{"t":"서윤 — 「1 cm = 10 mm야」","mis":"M3-1-u5-X20"}],"explanation":["9 cm = 90 mm예요.","90 mm + 2 mm = 92 mm예요.","도윤은 9와 2 사이에 0을 끼워 넣었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
