INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_challenge#6','math',3,1,'u5','L02','g3_1_math_u5_L02_challenge','lesson_challenge','M3-1-u5-C2',3,'sa','auto','연필의 길이는 8 cm 5 mm, 지우개를 이어 놓은 길이는 47 mm예요. 연필이 몇 mm 더 긴가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u5-C2","difficulty":3,"kind":"sa","stem":"연필의 길이는 8 cm 5 mm, 지우개를 이어 놓은 길이는 47 mm예요. 연필이 몇 mm 더 긴가요? 숫자로 쓰세요.","answer":["38"],"explanation":["단위를 mm로 맞춰요 — 8 cm 5 mm = 85 mm예요.","85 − 47 = 38.","연필이 38 mm 더 길어요."],"variant_rule":{"alt":[{"stem":"연필의 길이는 6 cm 8 mm, 지우개를 이어 놓은 길이는 23 mm예요. 연필이 몇 mm 더 긴가요? 숫자로 쓰세요.","answer":["45"],"explanation":["단위를 mm로 맞춰요 — 6 cm 8 mm = 68 mm예요.","68 − 23 = 45.","연필이 45 mm 더 길어요."],"asset":null},{"stem":"연필의 길이는 6 cm 4 mm, 지우개를 이어 놓은 길이는 33 mm예요. 연필이 몇 mm 더 긴가요? 숫자로 쓰세요.","answer":["31"],"explanation":["단위를 mm로 맞춰요 — 6 cm 4 mm = 64 mm예요.","64 − 33 = 31.","연필이 31 mm 더 길어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_challenge#7','math',3,1,'u5','L02','g3_1_math_u5_L02_challenge','lesson_challenge','M3-1-u5-C2',3,'sa','auto','93 mm = □ cm 3 mm — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u5-C2","difficulty":3,"kind":"sa","stem":"93 mm = □ cm 3 mm — □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["10 mm = 1 cm — 10씩 묶어요.","93 mm = 90 mm + 3 mm.","93 mm = 9 cm 3 mm예요."],"variant_rule":{"alt":[{"stem":"55 mm = □ cm 5 mm — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["10 mm = 1 cm — 10씩 묶어요.","55 mm = 50 mm + 5 mm.","55 mm = 5 cm 5 mm예요."],"asset":null},{"stem":"57 mm = □ cm 7 mm — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["10 mm = 1 cm — 10씩 묶어요.","57 mm = 50 mm + 7 mm.","57 mm = 5 cm 7 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_challenge#8','math',3,1,'u5','L02','g3_1_math_u5_L02_challenge','lesson_challenge','M3-1-u5-C2',4,'essay','teacher','나뭇잎의 길이가 6 cm 7 mm예요. 이 길이가 몇 mm인지 1 cm = 10 mm를 이용해 구하는 방법을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C2","difficulty":4,"kind":"essay","stem":"나뭇잎의 길이가 6 cm 7 mm예요. 이 길이가 몇 mm인지 1 cm = 10 mm를 이용해 구하는 방법을 써 보세요.","answer_guide":{"answer":"예: 1 cm = 10 mm이므로 6 cm는 60 mm이다. 60 mm에 7 mm를 더하면 67 mm이다. 그래서 6 cm 7 mm = 67 mm이다.","scoring_points":["6 cm = 60 mm로 바꾸었는가","60 mm + 7 mm를 했는가","67 mm를 구했는가"]},"explanation":["1 cm = 10 mm.","6 cm = 60 mm, + 7 mm.","6 cm 7 mm = 67 mm."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_challenge#9','math',3,1,'u5','L02','g3_1_math_u5_L02_challenge','lesson_challenge','M3-1-u5-C2',4,'essay','teacher','어떤 친구가 2 cm 5 mm를 205 mm라고 했어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C2","difficulty":4,"kind":"essay","stem":"어떤 친구가 2 cm 5 mm를 205 mm라고 했어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 2 cm는 20 mm인데 2와 5 사이에 0을 끼워 205라고 썼다. 205 mm는 20 cm 5 mm로 훨씬 긴 길이이다. 바르게 고치면 2 cm 5 mm = 20 mm + 5 mm = 25 mm이다.","scoring_points":["0을 끼워 넣었다고 찾았는가","2 cm = 20 mm로 설명했는가","25 mm로 고쳤는가"]},"explanation":["2 cm = 20 mm.","20 mm + 5 mm = 25 mm.","205 mm는 20 cm 5 mm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L02_challenge#10','math',3,1,'u5','L02','g3_1_math_u5_L02_challenge','lesson_challenge','M3-1-u5-C2',4,'sa','auto','리본 3 cm 6 mm와 4 cm 8 mm를 겹치지 않게 이었어요. 이은 리본은 모두 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u5-C2","difficulty":4,"kind":"sa","stem":"리본 3 cm 6 mm와 4 cm 8 mm를 겹치지 않게 이었어요. 이은 리본은 모두 몇 mm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["두 길이를 mm로 바꿔요 — 36 mm, 48 mm.","36 + 48 = 84.","모두 84 mm예요 — 8 cm 4 mm."],"variant_rule":{"alt":[{"stem":"리본 2 cm 9 mm와 4 cm 6 mm를 겹치지 않게 이었어요. 이은 리본은 모두 몇 mm인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["두 길이를 mm로 바꿔요 — 29 mm, 46 mm.","29 + 46 = 75.","모두 75 mm예요 — 7 cm 5 mm."],"asset":null},{"stem":"리본 5 cm 9 mm와 3 cm 5 mm를 겹치지 않게 이었어요. 이은 리본은 모두 몇 mm인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["두 길이를 mm로 바꿔요 — 59 mm, 35 mm.","59 + 35 = 94.","모두 94 mm예요 — 9 cm 4 mm."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#1','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',1,'mc','auto','엄지손가락 너비는 약 1 cm예요. 엄지가 6번쯤 들어가는 사인펜의 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X01','M3-1-u5-X21']::text[],true,'{"seq":1,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 6번쯤 들어가는 사인펜의 길이는 약 얼마인가요?","options":[{"t":"약 6 cm","correct":true},{"t":"약 6 mm","mis":"M3-1-u5-X06"},{"t":"약 60 cm","mis":"M3-1-u5-X01"},{"t":"약 16 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","6번이면 약 6 cm.","어림한 길이라 앞에 「약」을 붙여 약 6 cm라고 해요."],"variant_rule":{"alt":[{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 13번쯤 들어가는 필통의 길이는 약 얼마인가요?","options":[{"t":"약 13 cm","correct":true},{"t":"약 13 mm","mis":"M3-1-u5-X06"},{"t":"약 130 cm","mis":"M3-1-u5-X01"},{"t":"약 23 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","13번이면 약 13 cm.","어림한 길이라 앞에 「약」을 붙여 약 13 cm라고 해요."],"asset":null},{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 10번쯤 들어가는 자의 길이는 약 얼마인가요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 10 mm","mis":"M3-1-u5-X06"},{"t":"약 100 cm","mis":"M3-1-u5-X01"},{"t":"약 20 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","10번이면 약 10 cm.","어림한 길이라 앞에 「약」을 붙여 약 10 cm라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#2','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',1,'mc','auto','약 7 cm인 색연필과 약 3 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X03','M3-1-u5-X06']::text[],true,'{"seq":2,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"약 7 cm인 색연필과 약 3 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 4 cm","mis":"M3-1-u5-X20"},{"t":"약 73 cm","mis":"M3-1-u5-X03"},{"t":"약 10 mm","mis":"M3-1-u5-X06"}],"explanation":["길이를 아는 물건을 이어 붙여 어림해요.","약 7 cm + 약 3 cm.","이은 길이는 약 10 cm예요."],"variant_rule":{"alt":[{"stem":"약 6 cm인 색연필과 약 3 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?","options":[{"t":"약 9 cm","correct":true},{"t":"약 3 cm","mis":"M3-1-u5-X20"},{"t":"약 63 cm","mis":"M3-1-u5-X03"},{"t":"약 9 mm","mis":"M3-1-u5-X06"}],"explanation":["길이를 아는 물건을 이어 붙여 어림해요.","약 6 cm + 약 3 cm.","이은 길이는 약 9 cm예요."],"asset":null},{"stem":"약 7 cm인 색연필과 약 4 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?","options":[{"t":"약 11 cm","correct":true},{"t":"약 3 cm","mis":"M3-1-u5-X20"},{"t":"약 74 cm","mis":"M3-1-u5-X03"},{"t":"약 11 mm","mis":"M3-1-u5-X06"}],"explanation":["길이를 아는 물건을 이어 붙여 어림해요.","약 7 cm + 약 4 cm.","이은 길이는 약 11 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#3','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',1,'mc','auto','어림한 길이를 말할 때 앞에 붙이는 말은 어느 것인가요?',ARRAY['M3-1-u5-X07','M3-1-u5-X20']::text[],true,'{"seq":3,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"어림한 길이를 말할 때 앞에 붙이는 말은 어느 것인가요?","options":[{"t":"약","correct":true},{"t":"정확히","mis":"M3-1-u5-X07"},{"t":"모두","mis":"M3-1-u5-X20"},{"t":"반","mis":"M3-1-u5-X20"}],"explanation":["어림은 자 없이 길이를 짐작하는 거예요.","어림한 길이는 「약 ○○」으로 나타내요.","엄지 너비(약 1 cm)로 짐작하고 자로 재어 확인해요."],"variant_rule":{"alt":[{"stem":"「어림하기」는 무엇인가요?","options":[{"t":"자 없이 길이를 짐작하는 것","correct":true},{"t":"자로 정확히 재는 것","mis":"M3-1-u5-X07"},{"t":"길이를 더하는 것","mis":"M3-1-u5-X20"},{"t":"단위를 바꾸는 것","mis":"M3-1-u5-X20"}],"explanation":["어림은 자 없이 길이를 짐작하는 거예요.","어림한 길이는 「약 ○○」으로 나타내요.","엄지 너비(약 1 cm)로 짐작하고 자로 재어 확인해요."],"asset":null},{"stem":"엄지손가락 너비는 약 얼마인가요?","options":[{"t":"약 1 cm","correct":true},{"t":"약 1 mm","mis":"M3-1-u5-X06"},{"t":"약 10 cm","mis":"M3-1-u5-X01"},{"t":"약 1 m","mis":"M3-1-u5-X06"}],"explanation":["어림은 자 없이 길이를 짐작하는 거예요.","어림한 길이는 「약 ○○」으로 나타내요.","엄지 너비(약 1 cm)로 짐작하고 자로 재어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#4','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',1,'mc','auto','씨앗의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?',ARRAY['M3-1-u5-X04','M3-1-u5-X03']::text[],true,'{"seq":4,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"씨앗의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?","options":[{"t":"8 cm 3 mm","correct":true},{"t":"3 cm 8 mm","mis":"M3-1-u5-X04"},{"t":"83 cm","mis":"M3-1-u5-X04"},{"t":"8 cm 30 mm","mis":"M3-1-u5-X03"}],"explanation":["큰 눈금 숫자를 먼저 읽어요 — 8 cm.","그다음 작은 눈금 3칸 — 3 mm.","씨앗의 길이는 8 cm 3 mm예요."],"asset":{"type":"mmruler","len":83,"label":"씨앗"},"variant_rule":{"alt":[{"stem":"나뭇잎의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?","options":[{"t":"7 cm 2 mm","correct":true},{"t":"2 cm 7 mm","mis":"M3-1-u5-X04"},{"t":"72 cm","mis":"M3-1-u5-X04"},{"t":"7 cm 20 mm","mis":"M3-1-u5-X03"}],"explanation":["큰 눈금 숫자를 먼저 읽어요 — 7 cm.","그다음 작은 눈금 2칸 — 2 mm.","나뭇잎의 길이는 7 cm 2 mm예요."],"asset":{"type":"mmruler","len":72,"label":"나뭇잎"}},{"stem":"솔방울의 길이를 몇 cm 몇 mm로 나타내면 얼마인가요?","options":[{"t":"5 cm 9 mm","correct":true},{"t":"9 cm 5 mm","mis":"M3-1-u5-X04"},{"t":"59 cm","mis":"M3-1-u5-X04"},{"t":"5 cm 90 mm","mis":"M3-1-u5-X03"}],"explanation":["큰 눈금 숫자를 먼저 읽어요 — 5 cm.","그다음 작은 눈금 9칸 — 9 mm.","솔방울의 길이는 5 cm 9 mm예요."],"asset":{"type":"mmruler","len":59,"label":"솔방울"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#5','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',2,'mc','auto','색연필의 길이는 약 15 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":5,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"색연필의 길이는 약 15 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"cm","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","색연필의 길이는 약 15 cm가 알맞아요."],"variant_rule":{"alt":[{"stem":"지우개의 길이는 약 4 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"cm","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","지우개의 길이는 약 4 cm가 알맞아요."],"asset":null},{"stem":"동전의 두께는 약 2 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"mm","correct":true},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","동전의 두께는 약 2 mm가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#6','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',2,'ox','auto','지유는 발 길이를 약 220 cm라고 했어요. 알맞게 어림했어요.',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":6,"concept":"M3-1-u5-C3","difficulty":2,"kind":"ox","stem":"지유는 발 길이를 약 220 cm라고 했어요. 알맞게 어림했어요.","answer":"X","reason_options":[{"t":"발 길이는 약 220 mm가 알맞아서","correct":true},{"t":"수만 맞으면 단위는 상관없어서","mis":"M3-1-u5-X06"}],"mis":"M3-1-u5-X06","explanation":["발 길이의 크기를 떠올려요.","약 220 cm는 너무 길어요.","발 길이는 약 220 mm가 알맞아요."],"variant_rule":{"alt":[{"stem":"은우는 씨앗의 길이를 약 8 cm라고 했어요. 알맞게 어림했어요.","answer":"X","reason_options":[{"t":"씨앗의 길이는 약 8 mm가 알맞아서","correct":true},{"t":"수만 맞으면 단위는 상관없어서","mis":"M3-1-u5-X06"}],"explanation":["씨앗의 길이의 크기를 떠올려요.","약 8 cm는 너무 길어요.","씨앗의 길이는 약 8 mm가 알맞아요."],"asset":null},{"stem":"하랑은 지우개의 길이를 약 4 mm라고 했어요. 알맞게 어림했어요.","answer":"X","reason_options":[{"t":"지우개의 길이는 약 4 cm가 알맞아서","correct":true},{"t":"수만 맞으면 단위는 상관없어서","mis":"M3-1-u5-X06"}],"explanation":["지우개의 길이의 크기를 떠올려요.","약 4 mm는 너무 짧아요.","지우개의 길이는 약 4 cm가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#7','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',2,'ox','auto','길이를 어림할 때는 꼭 자로 정확히 재야 해요.',ARRAY['M3-1-u5-X07']::text[],true,'{"seq":7,"concept":"M3-1-u5-C3","difficulty":2,"kind":"ox","stem":"길이를 어림할 때는 꼭 자로 정확히 재야 해요.","answer":"X","reason_options":[{"t":"어림은 자 없이 짐작하는 것이라서","correct":true},{"t":"정확하지 않으면 어림이 아니라서","mis":"M3-1-u5-X07"}],"mis":"M3-1-u5-X07","explanation":["어림은 자 없이 길이를 짐작하는 거예요.","아는 길이(엄지 약 1 cm, 클립 약 3 cm)를 이용해요.","어림한 길이는 「약 ○○」 — 자로 재어 확인해요."],"variant_rule":{"alt":[{"stem":"어림한 길이는 앞에 「약」을 붙여 말해요.","answer":"O","reason_options":[{"t":"짐작한 길이라 정확한 길이와 다를 수 있어서","correct":true},{"t":"「약」은 아무 때나 붙이는 말이라서","mis":"M3-1-u5-X07"}],"explanation":["어림은 자 없이 길이를 짐작하는 거예요.","아는 길이(엄지 약 1 cm, 클립 약 3 cm)를 이용해요.","어림한 길이는 「약 ○○」 — 자로 재어 확인해요."],"asset":null},{"stem":"엄지손가락 너비(약 1 cm)를 이용해 길이를 어림할 수 있어요.","answer":"O","reason_options":[{"t":"아는 길이가 몇 번 들어가는지로 짐작할 수 있어서","correct":true},{"t":"몸으로는 길이를 짐작할 수 없어서","mis":"M3-1-u5-X07"}],"explanation":["어림은 자 없이 길이를 짐작하는 거예요.","아는 길이(엄지 약 1 cm, 클립 약 3 cm)를 이용해요.","어림한 길이는 「약 ○○」 — 자로 재어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#8','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',2,'mc','auto','씨앗의 길이는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X05','M3-1-u5-X04']::text[],true,'{"seq":8,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"씨앗의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"2 cm 7 mm","correct":true},{"t":"4 cm 7 mm","mis":"M3-1-u5-X05"},{"t":"3 cm 7 mm","mis":"M3-1-u5-X05"},{"t":"7 cm 2 mm","mis":"M3-1-u5-X04"}],"explanation":["씨앗의 왼쪽 끝이 2에 있어요 — 0이 아니에요.","2에서 4 cm 7 mm 눈금까지 큰 눈금 2칸·작은 눈금 7칸.","길이는 2 cm 7 mm = 27 mm예요."],"asset":{"type":"mmruler","len":27,"label":"씨앗","s":2},"variant_rule":{"alt":[{"stem":"나뭇잎의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 3 mm","correct":true},{"t":"3 cm 3 mm","mis":"M3-1-u5-X05"},{"t":"2 cm 3 mm","mis":"M3-1-u5-X05"},{"t":"3 cm 1 mm","mis":"M3-1-u5-X04"}],"explanation":["나뭇잎의 왼쪽 끝이 2에 있어요 — 0이 아니에요.","2에서 3 cm 3 mm 눈금까지 큰 눈금 1칸·작은 눈금 3칸.","길이는 1 cm 3 mm = 13 mm예요."],"asset":{"type":"mmruler","len":13,"label":"나뭇잎","s":2}},{"stem":"솔방울의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"6 cm 5 mm","correct":true},{"t":"9 cm 5 mm","mis":"M3-1-u5-X05"},{"t":"7 cm 5 mm","mis":"M3-1-u5-X05"},{"t":"5 cm 6 mm","mis":"M3-1-u5-X04"}],"explanation":["솔방울의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 9 cm 5 mm 눈금까지 큰 눈금 6칸·작은 눈금 5칸.","길이는 6 cm 5 mm = 65 mm예요."],"asset":{"type":"mmruler","len":65,"label":"솔방울","s":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#9','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',2,'mc','auto','엄지손가락 너비는 약 1 cm예요. 엄지가 13번쯤 들어가는 막대의 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X01','M3-1-u5-X21']::text[],true,'{"seq":9,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 13번쯤 들어가는 막대의 길이는 약 얼마인가요?","options":[{"t":"약 13 cm","correct":true},{"t":"약 13 mm","mis":"M3-1-u5-X06"},{"t":"약 130 cm","mis":"M3-1-u5-X01"},{"t":"약 23 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","13번이면 약 13 cm.","어림한 길이라 앞에 「약」을 붙여 약 13 cm라고 해요."],"variant_rule":{"alt":[{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 19번쯤 들어가는 사인펜의 길이는 약 얼마인가요?","options":[{"t":"약 19 cm","correct":true},{"t":"약 19 mm","mis":"M3-1-u5-X06"},{"t":"약 190 cm","mis":"M3-1-u5-X01"},{"t":"약 29 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","19번이면 약 19 cm.","어림한 길이라 앞에 「약」을 붙여 약 19 cm라고 해요."],"asset":null},{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 15번쯤 들어가는 필통의 길이는 약 얼마인가요?","options":[{"t":"약 15 cm","correct":true},{"t":"약 15 mm","mis":"M3-1-u5-X06"},{"t":"약 150 cm","mis":"M3-1-u5-X01"},{"t":"약 25 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","15번이면 약 15 cm.","어림한 길이라 앞에 「약」을 붙여 약 15 cm라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_basic#10','math',3,1,'u5','L03','g3_1_math_u5_L03_basic','lesson_basic','M3-1-u5-C3',3,'error','auto','길이의 단위를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C3","difficulty":3,"kind":"error","stem":"길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「발 길이는 약 220 cm야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"시우 — 「나뭇잎의 길이는 약 9 cm야」","mis":"M3-1-u5-X20"},{"t":"하린 — 「필통의 길이는 약 20 cm야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","발 길이는 약 220 mm가 알맞아요.","하은은 cm를 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「콩 한 알의 길이는 약 7 cm야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"지유 — 「3학년 친구의 키는 약 135 cm야」","mis":"M3-1-u5-X20"},{"t":"은우 — 「필통의 길이는 약 20 cm야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","콩 한 알의 길이는 약 7 mm가 알맞아요.","도윤은 cm를 잘못 썼어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「나뭇잎의 길이는 약 9 m야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"태오 — 「개미의 몸길이는 약 5 mm야」","mis":"M3-1-u5-X20"},{"t":"하린 — 「색연필의 길이는 약 15 cm야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","나뭇잎의 길이는 약 9 cm가 알맞아요.","도윤은 m를 잘못 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#1','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',2,'sa','auto','가위의 길이를 약 15 cm로 어림했어요. 자로 재었더니 15 cm 5 mm였어요. 어림한 길이와 잰 길이의 차는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u5-C3","difficulty":2,"kind":"sa","stem":"가위의 길이를 약 15 cm로 어림했어요. 자로 재었더니 15 cm 5 mm였어요. 어림한 길이와 잰 길이의 차는 몇 mm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["어림한 길이 약 15 cm, 잰 길이 15 cm 5 mm.","15 cm는 같고 5 mm만 달라요.","차는 5 mm — 아주 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"풀의 길이를 약 12 cm로 어림했어요. 자로 재었더니 12 cm 2 mm였어요. 어림한 길이와 잰 길이의 차는 몇 mm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["어림한 길이 약 12 cm, 잰 길이 12 cm 2 mm.","12 cm는 같고 2 mm만 달라요.","차는 2 mm — 아주 가깝게 어림했어요."],"asset":null},{"stem":"사인펜의 길이를 약 18 cm로 어림했어요. 자로 재었더니 18 cm 8 mm였어요. 어림한 길이와 잰 길이의 차는 몇 mm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["어림한 길이 약 18 cm, 잰 길이 18 cm 8 mm.","18 cm는 같고 8 mm만 달라요.","차는 8 mm — 아주 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#2','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',2,'mc','auto','씨앗의 길이는 약 8 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":2,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"씨앗의 길이는 약 8 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"mm","correct":true},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","씨앗의 길이는 약 8 mm가 알맞아요."],"variant_rule":{"alt":[{"stem":"공책의 긴 쪽은 약 26 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"cm","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","공책의 긴 쪽은 약 26 cm가 알맞아요."],"asset":null},{"stem":"책상의 높이는 약 70 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"cm","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","책상의 높이는 약 70 cm가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#3','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',3,'mc','auto','실제 길이가 7 cm 9 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-1-u5-X05','M3-1-u5-X20']::text[],true,'{"seq":3,"concept":"M3-1-u5-C3","difficulty":3,"kind":"mc","stem":"실제 길이가 7 cm 9 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"서윤(약 8 cm)","correct":true},{"t":"은우(약 10 cm)","mis":"M3-1-u5-X05"},{"t":"지유(약 5 cm)","mis":"M3-1-u5-X20"},{"t":"하린(약 9 cm)","mis":"M3-1-u5-X05"}],"explanation":["실제 길이 7 cm 9 mm = 79 mm예요.","약 10 cm는 21 mm 차이, 약 5 cm는 29 mm 차이, 약 9 cm는 11 mm 차이, 약 8 cm는 1 mm 차이.","차이가 가장 작은 서윤이 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"실제 길이가 9 cm 9 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"지유(약 10 cm)","correct":true},{"t":"하은(약 11 cm)","mis":"M3-1-u5-X05"},{"t":"태오(약 7 cm)","mis":"M3-1-u5-X20"},{"t":"민준(약 12 cm)","mis":"M3-1-u5-X05"}],"explanation":["실제 길이 9 cm 9 mm = 99 mm예요.","약 11 cm는 11 mm 차이, 약 7 cm는 29 mm 차이, 약 10 cm는 1 mm 차이, 약 12 cm는 21 mm 차이.","차이가 가장 작은 지유가 가장 가깝게 어림했어요."],"asset":null},{"stem":"실제 길이가 12 cm 8 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"민준(약 14 cm)","correct":true},{"t":"하린(약 15 cm)","mis":"M3-1-u5-X05"},{"t":"지유(약 11 cm)","mis":"M3-1-u5-X05"},{"t":"시우(약 10 cm)","mis":"M3-1-u5-X20"}],"explanation":["실제 길이 12 cm 8 mm = 128 mm예요.","약 15 cm는 22 mm 차이, 약 11 cm는 18 mm 차이, 약 10 cm는 28 mm 차이, 약 14 cm는 12 mm 차이.","차이가 가장 작은 민준이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#4','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',3,'sa','auto','씨앗의 길이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u5-C3","difficulty":3,"kind":"sa","stem":"씨앗의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["씨앗의 왼쪽 끝이 1에 있어요 — 0이 아니에요.","1에서 5 cm 6 mm 눈금까지 큰 눈금 4칸·작은 눈금 6칸.","길이는 4 cm 6 mm = 46 mm예요."],"asset":{"type":"mmruler","len":46,"label":"씨앗","s":1},"variant_rule":{"alt":[{"stem":"나뭇잎의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["나뭇잎의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 8 cm 4 mm 눈금까지 큰 눈금 5칸·작은 눈금 4칸.","길이는 5 cm 4 mm = 54 mm예요."],"asset":{"type":"mmruler","len":54,"label":"나뭇잎","s":3}},{"stem":"솔방울의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["솔방울의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 7 cm 8 mm 눈금까지 큰 눈금 4칸·작은 눈금 8칸.","길이는 4 cm 8 mm = 48 mm예요."],"asset":{"type":"mmruler","len":48,"label":"솔방울","s":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#5','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',3,'mc','auto','약 12 cm인 색연필과 약 4 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X03','M3-1-u5-X06']::text[],true,'{"seq":5,"concept":"M3-1-u5-C3","difficulty":3,"kind":"mc","stem":"약 12 cm인 색연필과 약 4 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?","options":[{"t":"약 16 cm","correct":true},{"t":"약 8 cm","mis":"M3-1-u5-X20"},{"t":"약 124 cm","mis":"M3-1-u5-X03"},{"t":"약 16 mm","mis":"M3-1-u5-X06"}],"explanation":["길이를 아는 물건을 이어 붙여 어림해요.","약 12 cm + 약 4 cm.","이은 길이는 약 16 cm예요."],"variant_rule":{"alt":[{"stem":"약 10 cm인 색연필과 약 5 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?","options":[{"t":"약 15 cm","correct":true},{"t":"약 5 cm","mis":"M3-1-u5-X20"},{"t":"약 105 cm","mis":"M3-1-u5-X03"},{"t":"약 15 mm","mis":"M3-1-u5-X06"}],"explanation":["길이를 아는 물건을 이어 붙여 어림해요.","약 10 cm + 약 5 cm.","이은 길이는 약 15 cm예요."],"asset":null},{"stem":"약 15 cm인 색연필과 약 5 cm인 클립을 이어 놓았어요. 이은 길이는 약 얼마인가요?","options":[{"t":"약 20 cm","correct":true},{"t":"약 10 cm","mis":"M3-1-u5-X20"},{"t":"약 155 cm","mis":"M3-1-u5-X03"},{"t":"약 20 mm","mis":"M3-1-u5-X06"}],"explanation":["길이를 아는 물건을 이어 붙여 어림해요.","약 15 cm + 약 5 cm.","이은 길이는 약 20 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#6','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',3,'error','auto','길이의 단위를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X20']::text[],true,'{"seq":6,"concept":"M3-1-u5-C3","difficulty":3,"kind":"error","stem":"길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「3학년 친구의 키는 약 135 m야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"시우 — 「씨앗의 길이는 약 8 mm야」","mis":"M3-1-u5-X20"},{"t":"지유 — 「콩 한 알의 길이는 약 7 mm야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","3학년 친구의 키는 약 135 cm가 알맞아요.","태오는 m를 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「지우개의 길이는 약 4 m야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"도윤 — 「씨앗의 길이는 약 8 mm야」","mis":"M3-1-u5-X20"},{"t":"하은 — 「콩 한 알의 길이는 약 7 mm야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","지우개의 길이는 약 4 cm가 알맞아요.","서윤은 m를 잘못 썼어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「책상의 높이는 약 70 m야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"민준 — 「3학년 친구의 키는 약 135 cm야」","mis":"M3-1-u5-X20"},{"t":"도윤 — 「발 길이는 약 220 mm야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","책상의 높이는 약 70 cm가 알맞아요.","하린은 m를 잘못 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#7','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',3,'mc','auto','가장 긴 것은 어느 것인가요?',ARRAY['M3-1-u5-X02','M3-1-u5-X06']::text[],true,'{"seq":7,"concept":"M3-1-u5-C3","difficulty":3,"kind":"mc","stem":"가장 긴 것은 어느 것인가요?","options":[{"t":"지우개의 길이 약 4 cm","correct":true},{"t":"개미의 몸길이 약 5 mm","mis":"M3-1-u5-X02"},{"t":"동전의 두께 약 2 mm","mis":"M3-1-u5-X02"},{"t":"콩 한 알의 길이 약 7 mm","mis":"M3-1-u5-X06"}],"explanation":["단위를 mm로 맞춰 견주어요.","개미의 몸길이 약 5 mm, 동전의 두께 약 2 mm, 지우개의 길이 약 40 mm, 콩 한 알의 길이 약 7 mm.","가장 긴 것은 지우개의 길이 — 수가 크다고 가장 긴 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 가장 긴 것은 어느 것인가요?","options":[{"t":"지우개의 길이 약 4 cm","correct":true},{"t":"개미의 몸길이 약 5 mm","mis":"M3-1-u5-X02"},{"t":"씨앗의 길이 약 8 mm","mis":"M3-1-u5-X06"},{"t":"동전의 두께 약 2 mm","mis":"M3-1-u5-X02"}],"explanation":["단위를 mm로 맞춰 견주어요.","지우개의 길이 약 40 mm, 개미의 몸길이 약 5 mm, 씨앗의 길이 약 8 mm, 동전의 두께 약 2 mm.","가장 긴 것은 지우개의 길이 — 수가 크다고 가장 긴 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 가장 긴 것은 어느 것인가요?","options":[{"t":"지우개의 길이 약 4 cm","correct":true},{"t":"씨앗의 길이 약 8 mm","mis":"M3-1-u5-X02"},{"t":"새끼손톱의 너비 약 9 mm","mis":"M3-1-u5-X06"},{"t":"개미의 몸길이 약 5 mm","mis":"M3-1-u5-X02"}],"explanation":["단위를 mm로 맞춰 견주어요.","씨앗의 길이 약 8 mm, 새끼손톱의 너비 약 9 mm, 개미의 몸길이 약 5 mm, 지우개의 길이 약 40 mm.","가장 긴 것은 지우개의 길이 — 수가 크다고 가장 긴 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#8','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',4,'essay','teacher','사인펜의 길이를 자 없이 어림하는 방법을 두 가지 쓰고, 어림한 길이는 어떻게 말해야 하는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C3","difficulty":4,"kind":"essay","stem":"사인펜의 길이를 자 없이 어림하는 방법을 두 가지 쓰고, 어림한 길이는 어떻게 말해야 하는지 써 보세요.","answer_guide":{"answer":"예: ① 엄지손가락 너비(약 1 cm)가 몇 번 들어가는지 센다 — 15번쯤이면 약 15 cm. ② 길이를 아는 물건(약 7 cm 색연필, 약 3 cm 클립)을 이어 붙여 견준다. 어림한 길이는 앞에 「약」을 붙여 「약 15 cm」라고 말한다.","scoring_points":["엄지 너비로 어림하는 방법을 썼는가","아는 길이를 이어 붙이는 방법을 썼는가","「약」을 붙인다고 썼는가"]},"explanation":["엄지 너비 약 1 cm로 세어요.","아는 길이를 이어 붙여 견주어요.","어림한 길이는 「약 ○○」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#9','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',4,'essay','teacher','지유가 「내 발 길이는 약 220 cm야.」라고 했어요. 지유의 말이 알맞은지 판단하고, 바른 단위를 써서 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C3","difficulty":4,"kind":"essay","stem":"지유가 「내 발 길이는 약 220 cm야.」라고 했어요. 지유의 말이 알맞은지 판단하고, 바른 단위를 써서 고쳐 보세요.","answer_guide":{"answer":"예: 알맞지 않다. 220 cm는 2 m 20 cm로 어른 키보다 훨씬 길다. 발 길이는 mm로 나타내야 알맞으므로 「내 발 길이는 약 220 mm야.」라고 고친다(약 22 cm).","scoring_points":["알맞지 않다고 판단했는가","220 cm가 너무 긴 까닭을 썼는가","약 220 mm(약 22 cm)로 고쳤는가"]},"explanation":["220 cm는 2 m 20 cm예요.","발 길이는 작은 단위 mm로.","약 220 mm = 약 22 cm."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L03_challenge#10','math',3,1,'u5','L03','g3_1_math_u5_L03_challenge','lesson_challenge','M3-1-u5-C3',4,'mc','auto','실제 길이가 10 cm 9 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?',ARRAY['M3-1-u5-X05','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C3","difficulty":4,"kind":"mc","stem":"실제 길이가 10 cm 9 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"하은(약 10 cm)","correct":true},{"t":"민준(약 13 cm)","mis":"M3-1-u5-X05"},{"t":"은우(약 8 cm)","mis":"M3-1-u5-X20"},{"t":"시우(약 9 cm)","mis":"M3-1-u5-X05"}],"explanation":["실제 길이 10 cm 9 mm = 109 mm예요.","약 13 cm는 21 mm 차이, 약 8 cm는 29 mm 차이, 약 10 cm는 9 mm 차이, 약 9 cm는 19 mm 차이.","차이가 가장 작은 하은이 가장 가깝게 어림했어요."],"variant_rule":{"alt":[{"stem":"실제 길이가 12 cm 6 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"태오(약 13 cm)","correct":true},{"t":"하은(약 10 cm)","mis":"M3-1-u5-X20"},{"t":"민준(약 15 cm)","mis":"M3-1-u5-X05"},{"t":"도윤(약 11 cm)","mis":"M3-1-u5-X05"}],"explanation":["실제 길이 12 cm 6 mm = 126 mm예요.","약 10 cm는 26 mm 차이, 약 15 cm는 24 mm 차이, 약 11 cm는 16 mm 차이, 약 13 cm는 4 mm 차이.","차이가 가장 작은 태오가 가장 가깝게 어림했어요."],"asset":null},{"stem":"실제 길이가 6 cm 3 mm인 나뭇잎을 네 친구가 어림했어요. 가장 가깝게 어림한 친구는 누구인가요?","options":[{"t":"하린(약 6 cm)","correct":true},{"t":"민준(약 9 cm)","mis":"M3-1-u5-X20"},{"t":"은우(약 4 cm)","mis":"M3-1-u5-X05"},{"t":"하랑(약 5 cm)","mis":"M3-1-u5-X05"}],"explanation":["실제 길이 6 cm 3 mm = 63 mm예요.","약 9 cm는 27 mm 차이, 약 4 cm는 23 mm 차이, 약 6 cm는 3 mm 차이, 약 5 cm는 13 mm 차이.","차이가 가장 작은 하린이 가장 가깝게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L04_basic#1','math',3,1,'u5','L04','g3_1_math_u5_L04_basic','lesson_basic','M3-1-u5-C4',1,'mc','auto','1000 m를 나타내는 더 큰 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X01']::text[],true,'{"seq":1,"concept":"M3-1-u5-C4","difficulty":1,"kind":"mc","stem":"1000 m를 나타내는 더 큰 단위는 어느 것인가요?","options":[{"t":"1 km","correct":true},{"t":"1 cm","mis":"M3-1-u5-X06"},{"t":"1 mm","mis":"M3-1-u5-X06"},{"t":"100 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m를 1 km라 쓰고 「1 킬로미터」라고 읽어요.","100 m가 10번이면 1000 m예요.","그래서 1 km = 1000 m예요."],"variant_rule":{"alt":[{"stem":"1 km는 몇 m인가요?","options":[{"t":"1000 m","correct":true},{"t":"100 m","mis":"M3-1-u5-X01"},{"t":"10 m","mis":"M3-1-u5-X01"},{"t":"500 m","mis":"M3-1-u5-X21"}],"explanation":["1000 m를 1 km라 쓰고 「1 킬로미터」라고 읽어요.","100 m가 10번이면 1000 m예요.","그래서 1 km = 1000 m예요."],"asset":null},{"stem":"「3 km」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"3 킬로미터","correct":true},{"t":"3 미터","mis":"M3-1-u5-X01"},{"t":"3 밀리미터","mis":"M3-1-u5-X06"},{"t":"3 센티미터","mis":"M3-1-u5-X06"}],"explanation":["1000 m를 1 km라 쓰고 「1 킬로미터」라고 읽어요.","100 m가 10번이면 1000 m예요.","그래서 1 km = 1000 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
