INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L04_challenge#6','math',3,1,'u5','L04','g3_1_math_u5_L04_challenge','lesson_challenge','M3-1-u5-C4',3,'sa','auto','학교에서 도서관까지는 1 km 50 m, 공원까지는 980 m예요. 도서관이 몇 m 더 먼가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u5-C4","difficulty":3,"kind":"sa","stem":"학교에서 도서관까지는 1 km 50 m, 공원까지는 980 m예요. 도서관이 몇 m 더 먼가요? 숫자로 쓰세요.","answer":["70"],"explanation":["단위를 m로 맞춰요 — 1 km 50 m = 1050 m예요.","1050 − 980 = 70.","도서관이 70 m 더 멀어요."],"variant_rule":{"alt":[{"stem":"학교에서 도서관까지는 1 km 55 m, 공원까지는 985 m예요. 도서관이 몇 m 더 먼가요? 숫자로 쓰세요.","answer":["70"],"explanation":["단위를 m로 맞춰요 — 1 km 55 m = 1055 m예요.","1055 − 985 = 70.","도서관이 70 m 더 멀어요."],"asset":null},{"stem":"학교에서 도서관까지는 1 km 45 m, 공원까지는 975 m예요. 도서관이 몇 m 더 먼가요? 숫자로 쓰세요.","answer":["70"],"explanation":["단위를 m로 맞춰요 — 1 km 45 m = 1045 m예요.","1045 − 975 = 70.","도서관이 70 m 더 멀어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L04_challenge#7','math',3,1,'u5','L04','g3_1_math_u5_L04_challenge','lesson_challenge','M3-1-u5-C4',3,'sa','auto','산책로 2 km 중에서 1920 m를 걸었어요. 남은 거리는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u5-C4","difficulty":3,"kind":"sa","stem":"산책로 2 km 중에서 1920 m를 걸었어요. 남은 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["2 km = 2000 m예요.","2000 − 1920 = 80.","남은 거리는 80 m예요."],"variant_rule":{"alt":[{"stem":"산책로 1 km 중에서 965 m를 걸었어요. 남은 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["1 km = 1000 m예요.","1000 − 965 = 35.","남은 거리는 35 m예요."],"asset":null},{"stem":"산책로 2 km 중에서 1940 m를 걸었어요. 남은 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["2 km = 2000 m예요.","2000 − 1940 = 60.","남은 거리는 60 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L04_challenge#8','math',3,1,'u5','L04','g3_1_math_u5_L04_challenge','lesson_challenge','M3-1-u5-C4',4,'essay','teacher','활주로의 길이는 3750 m예요. 이 길이를 몇 km 몇 m로 나타내는 방법을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C4","difficulty":4,"kind":"essay","stem":"활주로의 길이는 3750 m예요. 이 길이를 몇 km 몇 m로 나타내는 방법을 써 보세요.","answer_guide":{"answer":"예: 1000 m = 1 km이므로 3750 m를 1000 m 묶음 3개와 750 m로 나눈다. 3000 m = 3 km이므로 3750 m = 3 km 750 m이다.","scoring_points":["1000 m = 1 km를 썼는가","3000 m와 750 m로 나누었는가","3 km 750 m를 구했는가"]},"explanation":["1000 m = 1 km.","3750 m = 3000 m + 750 m.","3 km 750 m."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L04_challenge#9','math',3,1,'u5','L04','g3_1_math_u5_L04_challenge','lesson_challenge','M3-1-u5-C4',4,'essay','teacher','도윤이는 2 km 63 m를 263 m라고 했어요. 도윤이의 답이 맞는지 판단하고, 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C4","difficulty":4,"kind":"essay","stem":"도윤이는 2 km 63 m를 263 m라고 했어요. 도윤이의 답이 맞는지 판단하고, 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 틀렸다. 2 km는 2000 m이므로 2 km 63 m = 2000 m + 63 m = 2063 m이다. 263 m는 1 km도 안 되는 거리이다.","scoring_points":["틀렸다고 판단했는가","2 km = 2000 m로 설명했는가","2063 m로 고쳤는가"]},"explanation":["2 km = 2000 m.","2000 m + 63 m = 2063 m.","263 m는 1 km보다 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L04_challenge#10','math',3,1,'u5','L04','g3_1_math_u5_L04_challenge','lesson_challenge','M3-1-u5-C4',4,'sa','auto','한 바퀴가 250 m인 산책로를 몇 바퀴 돌면 2 km가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u5-C4","difficulty":4,"kind":"sa","stem":"한 바퀴가 250 m인 산책로를 몇 바퀴 돌면 2 km가 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["2 km = 2000 m예요.","250 m씩 더해 2000 m가 될 때까지 세어요.","8바퀴 — 250 m × 8 = 2000 m."],"variant_rule":{"alt":[{"stem":"한 바퀴가 250 m인 산책로를 몇 바퀴 돌면 1 km가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["1 km = 1000 m예요.","250 m씩 더해 1000 m가 될 때까지 세어요.","4바퀴 — 250 m × 4 = 1000 m."],"asset":null},{"stem":"한 바퀴가 500 m인 산책로를 몇 바퀴 돌면 2 km가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["2 km = 2000 m예요.","500 m씩 더해 2000 m가 될 때까지 세어요.","4바퀴 — 500 m × 4 = 2000 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#1','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',1,'mc','auto','지도에서 약 500 m인 거리가 2번 들어가는 곳까지의 거리는 약 얼마인가요?',ARRAY['M3-1-u5-X08']::text[],true,'{"seq":1,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"지도에서 약 500 m인 거리가 2번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km","correct":true},{"t":"약 2 km","mis":"M3-1-u5-X08"},{"t":"약 100 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m = 1000 m.","1000 m = 1 km — 어림한 거리라 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"지도에서 약 250 m인 거리가 4번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km","correct":true},{"t":"약 4 km","mis":"M3-1-u5-X08"},{"t":"약 100 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m = 1000 m.","1000 m = 1 km — 어림한 거리라 「약」을 붙여요."],"asset":null},{"stem":"지도에서 약 200 m인 거리가 5번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km","correct":true},{"t":"약 5 km","mis":"M3-1-u5-X08"},{"t":"약 100 m","mis":"M3-1-u5-X08"},{"t":"약 200 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 200 m가 몇 번 들어가는지 세어요.","200 m + 200 m + 200 m + 200 m + 200 m = 1000 m.","1000 m = 1 km — 어림한 거리라 「약」을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#2','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',1,'mc','auto','지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?',ARRAY['M3-1-u5-X08']::text[],true,'{"seq":2,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 3 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m + 500 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"지도에서 약 500 m인 거리가 5번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 2 km 500 m","correct":true},{"t":"약 5 km","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m + 500 m + 500 m + 500 m = 2500 m.","2500 m = 2 km 500 m — 어림한 거리라 「약」을 붙여요."],"asset":null},{"stem":"지도에서 약 250 m인 거리가 5번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 250 m","correct":true},{"t":"약 5 km","mis":"M3-1-u5-X08"},{"t":"약 125 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m = 1250 m.","1250 m = 1 km 250 m — 어림한 거리라 「약」을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#3','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',1,'mc','auto','한라산의 높이는 약 1950 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":3,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"한라산의 높이는 약 1950 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","한라산의 높이는 약 1950 m가 알맞아요."],"variant_rule":{"alt":[{"stem":"수영장의 길이는 약 25 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","수영장의 길이는 약 25 m가 알맞아요."],"asset":null},{"stem":"운동장 한 바퀴는 약 200 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","운동장 한 바퀴는 약 200 m가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#4','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',1,'mc','auto','서울에서 제주도까지의 거리는 약 460 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":4,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"서울에서 제주도까지의 거리는 약 460 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","서울에서 제주도까지의 거리는 약 460 km가 알맞아요."],"variant_rule":{"alt":[{"stem":"우리 동네에서 옆 도시까지의 거리는 약 15 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","우리 동네에서 옆 도시까지의 거리는 약 15 km가 알맞아요."],"asset":null},{"stem":"서울에서 부산까지의 거리는 약 400 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","서울에서 부산까지의 거리는 약 400 km가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#5','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',2,'mc','auto','1 km보다 짧은 것은 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":5,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"1 km보다 짧은 것은 어느 것인가요?","options":[{"t":"놀이터 한 바퀴의 길이","correct":true},{"t":"한라산의 높이","mis":"M3-1-u5-X06"},{"t":"서울에서 부산까지의 거리","mis":"M3-1-u5-X06"},{"t":"서울에서 제주도까지의 거리","mis":"M3-1-u5-X06"}],"explanation":["1 km = 1000 m — 운동장을 여러 바퀴 도는 거리예요.","놀이터 한 바퀴의 길이는 1000 m보다 훨씬 짧아요.","나머지는 모두 1 km보다 길어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 1 km보다 짧은 것은 어느 것인가요?","options":[{"t":"수영장의 길이","correct":true},{"t":"보령 해저 터널의 길이","mis":"M3-1-u5-X06"},{"t":"한라산의 높이","mis":"M3-1-u5-X06"},{"t":"서울에서 부산까지의 거리","mis":"M3-1-u5-X06"}],"explanation":["1 km = 1000 m — 운동장을 여러 바퀴 도는 거리예요.","수영장의 길이는 1000 m보다 훨씬 짧아요.","나머지는 모두 1 km보다 길어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 1 km보다 짧은 것은 어느 것인가요?","options":[{"t":"운동장 한 바퀴의 길이","correct":true},{"t":"마라톤 경기의 거리","mis":"M3-1-u5-X06"},{"t":"보령 해저 터널의 길이","mis":"M3-1-u5-X06"},{"t":"서울에서 부산까지의 거리","mis":"M3-1-u5-X06"}],"explanation":["1 km = 1000 m — 운동장을 여러 바퀴 도는 거리예요.","운동장 한 바퀴의 길이는 1000 m보다 훨씬 짧아요.","나머지는 모두 1 km보다 길어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#6','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',2,'mc','auto','세계 온실까지의 거리는 약 1500 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":6,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"세계 온실까지의 거리는 약 1500 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","세계 온실까지의 거리는 약 1500 m가 알맞아요."],"variant_rule":{"alt":[{"stem":"서울에서 제주도까지의 거리는 약 460 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","서울에서 제주도까지의 거리는 약 460 km가 알맞아요."],"asset":null},{"stem":"기차의 길이는 약 300 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","기차의 길이는 약 300 m가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#7','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',2,'ox','auto','지유는 세계 온실까지의 거리를 약 1500 km라고 했어요. 알맞게 어림했어요.',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":7,"concept":"M3-1-u5-C5","difficulty":2,"kind":"ox","stem":"지유는 세계 온실까지의 거리를 약 1500 km라고 했어요. 알맞게 어림했어요.","answer":"X","reason_options":[{"t":"세계 온실까지의 거리는 약 1500 m가 알맞아서","correct":true},{"t":"수만 맞으면 단위는 상관없어서","mis":"M3-1-u5-X06"}],"mis":"M3-1-u5-X06","explanation":["세계 온실까지의 거리의 크기를 떠올려요.","약 1500 km는 너무 길어요.","세계 온실까지의 거리는 약 1500 m가 알맞아요."],"variant_rule":{"alt":[{"stem":"하랑은 마라톤 경기의 거리를 약 42 m라고 했어요. 알맞게 어림했어요.","answer":"X","reason_options":[{"t":"마라톤 경기의 거리는 약 42 km가 알맞아서","correct":true},{"t":"수만 맞으면 단위는 상관없어서","mis":"M3-1-u5-X06"}],"explanation":["마라톤 경기의 거리의 크기를 떠올려요.","약 42 m는 너무 짧아요.","마라톤 경기의 거리는 약 42 km가 알맞아요."],"asset":null},{"stem":"은우는 기차의 길이를 약 300 km라고 했어요. 알맞게 어림했어요.","answer":"X","reason_options":[{"t":"기차의 길이는 약 300 m가 알맞아서","correct":true},{"t":"수만 맞으면 단위는 상관없어서","mis":"M3-1-u5-X06"}],"explanation":["기차의 길이의 크기를 떠올려요.","약 300 km는 너무 길어요.","기차의 길이는 약 300 m가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#8','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',2,'mc','auto','운동장 한 바퀴가 약 50 m예요. 20바퀴를 돌면 약 얼마를 걷게 되나요?',ARRAY['M3-1-u5-X02','M3-1-u5-X08','M3-1-u5-X01']::text[],true,'{"seq":8,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"운동장 한 바퀴가 약 50 m예요. 20바퀴를 돌면 약 얼마를 걷게 되나요?","options":[{"t":"약 1 km","correct":true},{"t":"약 70 m","mis":"M3-1-u5-X02"},{"t":"약 100 m","mis":"M3-1-u5-X08"},{"t":"약 20 km","mis":"M3-1-u5-X01"}],"explanation":["약 50 m씩 20번이에요.","50 × 20 = 1000 — 약 1000 m.","1000 m = 1 km — 약 1 km예요."],"variant_rule":{"alt":[{"stem":"운동장 한 바퀴가 약 100 m예요. 10바퀴를 돌면 약 얼마를 걷게 되나요?","options":[{"t":"약 1 km","correct":true},{"t":"약 110 m","mis":"M3-1-u5-X02"},{"t":"약 200 m","mis":"M3-1-u5-X08"},{"t":"약 10 km","mis":"M3-1-u5-X01"}],"explanation":["약 100 m씩 10번이에요.","100 × 10 = 1000 — 약 1000 m.","1000 m = 1 km — 약 1 km예요."],"asset":null},{"stem":"운동장 한 바퀴가 약 200 m예요. 5바퀴를 돌면 약 얼마를 걷게 되나요?","options":[{"t":"약 1 km","correct":true},{"t":"약 205 m","mis":"M3-1-u5-X02"},{"t":"약 400 m","mis":"M3-1-u5-X08"},{"t":"약 5 km","mis":"M3-1-u5-X01"}],"explanation":["약 200 m씩 5번이에요.","200 × 5 = 1000 — 약 1000 m.","1000 m = 1 km — 약 1 km예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#9','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',2,'match','auto','대상과 길이를 나타내기에 알맞은 단위를 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u5-C5","difficulty":2,"kind":"match","stem":"대상과 길이를 나타내기에 알맞은 단위를 이으세요.","pairs":[{"l":"새끼손톱의 너비","r":"mm"},{"l":"책상의 높이","r":"cm"},{"l":"한라산의 높이","r":"m"},{"l":"서울에서 제주도까지의 거리","r":"km"}],"mis":"M3-1-u5-X06","explanation":["작은 것부터 큰 것까지 mm·cm·m·km 차례예요.","새끼손톱의 너비 — mm, 책상의 높이 — cm, 한라산의 높이 — m, 서울에서 제주도까지의 거리 — km.","대상의 크기를 떠올려 단위를 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 대상과 길이를 나타내기에 알맞은 단위를 이으세요.","pairs":[{"l":"개미의 몸길이","r":"mm"},{"l":"필통의 길이","r":"cm"},{"l":"수영장의 길이","r":"m"},{"l":"마라톤 경기의 거리","r":"km"}],"explanation":["작은 것부터 큰 것까지 mm·cm·m·km 차례예요.","개미의 몸길이 — mm, 필통의 길이 — cm, 수영장의 길이 — m, 마라톤 경기의 거리 — km.","대상의 크기를 떠올려 단위를 골라요."],"asset":null},{"stem":"이번에는 다른 문제예요. 대상과 길이를 나타내기에 알맞은 단위를 이으세요.","pairs":[{"l":"동전의 두께","r":"mm"},{"l":"공책의 긴 쪽","r":"cm"},{"l":"나무의 높이","r":"m"},{"l":"보령 해저 터널의 길이","r":"km"}],"explanation":["작은 것부터 큰 것까지 mm·cm·m·km 차례예요.","동전의 두께 — mm, 공책의 긴 쪽 — cm, 나무의 높이 — m, 보령 해저 터널의 길이 — km.","대상의 크기를 떠올려 단위를 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_basic#10','math',3,1,'u5','L05','g3_1_math_u5_L05_basic','lesson_basic','M3-1-u5-C5',3,'error','auto','길이의 단위를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C5","difficulty":3,"kind":"error","stem":"길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「한라산의 높이는 약 1950 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"도윤 — 「수영장의 길이는 약 25 m야」","mis":"M3-1-u5-X20"},{"t":"태오 — 「세계 온실까지의 거리는 약 1500 m야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","한라산의 높이는 약 1950 m가 알맞아요.","은우는 km를 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「운동장 한 바퀴는 약 200 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"도윤 — 「기차의 길이는 약 300 m야」","mis":"M3-1-u5-X20"},{"t":"서윤 — 「서울에서 부산까지의 거리는 약 400 km야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","운동장 한 바퀴는 약 200 m가 알맞아요.","하린은 km를 잘못 썼어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「세계 온실까지의 거리는 약 1500 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"태오 — 「교실 긴 쪽의 길이는 약 9 m야」","mis":"M3-1-u5-X20"},{"t":"하린 — 「서울에서 제주도까지의 거리는 약 460 km야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","세계 온실까지의 거리는 약 1500 m가 알맞아요.","하랑은 km를 잘못 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#1','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',2,'mc','auto','지도에서 약 250 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?',ARRAY['M3-1-u5-X08']::text[],true,'{"seq":1,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"지도에서 약 250 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 6 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m + 250 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"지도에서 약 200 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 200 m","correct":true},{"t":"약 6 km","mis":"M3-1-u5-X08"},{"t":"약 120 m","mis":"M3-1-u5-X08"},{"t":"약 200 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 200 m가 몇 번 들어가는지 세어요.","200 m + 200 m + 200 m + 200 m + 200 m + 200 m = 1200 m.","1200 m = 1 km 200 m — 어림한 거리라 「약」을 붙여요."],"asset":null},{"stem":"지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 3 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m + 500 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#2','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',2,'mc','auto','1 km보다 긴 것은 어느 것인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X06']::text[],true,'{"seq":2,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"1 km보다 긴 것은 어느 것인가요?","options":[{"t":"보령 해저 터널의 길이","correct":true},{"t":"교실 긴 쪽의 길이","mis":"M3-1-u5-X20"},{"t":"운동장 한 바퀴의 길이","mis":"M3-1-u5-X06"},{"t":"수영장의 길이","mis":"M3-1-u5-X06"}],"explanation":["1 km = 1000 m예요.","보령 해저 터널의 길이는 1000 m보다 길어요.","나머지는 모두 1 km보다 짧아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 1 km보다 긴 것은 어느 것인가요?","options":[{"t":"마라톤 경기의 거리","correct":true},{"t":"수영장의 길이","mis":"M3-1-u5-X20"},{"t":"운동장 한 바퀴의 길이","mis":"M3-1-u5-X06"},{"t":"기차 한 대의 길이","mis":"M3-1-u5-X06"}],"explanation":["1 km = 1000 m예요.","마라톤 경기의 거리는 1000 m보다 길어요.","나머지는 모두 1 km보다 짧아요."],"asset":null},{"stem":"이번에는 다른 문제예요. 1 km보다 긴 것은 어느 것인가요?","options":[{"t":"서울에서 부산까지의 거리","correct":true},{"t":"수영장의 길이","mis":"M3-1-u5-X20"},{"t":"운동장 한 바퀴의 길이","mis":"M3-1-u5-X06"},{"t":"기차 한 대의 길이","mis":"M3-1-u5-X06"}],"explanation":["1 km = 1000 m예요.","서울에서 부산까지의 거리는 1000 m보다 길어요.","나머지는 모두 1 km보다 짧아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#3','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',3,'mc','auto','숲속 쉼터에서 세계 온실까지는 1 km 200 m, 숲속 놀이터까지는 980 m예요. 더 가까운 곳은 어디인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X03','M3-1-u5-X01']::text[],true,'{"seq":3,"concept":"M3-1-u5-C5","difficulty":3,"kind":"mc","stem":"숲속 쉼터에서 세계 온실까지는 1 km 200 m, 숲속 놀이터까지는 980 m예요. 더 가까운 곳은 어디인가요?","options":[{"t":"숲속 놀이터","correct":true},{"t":"세계 온실","mis":"M3-1-u5-X20"},{"t":"두 곳이 같아요","mis":"M3-1-u5-X03"},{"t":"알 수 없어요","mis":"M3-1-u5-X01"}],"explanation":["단위를 m로 맞춰요 — 1 km 200 m = 1200 m예요.","1200 m와 980 m를 견주어요.","더 가까운 곳은 숲속 놀이터예요."],"variant_rule":{"alt":[{"stem":"숲속 쉼터에서 전망대까지는 1 km 410 m, 연못까지는 1190 m예요. 더 가까운 곳은 어디인가요?","options":[{"t":"연못","correct":true},{"t":"전망대","mis":"M3-1-u5-X20"},{"t":"두 곳이 같아요","mis":"M3-1-u5-X03"},{"t":"알 수 없어요","mis":"M3-1-u5-X01"}],"explanation":["단위를 m로 맞춰요 — 1 km 410 m = 1410 m예요.","1410 m와 1190 m를 견주어요.","더 가까운 곳은 연못이에요."],"asset":null},{"stem":"숲속 쉼터에서 사랑숲까지는 1 km 380 m, 행복숲까지는 1160 m예요. 더 가까운 곳은 어디인가요?","options":[{"t":"행복숲","correct":true},{"t":"사랑숲","mis":"M3-1-u5-X20"},{"t":"두 곳이 같아요","mis":"M3-1-u5-X03"},{"t":"알 수 없어요","mis":"M3-1-u5-X01"}],"explanation":["단위를 m로 맞춰요 — 1 km 380 m = 1380 m예요.","1380 m와 1160 m를 견주어요.","더 가까운 곳은 행복숲이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#4','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',3,'sa','auto','약 1 km 500 m는 약 500 m가 몇 번 들어가는 거리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u5-C5","difficulty":3,"kind":"sa","stem":"약 1 km 500 m는 약 500 m가 몇 번 들어가는 거리인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1 km 500 m = 1500 m예요.","500 m씩 세어 1500 m가 될 때까지 — 3번.","약 500 m가 3번 들어가요."],"variant_rule":{"alt":[{"stem":"약 1 km 200 m는 약 200 m가 몇 번 들어가는 거리인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1 km 200 m = 1200 m예요.","200 m씩 세어 1200 m가 될 때까지 — 6번.","약 200 m가 6번 들어가요."],"asset":null},{"stem":"약 2 km 500 m는 약 500 m가 몇 번 들어가는 거리인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["2 km 500 m = 2500 m예요.","500 m씩 세어 2500 m가 될 때까지 — 5번.","약 500 m가 5번 들어가요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#5','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',3,'error','auto','길이의 단위를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X20']::text[],true,'{"seq":5,"concept":"M3-1-u5-C5","difficulty":3,"kind":"error","stem":"길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「보령 해저 터널의 길이는 약 7 m야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"하랑 — 「교실 긴 쪽의 길이는 약 9 m야」","mis":"M3-1-u5-X20"},{"t":"지유 — 「우리 동네에서 옆 도시까지의 거리는 약 15 km야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","보령 해저 터널의 길이는 약 7 km가 알맞아요.","도윤은 m를 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「우리 동네에서 옆 도시까지의 거리는 약 15 m야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"민준 — 「운동장 한 바퀴는 약 200 m야」","mis":"M3-1-u5-X20"},{"t":"하린 — 「나무의 높이는 약 12 m야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","우리 동네에서 옆 도시까지의 거리는 약 15 km가 알맞아요.","지유는 m를 잘못 썼어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 길이의 단위를 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「서울에서 부산까지의 거리는 약 400 m야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"민준 — 「교실 긴 쪽의 길이는 약 9 m야」","mis":"M3-1-u5-X20"},{"t":"하랑 — 「우리 동네에서 옆 도시까지의 거리는 약 15 km야」","mis":"M3-1-u5-X20"}],"explanation":["대상의 크기에 맞는 단위인지 하나씩 봐요.","서울에서 부산까지의 거리는 약 400 km가 알맞아요.","하은은 m를 잘못 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#6','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',3,'mc','auto','가장 긴 것은 어느 것인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X02']::text[],true,'{"seq":6,"concept":"M3-1-u5-C5","difficulty":3,"kind":"mc","stem":"가장 긴 것은 어느 것인가요?","options":[{"t":"서울에서 부산까지의 거리 약 400 km","correct":true},{"t":"세계 온실까지의 거리 약 1500 m","mis":"M3-1-u5-X06"},{"t":"교실 긴 쪽의 길이 약 9 m","mis":"M3-1-u5-X02"},{"t":"마라톤 경기의 거리 약 42 km","mis":"M3-1-u5-X02"}],"explanation":["단위를 m로 맞춰 견주어요.","세계 온실까지의 거리 약 1500 m, 교실 긴 쪽의 길이 약 9 m, 마라톤 경기의 거리 약 42000 m, 서울에서 부산까지의 거리 약 400000 m.","가장 긴 것은 서울에서 부산까지의 거리 — 수가 크다고 가장 긴 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 가장 긴 것은 어느 것인가요?","options":[{"t":"서울에서 제주도까지의 거리 약 460 km","correct":true},{"t":"나무의 높이 약 12 m","mis":"M3-1-u5-X02"},{"t":"서울에서 부산까지의 거리 약 400 km","mis":"M3-1-u5-X02"},{"t":"세계 온실까지의 거리 약 1500 m","mis":"M3-1-u5-X06"}],"explanation":["단위를 m로 맞춰 견주어요.","나무의 높이 약 12 m, 서울에서 부산까지의 거리 약 400000 m, 세계 온실까지의 거리 약 1500 m, 서울에서 제주도까지의 거리 약 460000 m.","가장 긴 것은 서울에서 제주도까지의 거리 — 수가 크다고 가장 긴 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 가장 긴 것은 어느 것인가요?","options":[{"t":"보령 해저 터널의 길이 약 7 km","correct":true},{"t":"나무의 높이 약 12 m","mis":"M3-1-u5-X02"},{"t":"운동장 한 바퀴 약 200 m","mis":"M3-1-u5-X02"},{"t":"세계 온실까지의 거리 약 1500 m","mis":"M3-1-u5-X06"}],"explanation":["단위를 m로 맞춰 견주어요.","나무의 높이 약 12 m, 보령 해저 터널의 길이 약 7000 m, 운동장 한 바퀴 약 200 m, 세계 온실까지의 거리 약 1500 m.","가장 긴 것은 보령 해저 터널의 길이 — 수가 크다고 가장 긴 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#7','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',3,'mc','auto','야영장에서 약수터까지는 약 750 m예요. 약수터에 갔다가 야영장으로 돌아오면 모두 약 얼마를 걷나요?',ARRAY['M3-1-u5-X20','M3-1-u5-X08','M3-1-u5-X03']::text[],true,'{"seq":7,"concept":"M3-1-u5-C5","difficulty":3,"kind":"mc","stem":"야영장에서 약수터까지는 약 750 m예요. 약수터에 갔다가 야영장으로 돌아오면 모두 약 얼마를 걷나요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 750 m","mis":"M3-1-u5-X20"},{"t":"약 2 km","mis":"M3-1-u5-X08"},{"t":"약 1 km 50 m","mis":"M3-1-u5-X03"}],"explanation":["갔다가 돌아오면 같은 거리를 두 번 걸어요.","750 m + 750 m = 1500 m.","1500 m = 1 km 500 m."],"variant_rule":{"alt":[{"stem":"야영장에서 전망대까지는 약 650 m예요. 전망대에 갔다가 야영장으로 돌아오면 모두 약 얼마를 걷나요?","options":[{"t":"약 1 km 300 m","correct":true},{"t":"약 650 m","mis":"M3-1-u5-X20"},{"t":"약 2 km","mis":"M3-1-u5-X08"},{"t":"약 1 km 30 m","mis":"M3-1-u5-X03"}],"explanation":["갔다가 돌아오면 같은 거리를 두 번 걸어요.","650 m + 650 m = 1300 m.","1300 m = 1 km 300 m."],"asset":null},{"stem":"야영장에서 연못까지는 약 800 m예요. 연못에 갔다가 야영장으로 돌아오면 모두 약 얼마를 걷나요?","options":[{"t":"약 1 km 600 m","correct":true},{"t":"약 800 m","mis":"M3-1-u5-X20"},{"t":"약 2 km","mis":"M3-1-u5-X08"},{"t":"약 1 km 60 m","mis":"M3-1-u5-X03"}],"explanation":["갔다가 돌아오면 같은 거리를 두 번 걸어요.","800 m + 800 m = 1600 m.","1600 m = 1 km 600 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#8','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',4,'essay','teacher','숲속 놀이터에서 사랑숲까지 가는 길에 약 500 m인 거리가 3번 들어가요. 사랑숲까지의 거리를 어림하는 방법을 쓰고, 어림한 거리를 km와 m로 나타내 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C5","difficulty":4,"kind":"essay","stem":"숲속 놀이터에서 사랑숲까지 가는 길에 약 500 m인 거리가 3번 들어가요. 사랑숲까지의 거리를 어림하는 방법을 쓰고, 어림한 거리를 km와 m로 나타내 보세요.","answer_guide":{"answer":"예: 약 500 m가 3번이므로 500 m + 500 m + 500 m = 1500 m이다. 1000 m = 1 km이므로 1500 m = 1 km 500 m이다. 어림한 거리라 「약 1 km 500 m」라고 쓴다.","scoring_points":["500 m를 3번 더했는가","1500 m = 1 km 500 m로 바꾸었는가","「약」을 붙였는가"]},"explanation":["약 500 m × 3번.","1500 m = 1 km 500 m.","약 1 km 500 m."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#9','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',4,'essay','teacher','새끼손톱의 너비, 책상의 높이, 한라산의 높이, 서울에서 제주도까지의 거리에 알맞은 단위(mm·cm·m·km)를 하나씩 고르고, 그렇게 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C5","difficulty":4,"kind":"essay","stem":"새끼손톱의 너비, 책상의 높이, 한라산의 높이, 서울에서 제주도까지의 거리에 알맞은 단위(mm·cm·m·km)를 하나씩 고르고, 그렇게 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 새끼손톱 너비 — mm(아주 작아서), 책상 높이 — cm(손으로 재는 크기), 한라산 높이 — m(아주 높지만 도시 사이만큼 멀지 않아서), 서울~제주 — km(아주 먼 거리라서).","scoring_points":["네 대상에 단위를 알맞게 골랐는가","작은 것은 mm·cm라고 설명했는가","먼 거리는 km라고 설명했는가"]},"explanation":["새끼손톱 mm · 책상 cm.","한라산 m.","서울~제주 km."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L05_challenge#10','math',3,1,'u5','L05','g3_1_math_u5_L05_challenge','lesson_challenge','M3-1-u5-C5',4,'mc','auto','숲속 놀이터까지 가는 길이 두 가지예요. 가 길은 약 400 m를 걷고 다시 약 700 m를 걸어요. 나 길은 약 1 km 200 m예요. 더 짧은 길은 어느 것인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X21','M3-1-u5-X02']::text[],true,'{"seq":10,"concept":"M3-1-u5-C5","difficulty":4,"kind":"mc","stem":"숲속 놀이터까지 가는 길이 두 가지예요. 가 길은 약 400 m를 걷고 다시 약 700 m를 걸어요. 나 길은 약 1 km 200 m예요. 더 짧은 길은 어느 것인가요?","options":[{"t":"가 길","correct":true},{"t":"나 길","mis":"M3-1-u5-X20"},{"t":"두 길이 같아요","mis":"M3-1-u5-X21"},{"t":"알 수 없어요","mis":"M3-1-u5-X02"}],"explanation":["가 길: 약 400 m + 약 700 m = 약 1100 m.","나 길: 약 1 km 200 m = 약 1200 m.","1100 m와 1200 m — 더 짧은 길은 가 길이에요."],"variant_rule":{"alt":[{"stem":"숲속 놀이터까지 가는 길이 두 가지예요. 가 길은 약 300 m를 걷고 다시 약 750 m를 걸어요. 나 길은 약 1 km 300 m예요. 더 짧은 길은 어느 것인가요?","options":[{"t":"가 길","correct":true},{"t":"나 길","mis":"M3-1-u5-X20"},{"t":"두 길이 같아요","mis":"M3-1-u5-X21"},{"t":"알 수 없어요","mis":"M3-1-u5-X02"}],"explanation":["가 길: 약 300 m + 약 750 m = 약 1050 m.","나 길: 약 1 km 300 m = 약 1300 m.","1050 m와 1300 m — 더 짧은 길은 가 길이에요."],"asset":null},{"stem":"숲속 놀이터까지 가는 길이 두 가지예요. 가 길은 약 750 m를 걷고 다시 약 650 m를 걸어요. 나 길은 약 1 km 550 m예요. 더 짧은 길은 어느 것인가요?","options":[{"t":"가 길","correct":true},{"t":"나 길","mis":"M3-1-u5-X20"},{"t":"두 길이 같아요","mis":"M3-1-u5-X21"},{"t":"알 수 없어요","mis":"M3-1-u5-X02"}],"explanation":["가 길: 약 750 m + 약 650 m = 약 1400 m.","나 길: 약 1 km 550 m = 약 1550 m.","1400 m와 1550 m — 더 짧은 길은 가 길이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#1','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',1,'mc','auto','1분은 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X01']::text[],true,'{"seq":1,"concept":"M3-1-u5-C6","difficulty":1,"kind":"mc","stem":"1분은 몇 초인가요?","options":[{"t":"60초","correct":true},{"t":"100초","mis":"M3-1-u5-X09"},{"t":"10초","mis":"M3-1-u5-X01"},{"t":"600초","mis":"M3-1-u5-X01"}],"explanation":["초바늘이 작은 눈금 한 칸 가는 동안이 1초예요.","작은 눈금이 60칸이라 한 바퀴는 60초예요.","60초 = 1분 — 그동안 긴바늘은 한 칸 움직여요."],"variant_rule":{"alt":[{"stem":"초바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 얼마인가요?","options":[{"t":"60초","correct":true},{"t":"12초","mis":"M3-1-u5-X11"},{"t":"100초","mis":"M3-1-u5-X09"},{"t":"1시간","mis":"M3-1-u5-X10"}],"explanation":["초바늘이 작은 눈금 한 칸 가는 동안이 1초예요.","작은 눈금이 60칸이라 한 바퀴는 60초예요.","60초 = 1분 — 그동안 긴바늘은 한 칸 움직여요."],"asset":null},{"stem":"초바늘이 작은 눈금 한 칸을 가는 동안은 몇 초인가요?","options":[{"t":"1초","correct":true},{"t":"5초","mis":"M3-1-u5-X11"},{"t":"1분","mis":"M3-1-u5-X10"},{"t":"60초","mis":"M3-1-u5-X10"}],"explanation":["초바늘이 작은 눈금 한 칸 가는 동안이 1초예요.","작은 눈금이 60칸이라 한 바퀴는 60초예요.","60초 = 1분 — 그동안 긴바늘은 한 칸 움직여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#2','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',1,'mc','auto','시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11']::text[],true,'{"seq":2,"concept":"M3-1-u5-C6","difficulty":1,"kind":"mc","stem":"시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"4시 10분 30초","correct":true},{"t":"4시 30분 10초","mis":"M3-1-u5-X10"},{"t":"4시 10분 6초","mis":"M3-1-u5-X11"},{"t":"2시 20분 30초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 4와 5 사이 — 4시.","긴바늘은 10분, 가는 빨간 초바늘은 30초를 가리켜요.","4시 10분 30초예요."],"asset":{"type":"clock3","h":4,"m":10,"s":30},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"11시 12분 10초","correct":true},{"t":"11시 10분 12초","mis":"M3-1-u5-X10"},{"t":"11시 12분 2초","mis":"M3-1-u5-X11"},{"t":"2시 55분 10초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 11과 12 사이 — 11시.","긴바늘은 12분, 가는 빨간 초바늘은 10초를 가리켜요.","11시 12분 10초예요."],"asset":{"type":"clock3","h":11,"m":12,"s":10}},{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"9시 56분 36초","correct":true},{"t":"9시 36분 56초","mis":"M3-1-u5-X10"},{"t":"9시 56분 37초","mis":"M3-1-u5-X21"},{"t":"11시 45분 36초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 9와 10 사이 — 9시.","긴바늘은 56분, 가는 빨간 초바늘은 36초를 가리켜요.","9시 56분 36초예요."],"asset":{"type":"clock3","h":9,"m":56,"s":36}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#3','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',1,'mc','auto','2분은 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X01']::text[],true,'{"seq":3,"concept":"M3-1-u5-C6","difficulty":1,"kind":"mc","stem":"2분은 몇 초인가요?","options":[{"t":"120초","correct":true},{"t":"200초","mis":"M3-1-u5-X09"},{"t":"20초","mis":"M3-1-u5-X01"},{"t":"12초","mis":"M3-1-u5-X01"}],"explanation":["1분 = 60초예요.","2분 = 60 + 60 = 120초.","2분 = 120초예요."],"variant_rule":{"alt":[{"stem":"4분은 몇 초인가요?","options":[{"t":"240초","correct":true},{"t":"400초","mis":"M3-1-u5-X09"},{"t":"40초","mis":"M3-1-u5-X01"},{"t":"24초","mis":"M3-1-u5-X01"}],"explanation":["1분 = 60초예요.","4분 = 60 + 60 + 60 + 60 = 240초.","4분 = 240초예요."],"asset":null},{"stem":"3분은 몇 초인가요?","options":[{"t":"180초","correct":true},{"t":"300초","mis":"M3-1-u5-X09"},{"t":"30초","mis":"M3-1-u5-X01"},{"t":"18초","mis":"M3-1-u5-X01"}],"explanation":["1분 = 60초예요.","3분 = 60 + 60 + 60 = 180초.","3분 = 180초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#4','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',1,'sa','auto','1분 30초는 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u5-C6","difficulty":1,"kind":"sa","stem":"1분 30초는 몇 초인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 30초 = 60 + 30 = 90초예요."],"variant_rule":{"alt":[{"stem":"1분 10초는 몇 초인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 10초 = 60 + 10 = 70초예요."],"asset":null},{"stem":"1분 15초는 몇 초인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 15초 = 60 + 15 = 75초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#5','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',2,'mc','auto','185초는 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X04','M3-1-u5-X03']::text[],true,'{"seq":5,"concept":"M3-1-u5-C6","difficulty":2,"kind":"mc","stem":"185초는 몇 분 몇 초인가요?","options":[{"t":"3분 5초","correct":true},{"t":"1분 85초","mis":"M3-1-u5-X09"},{"t":"18분 5초","mis":"M3-1-u5-X04"},{"t":"3분 50초","mis":"M3-1-u5-X03"}],"explanation":["60초 = 1분 — 60씩 묶어요.","185 = 60 + 60 + 60 + 5.","185초 = 3분 5초예요."],"variant_rule":{"alt":[{"stem":"239초는 몇 분 몇 초인가요?","options":[{"t":"3분 59초","correct":true},{"t":"2분 39초","mis":"M3-1-u5-X09"},{"t":"23분 9초","mis":"M3-1-u5-X04"},{"t":"2분 59초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","239 = 60 + 60 + 60 + 59.","239초 = 3분 59초예요."],"asset":null},{"stem":"193초는 몇 분 몇 초인가요?","options":[{"t":"3분 13초","correct":true},{"t":"1분 93초","mis":"M3-1-u5-X09"},{"t":"19분 3초","mis":"M3-1-u5-X04"},{"t":"2분 13초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","193 = 60 + 60 + 60 + 13.","193초 = 3분 13초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#6','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',2,'ox','auto','1분 25초 = 125초예요.',ARRAY['M3-1-u5-X09']::text[],true,'{"seq":6,"concept":"M3-1-u5-C6","difficulty":2,"kind":"ox","stem":"1분 25초 = 125초예요.","answer":"X","reason_options":[{"t":"1분은 60초라서 1분 25초는 85초여서","correct":true},{"t":"1분은 100초라서","mis":"M3-1-u5-X09"}],"mis":"M3-1-u5-X09","explanation":["1분 = 60초예요(100초가 아니에요).","1분 = 60초, 여기에 25초를 더해요.","1분 25초 = 85초예요."],"variant_rule":{"alt":[{"stem":"1분 32초 = 132초예요.","answer":"X","reason_options":[{"t":"1분은 60초라서 1분 32초는 92초여서","correct":true},{"t":"1분은 100초라서","mis":"M3-1-u5-X09"}],"explanation":["1분 = 60초예요(100초가 아니에요).","1분 = 60초, 여기에 32초를 더해요.","1분 32초 = 92초예요."],"asset":null},{"stem":"1분 21초 = 121초예요.","answer":"X","reason_options":[{"t":"1분은 60초라서 1분 21초는 81초여서","correct":true},{"t":"1분은 100초라서","mis":"M3-1-u5-X09"}],"explanation":["1분 = 60초예요(100초가 아니에요).","1분 = 60초, 여기에 21초를 더해요.","1분 21초 = 81초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#7','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',2,'mc','auto','「시각」을 나타낸 것은 어느 것인가요?',ARRAY['M3-1-u5-X12']::text[],true,'{"seq":7,"concept":"M3-1-u5-C6","difficulty":2,"kind":"mc","stem":"「시각」을 나타낸 것은 어느 것인가요?","options":[{"t":"수업은 9시에 시작해요.","correct":true},{"t":"달리기를 30초 동안 했어요.","mis":"M3-1-u5-X12"},{"t":"숙제를 20분 동안 했어요.","mis":"M3-1-u5-X12"},{"t":"영화는 2시간 동안 해요.","mis":"M3-1-u5-X12"}],"explanation":["시각은 「몇 시 몇 분」 어떤 때를 가리켜요.","시간은 「얼마 동안」 — 시각과 시각 사이예요.","「~에」는 시각, 「~동안」은 시간이에요."],"variant_rule":{"alt":[{"stem":"「시간」(얼마 동안)을 나타낸 것은 어느 것인가요?","options":[{"t":"줄넘기를 40초 동안 했어요.","correct":true},{"t":"3시 15분에 집에 왔어요.","mis":"M3-1-u5-X12"},{"t":"점심은 12시 10분에 먹어요.","mis":"M3-1-u5-X12"},{"t":"8시 40분에 학교에 가요.","mis":"M3-1-u5-X12"}],"explanation":["시각은 「몇 시 몇 분」 어떤 때를 가리켜요.","시간은 「얼마 동안」 — 시각과 시각 사이예요.","「~에」는 시각, 「~동안」은 시간이에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 「시각」을 나타낸 것은 어느 것인가요?","options":[{"t":"영화가 2시 10분에 시작했어요.","correct":true},{"t":"동굴 체험을 30분 동안 했어요.","mis":"M3-1-u5-X12"},{"t":"양치질을 3분 동안 했어요.","mis":"M3-1-u5-X12"},{"t":"1분은 60초예요.","mis":"M3-1-u5-X12"}],"explanation":["시각은 「몇 시 몇 분」 어떤 때를 가리켜요.","시간은 「얼마 동안」 — 시각과 시각 사이예요.","「~에」는 시각, 「~동안」은 시간이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#8','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',2,'sa','auto','시계에서 초바늘이 가리키는 것은 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u5-C6","difficulty":2,"kind":"sa","stem":"시계에서 초바늘이 가리키는 것은 몇 초인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["가는 빨간 바늘이 초바늘이에요.","숫자 한 칸(큰 눈금)은 5초, 작은 눈금 한 칸은 1초예요.","초바늘은 40초를 가리켜요."],"asset":{"type":"clock3","h":8,"m":23,"s":40},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계에서 초바늘이 가리키는 것은 몇 초인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["가는 빨간 바늘이 초바늘이에요.","숫자 한 칸(큰 눈금)은 5초, 작은 눈금 한 칸은 1초예요.","초바늘은 45초를 가리켜요."],"asset":{"type":"clock3","h":7,"m":2,"s":45}},{"stem":"이번에는 다른 문제예요. 시계에서 초바늘이 가리키는 것은 몇 초인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["가는 빨간 바늘이 초바늘이에요.","숫자 한 칸(큰 눈금)은 5초, 작은 눈금 한 칸은 1초예요.","초바늘은 46초를 가리켜요."],"asset":{"type":"clock3","h":3,"m":26,"s":46}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#9','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',2,'sa','auto','초바늘이 숫자 3에서 숫자 7까지 움직였어요. 몇 초가 지났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u5-C6","difficulty":2,"kind":"sa","stem":"초바늘이 숫자 3에서 숫자 7까지 움직였어요. 몇 초가 지났나요? 숫자로 쓰세요.","answer":["20"],"explanation":["숫자 한 칸 사이에는 작은 눈금이 5칸 있어요 — 5초.","3에서 7까지는 숫자 4칸.","5 × 4 = 20 — 20초가 지났어요."],"variant_rule":{"alt":[{"stem":"초바늘이 숫자 2에서 숫자 9까지 움직였어요. 몇 초가 지났나요? 숫자로 쓰세요.","answer":["35"],"explanation":["숫자 한 칸 사이에는 작은 눈금이 5칸 있어요 — 5초.","2에서 9까지는 숫자 7칸.","5 × 7 = 35 — 35초가 지났어요."],"asset":null},{"stem":"초바늘이 숫자 1에서 숫자 4까지 움직였어요. 몇 초가 지났나요? 숫자로 쓰세요.","answer":["15"],"explanation":["숫자 한 칸 사이에는 작은 눈금이 5칸 있어요 — 5초.","1에서 4까지는 숫자 3칸.","5 × 3 = 15 — 15초가 지났어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_basic#10','math',3,1,'u5','L06','g3_1_math_u5_L06_basic','lesson_basic','M3-1-u5-C6',3,'error','auto','시간을 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C6","difficulty":3,"kind":"error","stem":"시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「1분 25초는 125초야」","correct":true,"mis_target":"M3-1-u5-X09"},{"t":"태오 — 「1분은 60초야」","mis":"M3-1-u5-X20"},{"t":"하랑 — 「60초는 1분이야」","mis":"M3-1-u5-X20"}],"explanation":["1분 = 60초예요.","1분 25초 = 60 + 25 = 85초.","민준은 1분을 100초로 셈했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「1분 23초는 123초야」","correct":true,"mis_target":"M3-1-u5-X09"},{"t":"하린 — 「1분은 60초야」","mis":"M3-1-u5-X20"},{"t":"민준 — 「2분은 120초야」","mis":"M3-1-u5-X20"}],"explanation":["1분 = 60초예요.","1분 23초 = 60 + 23 = 83초.","서윤은 1분을 100초로 셈했어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「1분 11초는 111초야」","correct":true,"mis_target":"M3-1-u5-X09"},{"t":"민준 — 「1분은 60초야」","mis":"M3-1-u5-X20"},{"t":"도윤 — 「60초는 1분이야」","mis":"M3-1-u5-X20"}],"explanation":["1분 = 60초예요.","1분 11초 = 60 + 11 = 71초.","지유는 1분을 100초로 셈했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#1','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',2,'sa','auto','1분 15초는 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u5-C6","difficulty":2,"kind":"sa","stem":"1분 15초는 몇 초인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 15초 = 60 + 15 = 75초예요."],"variant_rule":{"alt":[{"stem":"1분 14초는 몇 초인가요? 숫자로 쓰세요.","answer":["74"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 14초 = 60 + 14 = 74초예요."],"asset":null},{"stem":"1분 32초는 몇 초인가요? 숫자로 쓰세요.","answer":["92"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 32초 = 60 + 32 = 92초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#2','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',2,'mc','auto','시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11']::text[],true,'{"seq":2,"concept":"M3-1-u5-C6","difficulty":2,"kind":"mc","stem":"시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"10시 47분 15초","correct":true},{"t":"10시 15분 47초","mis":"M3-1-u5-X10"},{"t":"10시 47분 3초","mis":"M3-1-u5-X11"},{"t":"9시 50분 15초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 10과 11 사이 — 10시.","긴바늘은 47분, 가는 빨간 초바늘은 15초를 가리켜요.","10시 47분 15초예요."],"asset":{"type":"clock3","h":10,"m":47,"s":15},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"9시 7분 35초","correct":true},{"t":"9시 35분 7초","mis":"M3-1-u5-X10"},{"t":"9시 7분 7초","mis":"M3-1-u5-X11"},{"t":"1시 45분 35초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 9와 10 사이 — 9시.","긴바늘은 7분, 가는 빨간 초바늘은 35초를 가리켜요.","9시 7분 35초예요."],"asset":{"type":"clock3","h":9,"m":7,"s":35}},{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"11시 34분 53초","correct":true},{"t":"11시 53분 34초","mis":"M3-1-u5-X10"},{"t":"11시 34분 54초","mis":"M3-1-u5-X21"},{"t":"6시 55분 53초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 11과 12 사이 — 11시.","긴바늘은 34분, 가는 빨간 초바늘은 53초를 가리켜요.","11시 34분 53초예요."],"asset":{"type":"clock3","h":11,"m":34,"s":53}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#3','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',3,'mc','auto','265초는 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X04']::text[],true,'{"seq":3,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"265초는 몇 분 몇 초인가요?","options":[{"t":"4분 25초","correct":true},{"t":"2분 65초","mis":"M3-1-u5-X09"},{"t":"26분 5초","mis":"M3-1-u5-X04"},{"t":"3분 25초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","265 = 60 + 60 + 60 + 60 + 25.","265초 = 4분 25초예요."],"variant_rule":{"alt":[{"stem":"263초는 몇 분 몇 초인가요?","options":[{"t":"4분 23초","correct":true},{"t":"2분 63초","mis":"M3-1-u5-X09"},{"t":"26분 3초","mis":"M3-1-u5-X04"},{"t":"3분 23초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","263 = 60 + 60 + 60 + 60 + 23.","263초 = 4분 23초예요."],"asset":null},{"stem":"213초는 몇 분 몇 초인가요?","options":[{"t":"3분 33초","correct":true},{"t":"2분 13초","mis":"M3-1-u5-X09"},{"t":"21분 3초","mis":"M3-1-u5-X04"},{"t":"2분 33초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","213 = 60 + 60 + 60 + 33.","213초 = 3분 33초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#4','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',3,'mc','auto','두 시간을 견주어 ○ 안에 알맞은 것을 고르세요. 2분 10초 ○ 125초',ARRAY['M3-1-u5-X09','M3-1-u5-X20']::text[],true,'{"seq":4,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"두 시간을 견주어 ○ 안에 알맞은 것을 고르세요. 2분 10초 ○ 125초","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X09"},{"t":"=","mis":"M3-1-u5-X09"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 초로 맞춰요.","2분 10초 = 130초예요.","130 > 125 — >예요."],"variant_rule":{"alt":[{"stem":"두 시간을 견주어 ○ 안에 알맞은 것을 고르세요. 2분 52초 ○ 194초","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X09"},{"t":"=","mis":"M3-1-u5-X09"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 초로 맞춰요.","2분 52초 = 172초예요.","172 < 194 — <예요."],"asset":null},{"stem":"두 시간을 견주어 ○ 안에 알맞은 것을 고르세요. 2분 18초 ○ 161초","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X09"},{"t":"=","mis":"M3-1-u5-X09"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 초로 맞춰요.","2분 18초 = 138초예요.","138 < 161 — <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#5','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',3,'mc','auto','숲길 한 바퀴를 달린 기록이에요. 가장 빨리 달린 친구는 누구인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X20']::text[],true,'{"seq":5,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"숲길 한 바퀴를 달린 기록이에요. 가장 빨리 달린 친구는 누구인가요?","options":[{"t":"서윤(76초)","correct":true},{"t":"시우(1분 20초)","mis":"M3-1-u5-X09"},{"t":"도윤(81초)","mis":"M3-1-u5-X09"},{"t":"은우(1분 30초)","mis":"M3-1-u5-X20"}],"explanation":["기록(걸린 시간)이 짧을수록 빨리 달린 거예요.","모두 초로 바꾸면 시우 80초, 도윤 81초, 은우 90초, 서윤 76초.","가장 짧은 서윤이 가장 빨리 달렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 숲길 한 바퀴를 달린 기록이에요. 가장 빨리 달린 친구는 누구인가요?","options":[{"t":"서윤(70초)","correct":true},{"t":"태오(1분 33초)","mis":"M3-1-u5-X20"},{"t":"도윤(1분 25초)","mis":"M3-1-u5-X09"},{"t":"은우(81초)","mis":"M3-1-u5-X09"}],"explanation":["기록(걸린 시간)이 짧을수록 빨리 달린 거예요.","모두 초로 바꾸면 태오 93초, 서윤 70초, 도윤 85초, 은우 81초.","가장 짧은 서윤이 가장 빨리 달렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 숲길 한 바퀴를 달린 기록이에요. 가장 빨리 달린 친구는 누구인가요?","options":[{"t":"시우(55초)","correct":true},{"t":"하은(1분 26초)","mis":"M3-1-u5-X09"},{"t":"도윤(1분 31초)","mis":"M3-1-u5-X20"},{"t":"하린(62초)","mis":"M3-1-u5-X09"}],"explanation":["기록(걸린 시간)이 짧을수록 빨리 달린 거예요.","모두 초로 바꾸면 하은 86초, 시우 55초, 도윤 91초, 하린 62초.","가장 짧은 시우가 가장 빨리 달렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#6','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',3,'error','auto','시간을 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X20']::text[],true,'{"seq":6,"concept":"M3-1-u5-C6","difficulty":3,"kind":"error","stem":"시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「2분 15초는 215초야」","correct":true,"mis_target":"M3-1-u5-X09"},{"t":"민준 — 「1분은 60초야」","mis":"M3-1-u5-X20"},{"t":"서윤 — 「60초는 1분이야」","mis":"M3-1-u5-X20"}],"explanation":["1분 = 60초예요.","2분 15초 = 120 + 15 = 135초.","태오는 1분을 100초로 셈했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「2분 27초는 227초야」","correct":true,"mis_target":"M3-1-u5-X09"},{"t":"하린 — 「1분은 60초야」","mis":"M3-1-u5-X20"},{"t":"민준 — 「3분은 180초야」","mis":"M3-1-u5-X20"}],"explanation":["1분 = 60초예요.","2분 27초 = 120 + 27 = 147초.","은우는 1분을 100초로 셈했어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「2분 31초는 231초야」","correct":true,"mis_target":"M3-1-u5-X09"},{"t":"시우 — 「1분은 60초야」","mis":"M3-1-u5-X20"},{"t":"하랑 — 「60초는 1분이야」","mis":"M3-1-u5-X20"}],"explanation":["1분 = 60초예요.","2분 31초 = 120 + 31 = 151초.","하은은 1분을 100초로 셈했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#7','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',3,'mc','auto','시계의 시각에서 초바늘이 한 바퀴를 더 돌았어요. 몇 시 몇 분 몇 초가 되나요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11','M3-1-u5-X09']::text[],true,'{"seq":7,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"시계의 시각에서 초바늘이 한 바퀴를 더 돌았어요. 몇 시 몇 분 몇 초가 되나요?","options":[{"t":"7시 36분 20초","correct":true},{"t":"8시 35분 20초","mis":"M3-1-u5-X10"},{"t":"7시 35분 21초","mis":"M3-1-u5-X11"},{"t":"7시 95분 20초","mis":"M3-1-u5-X09"}],"explanation":["시계는 7시 35분 20초예요.","초바늘 한 바퀴 = 60초 = 1분 — 긴바늘이 한 칸 움직여요.","7시 36분 20초예요."],"asset":{"type":"clock3","h":7,"m":35,"s":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계의 시각에서 초바늘이 한 바퀴를 더 돌았어요. 몇 시 몇 분 몇 초가 되나요?","options":[{"t":"10시 13분 35초","correct":true},{"t":"11시 12분 35초","mis":"M3-1-u5-X10"},{"t":"10시 12분 36초","mis":"M3-1-u5-X11"},{"t":"10시 72분 35초","mis":"M3-1-u5-X09"}],"explanation":["시계는 10시 12분 35초예요.","초바늘 한 바퀴 = 60초 = 1분 — 긴바늘이 한 칸 움직여요.","10시 13분 35초예요."],"asset":{"type":"clock3","h":10,"m":12,"s":35}},{"stem":"이번에는 다른 문제예요. 시계의 시각에서 초바늘이 한 바퀴를 더 돌았어요. 몇 시 몇 분 몇 초가 되나요?","options":[{"t":"6시 44분 37초","correct":true},{"t":"7시 43분 37초","mis":"M3-1-u5-X10"},{"t":"6시 43분 38초","mis":"M3-1-u5-X11"},{"t":"6시 103분 37초","mis":"M3-1-u5-X09"}],"explanation":["시계는 6시 43분 37초예요.","초바늘 한 바퀴 = 60초 = 1분 — 긴바늘이 한 칸 움직여요.","6시 44분 37초예요."],"asset":{"type":"clock3","h":6,"m":43,"s":37}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#8','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',4,'essay','teacher','185초는 몇 분 몇 초인지 1분 = 60초를 이용해 구하는 방법을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C6","difficulty":4,"kind":"essay","stem":"185초는 몇 분 몇 초인지 1분 = 60초를 이용해 구하는 방법을 써 보세요.","answer_guide":{"answer":"예: 60초가 1분이므로 185초에서 60씩 묶는다. 60 + 60 + 60 = 180이므로 3분이고 5초가 남는다. 그래서 185초 = 3분 5초이다.","scoring_points":["1분 = 60초를 썼는가","60씩 세 번 묶어 180초 = 3분을 구했는가","3분 5초를 구했는가"]},"explanation":["1분 = 60초.","185 = 180 + 5.","185초 = 3분 5초."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#9','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',4,'essay','teacher','「영화가 2시 10분에 시작했어요.」와 「영화를 2시간 10분 동안 봤어요.」에서 「2시 10분」과 「2시간 10분」이 어떻게 다른지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C6","difficulty":4,"kind":"essay","stem":"「영화가 2시 10분에 시작했어요.」와 「영화를 2시간 10분 동안 봤어요.」에서 「2시 10분」과 「2시간 10분」이 어떻게 다른지 설명해 보세요.","answer_guide":{"answer":"예: 「2시 10분」은 영화가 시작한 때를 나타내는 시각이고, 「2시간 10분」은 영화를 본 동안을 나타내는 시간이다. 시각은 「~에」, 시간은 「~동안」과 함께 쓴다.","scoring_points":["2시 10분을 시각(때)이라고 했는가","2시간 10분을 시간(동안)이라고 했는가","두 말의 쓰임을 구별했는가"]},"explanation":["2시 10분 — 시각(때).","2시간 10분 — 시간(동안).","「~에」 시각, 「~동안」 시간."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L06_challenge#10','math',3,1,'u5','L06','g3_1_math_u5_L06_challenge','lesson_challenge','M3-1-u5-C6',4,'sa','auto','숲길 달리기 기록이 서윤 1분 43초, 민준 1분 26초, 하은 1분 41초예요. 가장 빠른 기록과 가장 느린 기록의 차는 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u5-C6","difficulty":4,"kind":"sa","stem":"숲길 달리기 기록이 서윤 1분 43초, 민준 1분 26초, 하은 1분 41초예요. 가장 빠른 기록과 가장 느린 기록의 차는 몇 초인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["모두 초로 바꿔요 — 서윤 103초, 민준 86초, 하은 101초.","가장 빠른 기록 86초, 가장 느린 기록 103초.","103 − 86 = 17초."],"variant_rule":{"alt":[{"stem":"숲길 달리기 기록이 하은 1분 12초, 지유 1분 59초, 하린 1분 17초예요. 가장 빠른 기록과 가장 느린 기록의 차는 몇 초인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["모두 초로 바꿔요 — 하은 72초, 지유 119초, 하린 77초.","가장 빠른 기록 72초, 가장 느린 기록 119초.","119 − 72 = 47초."],"asset":null},{"stem":"숲길 달리기 기록이 태오 1분 49초, 하린 1분 56초, 하은 1분 58초예요. 가장 빠른 기록과 가장 느린 기록의 차는 몇 초인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["모두 초로 바꿔요 — 태오 109초, 하린 116초, 하은 118초.","가장 빠른 기록 109초, 가장 느린 기록 118초.","118 − 109 = 9초."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#1','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',1,'mc','auto','10시 20분 25초 + 11분 25초는 얼마인가요?',ARRAY['M3-1-u5-X15','M3-1-u5-X21']::text[],true,'{"seq":1,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"10시 20분 25초 + 11분 25초는 얼마인가요?","options":[{"t":"10시 31분 50초","correct":true},{"t":"21시 45분 25초","mis":"M3-1-u5-X15"},{"t":"10시 41분 50초","mis":"M3-1-u5-X21"},{"t":"10시 21분 50초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 25 + 25 = 50, 분끼리 31.","10시 20분 25초 + 11분 25초 = 10시 31분 50초예요."],"variant_rule":{"alt":[{"stem":"3시 5분 30초 + 10분 5초는 얼마인가요?","options":[{"t":"3시 15분 35초","correct":true},{"t":"13시 10분 30초","mis":"M3-1-u5-X15"},{"t":"3시 15분 45초","mis":"M3-1-u5-X21"},{"t":"3시 25분 35초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 30 + 5 = 35, 분끼리 15.","3시 5분 30초 + 10분 5초 = 3시 15분 35초예요."],"asset":null},{"stem":"1시 40분 40초 + 10분 10초는 얼마인가요?","options":[{"t":"1시 50분 50초","correct":true},{"t":"11시 50분 40초","mis":"M3-1-u5-X15"},{"t":"1시 40분 50초","mis":"M3-1-u5-X21"},{"t":"2시 50분 50초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 40 + 10 = 50, 분끼리 50.","1시 40분 40초 + 10분 10초 = 1시 50분 50초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#2','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',1,'mc','auto','2시간 10분 + 1시간 20분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":2,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"2시간 10분 + 1시간 20분은 얼마인가요?","options":[{"t":"3시간 30분","correct":true},{"t":"3시간 40분","mis":"M3-1-u5-X21"},{"t":"3시간 20분","mis":"M3-1-u5-X21"},{"t":"4시간 30분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 10 + 20 = 30.","2시간 10분 + 1시간 20분 = 3시간 30분이에요."],"variant_rule":{"alt":[{"stem":"1시간 20분 + 1시간 25분은 얼마인가요?","options":[{"t":"2시간 45분","correct":true},{"t":"2시간 55분","mis":"M3-1-u5-X21"},{"t":"2시간 35분","mis":"M3-1-u5-X21"},{"t":"3시간 45분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 20 + 25 = 45.","1시간 20분 + 1시간 25분 = 2시간 45분이에요."],"asset":null},{"stem":"5시간 35분 + 3시간 20분은 얼마인가요?","options":[{"t":"8시간 55분","correct":true},{"t":"8시간 45분","mis":"M3-1-u5-X21"},{"t":"9시간 55분","mis":"M3-1-u5-X21"},{"t":"7시간 55분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 35 + 20 = 55.","5시간 35분 + 3시간 20분 = 8시간 55분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#3','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',1,'mc','auto','30초 + 40초는 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"30초 + 40초는 얼마인가요?","options":[{"t":"1분 10초","correct":true},{"t":"10초","mis":"M3-1-u5-X14"},{"t":"2분 10초","mis":"M3-1-u5-X14"},{"t":"1분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 30 + 40 = 70 → 60초를 1분으로 받아올림.","30초 + 40초 = 1분 10초예요."],"variant_rule":{"alt":[{"stem":"20초 + 55초는 얼마인가요?","options":[{"t":"1분 15초","correct":true},{"t":"15초","mis":"M3-1-u5-X14"},{"t":"2분 15초","mis":"M3-1-u5-X14"},{"t":"1분 25초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 20 + 55 = 75 → 60초를 1분으로 받아올림.","20초 + 55초 = 1분 15초예요."],"asset":null},{"stem":"35초 + 35초는 얼마인가요?","options":[{"t":"1분 10초","correct":true},{"t":"10초","mis":"M3-1-u5-X14"},{"t":"2분 10초","mis":"M3-1-u5-X14"},{"t":"1분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 35 + 35 = 70 → 60초를 1분으로 받아올림.","35초 + 35초 = 1분 10초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#4','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',1,'mc','auto','1시간 40분 + 30분은 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":4,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"1시간 40분 + 30분은 얼마인가요?","options":[{"t":"2시간 10분","correct":true},{"t":"1시간 10분","mis":"M3-1-u5-X14"},{"t":"3시간 10분","mis":"M3-1-u5-X14"},{"t":"2시간 20분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 40 + 30 = 70 → 60분을 1시간으로 받아올림.","1시간 40분 + 30분 = 2시간 10분이에요."],"variant_rule":{"alt":[{"stem":"7시간 20분 + 55분은 얼마인가요?","options":[{"t":"8시간 15분","correct":true},{"t":"7시간 15분","mis":"M3-1-u5-X14"},{"t":"9시간 15분","mis":"M3-1-u5-X14"},{"t":"8시간 25분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 20 + 55 = 75 → 60분을 1시간으로 받아올림.","7시간 20분 + 55분 = 8시간 15분이에요."],"asset":null},{"stem":"1시간 45분 + 8시간 30분은 얼마인가요?","options":[{"t":"10시간 15분","correct":true},{"t":"9시간 15분","mis":"M3-1-u5-X14"},{"t":"11시간 15분","mis":"M3-1-u5-X14"},{"t":"10시간 25분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 45 + 30 = 75 → 60분을 1시간으로 받아올림.","1시간 45분 + 8시간 30분 = 10시간 15분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#5','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',2,'mc','auto','8시간 17분 50초 + 1시간 10분 30초는 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":5,"concept":"M3-1-u5-C7","difficulty":2,"kind":"mc","stem":"8시간 17분 50초 + 1시간 10분 30초는 얼마인가요?","options":[{"t":"9시간 28분 20초","correct":true},{"t":"9시간 27분 20초","mis":"M3-1-u5-X14"},{"t":"9시간 29분 20초","mis":"M3-1-u5-X14"},{"t":"9시간 28분 30초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 50 + 30 = 80 → 60초를 1분으로 받아올림, 분끼리 28.","8시간 17분 50초 + 1시간 10분 30초 = 9시간 28분 20초예요."],"variant_rule":{"alt":[{"stem":"5시간 35분 45초 + 7시간 15분 40초는 얼마인가요?","options":[{"t":"12시간 51분 25초","correct":true},{"t":"12시간 50분 25초","mis":"M3-1-u5-X14"},{"t":"12시간 52분 25초","mis":"M3-1-u5-X14"},{"t":"12시간 51분 35초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 45 + 40 = 85 → 60초를 1분으로 받아올림, 분끼리 51.","5시간 35분 45초 + 7시간 15분 40초 = 12시간 51분 25초예요."],"asset":null},{"stem":"3시간 25분 50초 + 7시간 20분 20초는 얼마인가요?","options":[{"t":"10시간 46분 10초","correct":true},{"t":"10시간 45분 10초","mis":"M3-1-u5-X14"},{"t":"10시간 47분 10초","mis":"M3-1-u5-X14"},{"t":"10시간 46분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 50 + 20 = 70 → 60초를 1분으로 받아올림, 분끼리 46.","3시간 25분 50초 + 7시간 20분 20초 = 10시간 46분 10초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#6','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',2,'ox','auto','2분 50초 + 30초를 계산해 「2분 80초」라고 답을 썼어요. 답을 바르게 나타냈어요.',ARRAY['M3-1-u5-X13']::text[],true,'{"seq":6,"concept":"M3-1-u5-C7","difficulty":2,"kind":"ox","stem":"2분 50초 + 30초를 계산해 「2분 80초」라고 답을 썼어요. 답을 바르게 나타냈어요.","answer":"X","reason_options":[{"t":"60초가 넘으면 1분으로 받아올림해 나타내야 해서","correct":true},{"t":"같은 단위끼리 더했으니 그대로 써도 되어서","mis":"M3-1-u5-X13"}],"mis":"M3-1-u5-X13","explanation":["같은 단위끼리 더하면 2분 80초.","60이 넘는 자리는 윗단위로 받아올림해요.","2분 50초 + 30초 = 3분 20초예요."],"variant_rule":{"alt":[{"stem":"25분 45초 + 35초를 계산해 「25분 80초」라고 답을 썼어요. 답을 바르게 나타냈어요.","answer":"X","reason_options":[{"t":"60초가 넘으면 1분으로 받아올림해 나타내야 해서","correct":true},{"t":"같은 단위끼리 더했으니 그대로 써도 되어서","mis":"M3-1-u5-X13"}],"explanation":["같은 단위끼리 더하면 25분 80초.","60이 넘는 자리는 윗단위로 받아올림해요.","25분 45초 + 35초 = 26분 20초예요."],"asset":null},{"stem":"10분 45초 + 35초를 계산해 「10분 80초」라고 답을 썼어요. 답을 바르게 나타냈어요.","answer":"X","reason_options":[{"t":"60초가 넘으면 1분으로 받아올림해 나타내야 해서","correct":true},{"t":"같은 단위끼리 더했으니 그대로 써도 되어서","mis":"M3-1-u5-X13"}],"explanation":["같은 단위끼리 더하면 10분 80초.","60이 넘는 자리는 윗단위로 받아올림해요.","10분 45초 + 35초 = 11분 20초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#7','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',2,'mc','auto','숲 해설 듣기를 3시 20분에 시작해서 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":7,"concept":"M3-1-u5-C7","difficulty":2,"kind":"mc","stem":"숲 해설 듣기를 3시 20분에 시작해서 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"3시 50분","correct":true},{"t":"3시 40분","mis":"M3-1-u5-X21"},{"t":"4시 50분","mis":"M3-1-u5-X21"},{"t":"2시 50분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","3시 20분 + 30분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 3시 50분이에요."],"variant_rule":{"alt":[{"stem":"씨앗 심기를 7시 25분에 시작해서 15분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 40분","correct":true},{"t":"22시 25분","mis":"M3-1-u5-X15"},{"t":"7시 50분","mis":"M3-1-u5-X21"},{"t":"7시 30분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","7시 25분 + 15분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 7시 40분이에요."],"asset":null},{"stem":"나무 이름표 달기를 1시 25분에 시작해서 5분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"1시 30분","correct":true},{"t":"6시 25분","mis":"M3-1-u5-X15"},{"t":"1시 40분","mis":"M3-1-u5-X21"},{"t":"1시 20분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","1시 25분 + 5분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 1시 30분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#8','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',2,'sa','auto','시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u5-C7","difficulty":2,"kind":"sa","stem":"시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["초부터 같은 단위끼리 더해요.","60이 넘으면 60을 빼고 윗단위에 1을 더해요(받아올림).","12분 45초 + 25분 30초 = 38분 15초 — ?는 15예요."],"asset":{"type":"expr_grid","rows":[["","12분","45초"],["+","25분","30초"],["","38분",null]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["46"],"explanation":["초부터 같은 단위끼리 더해요.","60이 넘으면 60을 빼고 윗단위에 1을 더해요(받아올림).","45분 20초 + 45초 = 46분 5초 — ?는 46이에요."],"asset":{"type":"expr_grid","rows":[["","45분","20초"],["+","","45초"],["",null,"5초"]]}},{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["30"],"explanation":["초부터 같은 단위끼리 더해요.","60이 넘으면 60을 빼고 윗단위에 1을 더해요(받아올림).","45분 35초 + 55초 = 46분 30초 — ?는 30이에요."],"asset":{"type":"expr_grid","rows":[["","45분","35초"],["+","","55초"],["","46분",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#9','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',2,'sa','auto','50초 + 30초 = 1분 □초 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u5-C7","difficulty":2,"kind":"sa","stem":"50초 + 30초 = 1분 □초 — □에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["50 + 30 = 80초.","60초 = 1분 — 60초를 1분으로 받아올림해요.","80초 = 1분 20초 — □ = 20."],"variant_rule":{"alt":[{"stem":"50초 + 50초 = 1분 □초 — □에 알맞은 수를 쓰세요.","answer":["40"],"explanation":["50 + 50 = 100초.","60초 = 1분 — 60초를 1분으로 받아올림해요.","100초 = 1분 40초 — □ = 40."],"asset":null},{"stem":"35초 + 50초 = 1분 □초 — □에 알맞은 수를 쓰세요.","answer":["25"],"explanation":["35 + 50 = 85초.","60초 = 1분 — 60초를 1분으로 받아올림해요.","85초 = 1분 25초 — □ = 25."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_basic#10','math',3,1,'u5','L07','g3_1_math_u5_L07_basic','lesson_basic','M3-1-u5-C7',3,'error','auto','시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?',ARRAY['M3-1-u5-X13','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C7","difficulty":3,"kind":"error","stem":"시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?","options":[{"t":"태오 — 「1분 25초 + 40초 = 1분 65초」","correct":true,"mis_target":"M3-1-u5-X13"},{"t":"서윤 — 「1분 25초 + 40초 = 2분 5초」","mis":"M3-1-u5-X20"},{"t":"하린 — 「30초 + 30초 = 1분」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 더하면 1분 65초.","60이 넘는 자리는 받아올림해요.","1분 25초 + 40초 = 2분 5초 — 태오는 받아올림을 안 했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?","options":[{"t":"시우 — 「15분 40초 + 50초 = 15분 90초」","correct":true,"mis_target":"M3-1-u5-X13"},{"t":"지유 — 「15분 40초 + 50초 = 16분 30초」","mis":"M3-1-u5-X20"},{"t":"하은 — 「20분 + 20분 = 40분」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 더하면 15분 90초.","60이 넘는 자리는 받아올림해요.","15분 40초 + 50초 = 16분 30초 — 시우는 받아올림을 안 했어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?","options":[{"t":"하은 — 「35분 35초 + 20분 55초 = 55분 90초」","correct":true,"mis_target":"M3-1-u5-X13"},{"t":"하린 — 「35분 35초 + 20분 55초 = 56분 30초」","mis":"M3-1-u5-X20"},{"t":"하랑 — 「30초 + 30초 = 1분」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 더하면 55분 90초.","60이 넘는 자리는 받아올림해요.","35분 35초 + 20분 55초 = 56분 30초 — 하은은 받아올림을 안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#1','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',2,'mc','auto','나무 이름표 달기를 1시 50분에 시작해서 1시간 25분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":1,"concept":"M3-1-u5-C7","difficulty":2,"kind":"mc","stem":"나무 이름표 달기를 1시 50분에 시작해서 1시간 25분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"3시 15분","correct":true},{"t":"2시 15분","mis":"M3-1-u5-X14"},{"t":"4시 15분","mis":"M3-1-u5-X14"},{"t":"3시 25분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","1시 50분 + 1시간 25분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 3시 15분이에요."],"variant_rule":{"alt":[{"stem":"쓰레기 줍기를 3시 50분에 시작해서 1시간 40분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 30분","correct":true},{"t":"4시 30분","mis":"M3-1-u5-X14"},{"t":"6시 30분","mis":"M3-1-u5-X14"},{"t":"5시 40분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","3시 50분 + 1시간 40분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 5시 30분이에요."],"asset":null},{"stem":"새 관찰을 1시 45분에 시작해서 45분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 30분","correct":true},{"t":"1시 30분","mis":"M3-1-u5-X14"},{"t":"3시 30분","mis":"M3-1-u5-X14"},{"t":"2시 40분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","1시 45분 + 45분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 2시 30분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#2','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',2,'sa','auto','시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u5-C7","difficulty":2,"kind":"sa","stem":"시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["25"],"explanation":["초부터 같은 단위끼리 더해요.","60이 넘으면 60을 빼고 윗단위에 1을 더해요(받아올림).","2시 45분 + 40분 = 3시 25분 — ?는 25예요."],"asset":{"type":"expr_grid","rows":[["","2시","45분"],["+","","40분"],["","3시",null]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["30"],"explanation":["초부터 같은 단위끼리 더해요.","60이 넘으면 60을 빼고 윗단위에 1을 더해요(받아올림).","5시 40분 + 2시간 50분 = 8시 30분 — ?는 30이에요."],"asset":{"type":"expr_grid","rows":[["","5시","40분"],["+","2시간","50분"],["","8시",null]]}},{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["초부터 같은 단위끼리 더해요.","60이 넘으면 60을 빼고 윗단위에 1을 더해요(받아올림).","2시 15분 + 50분 = 3시 5분 — ?는 5예요."],"asset":{"type":"expr_grid","rows":[["","2시","15분"],["+","","50분"],["","3시",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#3','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',3,'mc','auto','2시간 35분 40초 + 1시간 45분 30초는 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"2시간 35분 40초 + 1시간 45분 30초는 얼마인가요?","options":[{"t":"4시간 21분 10초","correct":true},{"t":"3시간 20분 10초","mis":"M3-1-u5-X14"},{"t":"5시간 21분 10초","mis":"M3-1-u5-X14"},{"t":"4시간 21분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 40 + 30 = 70 → 60초를 1분으로 받아올림, 분끼리 81 → 1시간으로 받아올림.","2시간 35분 40초 + 1시간 45분 30초 = 4시간 21분 10초예요."],"variant_rule":{"alt":[{"stem":"2시간 30분 20초 + 7시간 45분 55초는 얼마인가요?","options":[{"t":"10시간 16분 15초","correct":true},{"t":"9시간 15분 15초","mis":"M3-1-u5-X14"},{"t":"11시간 16분 15초","mis":"M3-1-u5-X14"},{"t":"10시간 16분 25초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 20 + 55 = 75 → 60초를 1분으로 받아올림, 분끼리 76 → 1시간으로 받아올림.","2시간 30분 20초 + 7시간 45분 55초 = 10시간 16분 15초예요."],"asset":null},{"stem":"4시간 55분 55초 + 20분 55초는 얼마인가요?","options":[{"t":"5시간 16분 50초","correct":true},{"t":"4시간 15분 50초","mis":"M3-1-u5-X14"},{"t":"6시간 16분 50초","mis":"M3-1-u5-X14"},{"t":"5시간 26분 50초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 55 + 55 = 110 → 60초를 1분으로 받아올림, 분끼리 76 → 1시간으로 받아올림.","4시간 55분 55초 + 20분 55초 = 5시간 16분 50초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#4','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',3,'mc','auto','동굴 체험을 2시 30분 45초에 시작해서 15분 20초 동안 했어요. 끝난 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X15']::text[],true,'{"seq":4,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"동굴 체험을 2시 30분 45초에 시작해서 15분 20초 동안 했어요. 끝난 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"2시 46분 5초","correct":true},{"t":"2시 45분 5초","mis":"M3-1-u5-X14"},{"t":"17시 50분 45초","mis":"M3-1-u5-X15"},{"t":"2시 47분 5초","mis":"M3-1-u5-X14"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","2시 30분 45초 + 15분 20초 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 2시 46분 5초예요."],"variant_rule":{"alt":[{"stem":"숲 해설 듣기를 7시 10분 30초에 시작해서 2시간 10분 45초 동안 했어요. 끝난 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"9시 21분 15초","correct":true},{"t":"9시 20분 15초","mis":"M3-1-u5-X14"},{"t":"9시 22분 15초","mis":"M3-1-u5-X14"},{"t":"9시 21분 25초","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","7시 10분 30초 + 2시간 10분 45초 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 9시 21분 15초예요."],"asset":null},{"stem":"씨앗 심기를 5시 5분 45초에 시작해서 2시간 10분 25초 동안 했어요. 끝난 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"7시 16분 10초","correct":true},{"t":"7시 15분 10초","mis":"M3-1-u5-X14"},{"t":"7시 17분 10초","mis":"M3-1-u5-X14"},{"t":"7시 16분 20초","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","5시 5분 45초 + 2시간 10분 25초 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 7시 16분 10초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#5','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',3,'error','auto','시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?',ARRAY['M3-1-u5-X13','M3-1-u5-X20']::text[],true,'{"seq":5,"concept":"M3-1-u5-C7","difficulty":3,"kind":"error","stem":"시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?","options":[{"t":"민준 — 「1시간 40분 + 1시간 35분 = 2시간 75분」","correct":true,"mis_target":"M3-1-u5-X13"},{"t":"은우 — 「1시간 40분 + 1시간 35분 = 3시간 15분」","mis":"M3-1-u5-X20"},{"t":"하랑 — 「20분 + 20분 = 40분」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 더하면 2시간 75분.","60이 넘는 자리는 받아올림해요.","1시간 40분 + 1시간 35분 = 3시간 15분 — 민준은 받아올림을 안 했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?","options":[{"t":"태오 — 「6시간 25분 + 5시간 40분 = 11시간 65분」","correct":true,"mis_target":"M3-1-u5-X13"},{"t":"하은 — 「6시간 25분 + 5시간 40분 = 12시간 5분」","mis":"M3-1-u5-X20"},{"t":"하랑 — 「30초 + 30초 = 1분」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 더하면 11시간 65분.","60이 넘는 자리는 받아올림해요.","6시간 25분 + 5시간 40분 = 12시간 5분 — 태오는 받아올림을 안 했어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 시간의 덧셈을 하고 답을 바르게 나타내지 않은 친구는 누구인가요?","options":[{"t":"은우 — 「3시간 50분 + 20분 = 3시간 70분」","correct":true,"mis_target":"M3-1-u5-X13"},{"t":"하린 — 「3시간 50분 + 20분 = 4시간 10분」","mis":"M3-1-u5-X20"},{"t":"도윤 — 「15분 + 20분 = 35분」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 더하면 3시간 70분.","60이 넘는 자리는 받아올림해요.","3시간 50분 + 20분 = 4시간 10분 — 은우는 받아올림을 안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#6','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',3,'mc','auto','씨앗 심기를 25분 40초, 물 주기를 18분 35초 동안 했어요. 두 활동을 한 시간은 모두 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":6,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"씨앗 심기를 25분 40초, 물 주기를 18분 35초 동안 했어요. 두 활동을 한 시간은 모두 얼마인가요?","options":[{"t":"44분 15초","correct":true},{"t":"43분 15초","mis":"M3-1-u5-X14"},{"t":"45분 15초","mis":"M3-1-u5-X14"},{"t":"44분 25초","mis":"M3-1-u5-X21"}],"explanation":["두 시간을 더해요.","초끼리·분끼리 더하고 60이 넘으면 받아올림해요.","25분 40초 + 18분 35초 = 44분 15초예요."],"variant_rule":{"alt":[{"stem":"새 관찰을 20분 45초, 나뭇잎 그리기를 10분 30초 동안 했어요. 두 활동을 한 시간은 모두 얼마인가요?","options":[{"t":"31분 15초","correct":true},{"t":"30분 15초","mis":"M3-1-u5-X14"},{"t":"32분 15초","mis":"M3-1-u5-X14"},{"t":"31분 25초","mis":"M3-1-u5-X21"}],"explanation":["두 시간을 더해요.","초끼리·분끼리 더하고 60이 넘으면 받아올림해요.","20분 45초 + 10분 30초 = 31분 15초예요."],"asset":null},{"stem":"동굴 체험을 30분 55초, 숲 해설 듣기를 15분 15초 동안 했어요. 두 활동을 한 시간은 모두 얼마인가요?","options":[{"t":"46분 10초","correct":true},{"t":"45분 10초","mis":"M3-1-u5-X14"},{"t":"47분 10초","mis":"M3-1-u5-X14"},{"t":"46분 20초","mis":"M3-1-u5-X21"}],"explanation":["두 시간을 더해요.","초끼리·분끼리 더하고 60이 넘으면 받아올림해요.","30분 55초 + 15분 15초 = 46분 10초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#7','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',3,'mc','auto','○ 안에 알맞은 것을 고르세요. 1시간 25분 + 4시간 40분 ○ 6시간 15분',ARRAY['M3-1-u5-X13','M3-1-u5-X14','M3-1-u5-X20']::text[],true,'{"seq":7,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"○ 안에 알맞은 것을 고르세요. 1시간 25분 + 4시간 40분 ○ 6시간 15분","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X13"},{"t":"=","mis":"M3-1-u5-X14"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["먼저 왼쪽을 계산해요.","1시간 25분 + 4시간 40분 = 6시간 5분이에요.","6시간 5분 < 6시간 15분 — <예요."],"variant_rule":{"alt":[{"stem":"○ 안에 알맞은 것을 고르세요. 5시간 40분 + 2시간 35분 ○ 8시간 25분","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X13"},{"t":"=","mis":"M3-1-u5-X14"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["먼저 왼쪽을 계산해요.","5시간 40분 + 2시간 35분 = 8시간 15분이에요.","8시간 15분 < 8시간 25분 — <예요."],"asset":null},{"stem":"○ 안에 알맞은 것을 고르세요. 7시간 50분 + 2시간 55분 ○ 10시간 55분","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X13"},{"t":"=","mis":"M3-1-u5-X14"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["먼저 왼쪽을 계산해요.","7시간 50분 + 2시간 55분 = 10시간 45분이에요.","10시간 45분 < 10시간 55분 — <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#8','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',4,'essay','teacher','8시간 17분 50초 + 1시간 10분 30초를 계산하는 방법을 쓰고, 받아올림을 어디에서 했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C7","difficulty":4,"kind":"essay","stem":"8시간 17분 50초 + 1시간 10분 30초를 계산하는 방법을 쓰고, 받아올림을 어디에서 했는지 설명해 보세요.","answer_guide":{"answer":"예: 초끼리 50 + 30 = 80초이고 60초는 1분이므로 1분 20초가 된다 — 20초를 쓰고 1분을 받아올린다. 분끼리 17 + 10 + 1 = 28분, 시간끼리 8 + 1 = 9시간이다. 답은 9시간 28분 20초이다.","scoring_points":["초끼리 더해 80초를 1분 20초로 받아올렸는가","분끼리 더할 때 받아올린 1을 더했는가","9시간 28분 20초를 구했는가"]},"explanation":["초: 50 + 30 = 80 → 1분 20초.","분: 17 + 10 + 1 = 28.","9시간 28분 20초."],"asset":{"type":"expr_grid","rows":[["","8시간","17분","50초"],["+","1시간","10분","30초"],["",null,null,null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#9','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',4,'essay','teacher','하랑이는 「2분 50초 + 30초 = 2분 80초」라고 했어요. 하랑이의 답이 왜 알맞지 않은지 설명하고, 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C7","difficulty":4,"kind":"essay","stem":"하랑이는 「2분 50초 + 30초 = 2분 80초」라고 했어요. 하랑이의 답이 왜 알맞지 않은지 설명하고, 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 80초는 60초를 넘으므로 1분 20초로 받아올림해야 한다. 2분에 받아올린 1분을 더하면 3분이 되어 답은 3분 20초이다.","scoring_points":["80초가 60초를 넘는다고 했는가","80초 = 1분 20초로 받아올렸는가","3분 20초로 고쳤는가"]},"explanation":["50 + 30 = 80초.","80초 = 1분 20초.","2분 + 1분 20초 = 3분 20초."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L07_challenge#10','math',3,1,'u5','L07','g3_1_math_u5_L07_challenge','lesson_challenge','M3-1-u5-C7',4,'mc','auto','6시 25분에 숲 해설을 듣기 시작해서 25분 동안 듣고, 바로 이어서 55분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X14']::text[],true,'{"seq":10,"concept":"M3-1-u5-C7","difficulty":4,"kind":"mc","stem":"6시 25분에 숲 해설을 듣기 시작해서 25분 동안 듣고, 바로 이어서 55분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 45분","correct":true},{"t":"6시 50분","mis":"M3-1-u5-X19"},{"t":"7시 20분","mis":"M3-1-u5-X19"},{"t":"6시 45분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","6시 25분 + 25분 = 6시 50분.","6시 50분 + 55분 = 7시 45분이에요."],"variant_rule":{"alt":[{"stem":"5시 10분에 숲 해설을 듣기 시작해서 50분 동안 듣고, 바로 이어서 1시간 25분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 25분","correct":true},{"t":"6시","mis":"M3-1-u5-X19"},{"t":"6시 35분","mis":"M3-1-u5-X19"},{"t":"6시 25분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","5시 10분 + 50분 = 6시.","6시 + 1시간 25분 = 7시 25분이에요."],"asset":null},{"stem":"3시 5분에 숲 해설을 듣기 시작해서 40분 동안 듣고, 바로 이어서 1시간 40분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 25분","correct":true},{"t":"3시 45분","mis":"M3-1-u5-X19"},{"t":"4시 45분","mis":"M3-1-u5-X19"},{"t":"4시 25분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","3시 5분 + 40분 = 3시 45분.","3시 45분 + 1시간 40분 = 5시 25분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#1','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',1,'mc','auto','3시간 50분 − 1시간 20분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":1,"concept":"M3-1-u5-C8","difficulty":1,"kind":"mc","stem":"3시간 50분 − 1시간 20분은 얼마인가요?","options":[{"t":"2시간 30분","correct":true},{"t":"2시간 40분","mis":"M3-1-u5-X21"},{"t":"2시간 20분","mis":"M3-1-u5-X21"},{"t":"3시간 30분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","3시간 50분 − 1시간 20분 = 2시간 30분이에요."],"variant_rule":{"alt":[{"stem":"7시간 45분 − 3시간 20분은 얼마인가요?","options":[{"t":"4시간 25분","correct":true},{"t":"4시간 35분","mis":"M3-1-u5-X21"},{"t":"4시간 15분","mis":"M3-1-u5-X21"},{"t":"5시간 25분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","7시간 45분 − 3시간 20분 = 4시간 25분이에요."],"asset":null},{"stem":"6시간 55분 − 15분은 얼마인가요?","options":[{"t":"6시간 40분","correct":true},{"t":"6시간 50분","mis":"M3-1-u5-X21"},{"t":"6시간 30분","mis":"M3-1-u5-X21"},{"t":"7시간 40분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","6시간 55분 − 15분 = 6시간 40분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
