INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#3','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',1,'mc','auto','1분 10초 − 40초는 얼마인가요?',ARRAY['M3-1-u5-X17','M3-1-u5-X09','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C8","difficulty":1,"kind":"mc","stem":"1분 10초 − 40초는 얼마인가요?","options":[{"t":"30초","correct":true},{"t":"1분 30초","mis":"M3-1-u5-X17"},{"t":"70초","mis":"M3-1-u5-X09"},{"t":"40초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요 — 빌려준 자리는 1 줄어요.","1분 10초 − 40초 = 30초예요."],"variant_rule":{"alt":[{"stem":"30분 5초 − 25분 55초는 얼마인가요?","options":[{"t":"4분 10초","correct":true},{"t":"5분 50초","mis":"M3-1-u5-X17"},{"t":"5분 10초","mis":"M3-1-u5-X16"},{"t":"4분 50초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요 — 빌려준 자리는 1 줄어요.","30분 5초 − 25분 55초 = 4분 10초예요."],"asset":null},{"stem":"15분 10초 − 45초는 얼마인가요?","options":[{"t":"14분 25초","correct":true},{"t":"15분 35초","mis":"M3-1-u5-X17"},{"t":"15분 25초","mis":"M3-1-u5-X16"},{"t":"14분 65초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요 — 빌려준 자리는 1 줄어요.","15분 10초 − 45초 = 14분 25초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#4','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',1,'mc','auto','3시간 10분 − 1시간 30분은 얼마인가요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":4,"concept":"M3-1-u5-C8","difficulty":1,"kind":"mc","stem":"3시간 10분 − 1시간 30분은 얼마인가요?","options":[{"t":"1시간 40분","correct":true},{"t":"2시간 20분","mis":"M3-1-u5-X17"},{"t":"2시간 40분","mis":"M3-1-u5-X16"},{"t":"1시간 80분","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","분이 모자라 1시간(60분)을 빌려 와요 — 빌려준 자리는 1 줄어요.","3시간 10분 − 1시간 30분 = 1시간 40분이에요."],"variant_rule":{"alt":[{"stem":"8시간 30분 − 55분은 얼마인가요?","options":[{"t":"7시간 35분","correct":true},{"t":"8시간 25분","mis":"M3-1-u5-X17"},{"t":"8시간 35분","mis":"M3-1-u5-X16"},{"t":"7시간 75분","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","분이 모자라 1시간(60분)을 빌려 와요 — 빌려준 자리는 1 줄어요.","8시간 30분 − 55분 = 7시간 35분이에요."],"asset":null},{"stem":"8시간 5분 − 10분은 얼마인가요?","options":[{"t":"7시간 55분","correct":true},{"t":"8시간 5분","mis":"M3-1-u5-X17"},{"t":"8시간 55분","mis":"M3-1-u5-X16"},{"t":"7시간 95분","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","분이 모자라 1시간(60분)을 빌려 와요 — 빌려준 자리는 1 줄어요.","8시간 5분 − 10분 = 7시간 55분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#5','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',2,'mc','auto','9시간 20분 30초 − 7시간 10분 40초는 얼마인가요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":5,"concept":"M3-1-u5-C8","difficulty":2,"kind":"mc","stem":"9시간 20분 30초 − 7시간 10분 40초는 얼마인가요?","options":[{"t":"2시간 9분 50초","correct":true},{"t":"2시간 10분 10초","mis":"M3-1-u5-X17"},{"t":"2시간 10분 50초","mis":"M3-1-u5-X16"},{"t":"2시간 9분 90초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요 — 빌려준 자리는 1 줄어요.","9시간 20분 30초 − 7시간 10분 40초 = 2시간 9분 50초예요."],"variant_rule":{"alt":[{"stem":"7시간 45분 15초 − 3시간 10분 25초는 얼마인가요?","options":[{"t":"4시간 34분 50초","correct":true},{"t":"4시간 35분 10초","mis":"M3-1-u5-X17"},{"t":"4시간 35분 50초","mis":"M3-1-u5-X16"},{"t":"4시간 34분 90초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요 — 빌려준 자리는 1 줄어요.","7시간 45분 15초 − 3시간 10분 25초 = 4시간 34분 50초예요."],"asset":null},{"stem":"4시간 50분 45초 − 2시간 20분 50초는 얼마인가요?","options":[{"t":"2시간 29분 55초","correct":true},{"t":"2시간 30분 5초","mis":"M3-1-u5-X17"},{"t":"2시간 30분 55초","mis":"M3-1-u5-X16"},{"t":"2시간 29분 95초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요 — 빌려준 자리는 1 줄어요.","4시간 50분 45초 − 2시간 20분 50초 = 2시간 29분 55초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#6','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',2,'ox','auto','1시부터 4시까지는 4시간이에요.',ARRAY['M3-1-u5-X18']::text[],true,'{"seq":6,"concept":"M3-1-u5-C8","difficulty":2,"kind":"ox","stem":"1시부터 4시까지는 4시간이에요.","answer":"X","reason_options":[{"t":"끝난 시각에서 시작 시각을 빼면 4 − 1 = 3시간이라서","correct":true},{"t":"1시, …, 4시 — 숫자를 세면 4개라서","mis":"M3-1-u5-X18"}],"mis":"M3-1-u5-X18","explanation":["걸린 시간 = 끝난 시각 − 시작 시각.","4 − 1 = 3.","3시간이에요 — 시 숫자 개수를 세면 안 돼요."],"variant_rule":{"alt":[{"stem":"6시부터 9시까지는 4시간이에요.","answer":"X","reason_options":[{"t":"끝난 시각에서 시작 시각을 빼면 9 − 6 = 3시간이라서","correct":true},{"t":"6시, …, 9시 — 숫자를 세면 4개라서","mis":"M3-1-u5-X18"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각.","9 − 6 = 3.","3시간이에요 — 시 숫자 개수를 세면 안 돼요."],"asset":null},{"stem":"4시부터 6시까지는 3시간이에요.","answer":"X","reason_options":[{"t":"끝난 시각에서 시작 시각을 빼면 6 − 4 = 2시간이라서","correct":true},{"t":"4시, …, 6시 — 숫자를 세면 3개라서","mis":"M3-1-u5-X18"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각.","6 − 4 = 2.","2시간이에요 — 시 숫자 개수를 세면 안 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#7','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',2,'mc','auto','불 끄기 캠페인 영화가 2시 10분에 시작해서 3시 50분에 끝났어요. 얼마 동안 했나요?',ARRAY['M3-1-u5-X18','M3-1-u5-X21']::text[],true,'{"seq":7,"concept":"M3-1-u5-C8","difficulty":2,"kind":"mc","stem":"불 끄기 캠페인 영화가 2시 10분에 시작해서 3시 50분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 40분","correct":true},{"t":"2시간 40분","mis":"M3-1-u5-X18"},{"t":"1시간 50분","mis":"M3-1-u5-X21"},{"t":"1시간 30분","mis":"M3-1-u5-X21"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 50분 − 2시 10분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 40분 동안 했어요."],"variant_rule":{"alt":[{"stem":"숲 해설이 2시 35분에 시작해서 5시 40분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 5분","correct":true},{"t":"4시간 5분","mis":"M3-1-u5-X18"},{"t":"3시간 15분","mis":"M3-1-u5-X21"},{"t":"2시간 5분","mis":"M3-1-u5-X21"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 40분 − 2시 35분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 5분 동안 했어요."],"asset":null},{"stem":"동굴 체험이 1시 35분에 시작해서 2시 50분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 15분","correct":true},{"t":"2시간 15분","mis":"M3-1-u5-X18"},{"t":"1시간 25분","mis":"M3-1-u5-X21"},{"t":"1시간 5분","mis":"M3-1-u5-X21"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","2시 50분 − 1시 35분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 15분 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#8','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',2,'sa','auto','시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u5-C8","difficulty":2,"kind":"sa","stem":"시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["초부터 같은 단위끼리 빼요.","모자라면 윗단위에서 60을 빌려 오고, 빌려준 자리는 1 줄여요.","5분 20초 − 2분 45초 = 2분 35초 — ?는 2."],"asset":{"type":"expr_grid","rows":[["","5분","20초"],["−","2분","45초"],["",null,"35초"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["초부터 같은 단위끼리 빼요.","모자라면 윗단위에서 60을 빌려 오고, 빌려준 자리는 1 줄여요.","35분 15초 − 20분 55초 = 14분 20초 — ?는 20."],"asset":{"type":"expr_grid","rows":[["","35분","15초"],["−","20분","55초"],["","14분",null]]}},{"stem":"이번에는 다른 문제예요. 시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["39"],"explanation":["초부터 같은 단위끼리 빼요.","모자라면 윗단위에서 60을 빌려 오고, 빌려준 자리는 1 줄여요.","45분 15초 − 5분 55초 = 39분 20초 — ?는 39."],"asset":{"type":"expr_grid","rows":[["","45분","15초"],["−","5분","55초"],["",null,"20초"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#9','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',2,'sa','auto','1분 − 40초 = □초 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u5-C8","difficulty":2,"kind":"sa","stem":"1분 − 40초 = □초 — □에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["1분 = 60초로 바꿔요.","60 − 40 = 20.","□ = 20 — 100초에서 빼면 안 돼요."],"variant_rule":{"alt":[{"stem":"1분 − 45초 = □초 — □에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["1분 = 60초로 바꿔요.","60 − 45 = 15.","□ = 15 — 100초에서 빼면 안 돼요."],"asset":null},{"stem":"1분 − 15초 = □초 — □에 알맞은 수를 쓰세요.","answer":["45"],"explanation":["1분 = 60초로 바꿔요.","60 − 15 = 45.","□ = 45 — 100초에서 빼면 안 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_basic#10','math',3,1,'u5','L08','g3_1_math_u5_L08_basic','lesson_basic','M3-1-u5-C8',3,'error','auto','시간 계산을 잘못한 친구는 누구인가요?',ARRAY['M3-1-u5-X17','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C8","difficulty":3,"kind":"error","stem":"시간 계산을 잘못한 친구는 누구인가요?","options":[{"t":"은우 — 「9시간 20분 30초 − 7시간 10분 40초 = 2시간 10분 10초」","correct":true,"mis_target":"M3-1-u5-X17"},{"t":"하은 — 「9시간 20분 30초 − 7시간 10분 40초 = 2시간 9분 50초」","mis":"M3-1-u5-X20"},{"t":"태오 — 「2시부터 5시까지는 3시간」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 빼고 모자라면 60을 빌려 와요.","빌려준 자리는 1 줄어요.","9시간 20분 30초 − 7시간 10분 40초 = 2시간 9분 50초 — 은우는 잘못 계산했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간 계산을 잘못한 친구는 누구인가요?","options":[{"t":"은우 — 「2시간 30분 5초 − 1시간 5분 25초 = 1시간 25분 20초」","correct":true,"mis_target":"M3-1-u5-X17"},{"t":"서윤 — 「2시간 30분 5초 − 1시간 5분 25초 = 1시간 24분 40초」","mis":"M3-1-u5-X20"},{"t":"지유 — 「1분 − 40초 = 20초」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 빼고 모자라면 60을 빌려 와요.","빌려준 자리는 1 줄어요.","2시간 30분 5초 − 1시간 5분 25초 = 1시간 24분 40초 — 은우는 잘못 계산했어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 시간 계산을 잘못한 친구는 누구인가요?","options":[{"t":"태오 — 「5시간 20분 20초 − 15분 30초 = 5시간 5분 10초」","correct":true,"mis_target":"M3-1-u5-X17"},{"t":"하린 — 「5시간 20분 20초 − 15분 30초 = 5시간 4분 50초」","mis":"M3-1-u5-X20"},{"t":"민준 — 「1시부터 5시까지는 4시간」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 빼고 모자라면 60을 빌려 와요.","빌려준 자리는 1 줄어요.","5시간 20분 20초 − 15분 30초 = 5시간 4분 50초 — 태오는 잘못 계산했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#1','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',2,'mc','auto','불 끄기 캠페인 영화가 3시 10분에 시작해서 5시 5분에 끝났어요. 얼마 동안 했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":1,"concept":"M3-1-u5-C8","difficulty":2,"kind":"mc","stem":"불 끄기 캠페인 영화가 3시 10분에 시작해서 5시 5분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 55분","correct":true},{"t":"2시간 5분","mis":"M3-1-u5-X17"},{"t":"2시간 55분","mis":"M3-1-u5-X16"},{"t":"1시간 95분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 5분 − 3시 10분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 55분 동안 했어요."],"variant_rule":{"alt":[{"stem":"숲 해설이 1시 15분에 시작해서 4시 10분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"2시간 55분","correct":true},{"t":"3시간 5분","mis":"M3-1-u5-X17"},{"t":"3시간 55분","mis":"M3-1-u5-X16"},{"t":"2시간 95분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","4시 10분 − 1시 15분 — 같은 단위끼리, 모자라면 빌려 와요.","2시간 55분 동안 했어요."],"asset":null},{"stem":"동굴 체험이 2시 35분에 시작해서 4시 15분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 40분","correct":true},{"t":"2시간 20분","mis":"M3-1-u5-X17"},{"t":"2시간 40분","mis":"M3-1-u5-X16"},{"t":"1시간 80분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","4시 15분 − 2시 35분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 40분 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#2','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',2,'sa','auto','시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u5-C8","difficulty":2,"kind":"sa","stem":"시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["35"],"explanation":["초부터 같은 단위끼리 빼요.","모자라면 윗단위에서 60을 빌려 오고, 빌려준 자리는 1 줄여요.","4시 15분 − 2시 40분 = 1시간 35분 — ?는 35."],"asset":{"type":"expr_grid","rows":[["","4시","15분"],["−","2시","40분"],["","1시간",null]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["초부터 같은 단위끼리 빼요.","모자라면 윗단위에서 60을 빌려 오고, 빌려준 자리는 1 줄여요.","4시 5분 − 2시 55분 = 1시간 10분 — ?는 10."],"asset":{"type":"expr_grid","rows":[["","4시","5분"],["−","2시","55분"],["","1시간",null]]}},{"stem":"이번에는 다른 문제예요. 시간의 뺄셈을 세로로 계산했어요. ?에 알맞은 수를 쓰세요.","answer":["40"],"explanation":["초부터 같은 단위끼리 빼요.","모자라면 윗단위에서 60을 빌려 오고, 빌려준 자리는 1 줄여요.","5시 10분 − 2시 30분 = 2시간 40분 — ?는 40."],"asset":{"type":"expr_grid","rows":[["","5시","10분"],["−","2시","30분"],["","2시간",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#3','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',3,'mc','auto','5시간 10분 20초 − 2시간 35분 45초는 얼마인가요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":3,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"5시간 10분 20초 − 2시간 35분 45초는 얼마인가요?","options":[{"t":"2시간 34분 35초","correct":true},{"t":"3시간 25분 25초","mis":"M3-1-u5-X17"},{"t":"3시간 35분 35초","mis":"M3-1-u5-X16"},{"t":"2시간 34분 75초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요, 분이 모자라 1시간(60분)을 빌려 와요 — 빌려준 자리는 1 줄어요.","5시간 10분 20초 − 2시간 35분 45초 = 2시간 34분 35초예요."],"variant_rule":{"alt":[{"stem":"3시간 35분 15초 − 40분 20초는 얼마인가요?","options":[{"t":"2시간 54분 55초","correct":true},{"t":"3시간 5분 5초","mis":"M3-1-u5-X17"},{"t":"3시간 55분 55초","mis":"M3-1-u5-X16"},{"t":"2시간 54분 95초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요, 분이 모자라 1시간(60분)을 빌려 와요 — 빌려준 자리는 1 줄어요.","3시간 35분 15초 − 40분 20초 = 2시간 54분 55초예요."],"asset":null},{"stem":"4시간 10분 20초 − 2시간 15분 50초는 얼마인가요?","options":[{"t":"1시간 54분 30초","correct":true},{"t":"2시간 5분 30초","mis":"M3-1-u5-X17"},{"t":"2시간 55분 30초","mis":"M3-1-u5-X16"},{"t":"1시간 54분 70초","mis":"M3-1-u5-X09"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","초가 모자라 1분(60초)을 빌려 와요, 분이 모자라 1시간(60분)을 빌려 와요 — 빌려준 자리는 1 줄어요.","4시간 10분 20초 − 2시간 15분 50초 = 1시간 54분 30초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#4','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',3,'mc','auto','동굴 체험을 1시간 45분 동안 하고 4시 20분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X17','M3-1-u5-X16']::text[],true,'{"seq":4,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"동굴 체험을 1시간 45분 동안 하고 4시 20분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 35분","correct":true},{"t":"6시 5분","mis":"M3-1-u5-X20"},{"t":"3시 25분","mis":"M3-1-u5-X17"},{"t":"3시 35분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","4시 20분 − 1시간 45분 — 모자라면 60을 빌려 와요.","시작한 시각은 2시 35분이에요."],"variant_rule":{"alt":[{"stem":"환경 인형극을 45분 동안 하고 7시 25분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"6시 40분","correct":true},{"t":"8시 10분","mis":"M3-1-u5-X20"},{"t":"7시 20분","mis":"M3-1-u5-X17"},{"t":"7시 40분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","7시 25분 − 45분 — 모자라면 60을 빌려 와요.","시작한 시각은 6시 40분이에요."],"asset":null},{"stem":"숲 해설을 55분 동안 하고 3시 35분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 40분","correct":true},{"t":"4시 30분","mis":"M3-1-u5-X20"},{"t":"3시 20분","mis":"M3-1-u5-X17"},{"t":"3시 40분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","3시 35분 − 55분 — 모자라면 60을 빌려 와요.","시작한 시각은 2시 40분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#5','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',3,'error','auto','시간 계산을 잘못한 친구는 누구인가요?',ARRAY['M3-1-u5-X17','M3-1-u5-X20']::text[],true,'{"seq":5,"concept":"M3-1-u5-C8","difficulty":3,"kind":"error","stem":"시간 계산을 잘못한 친구는 누구인가요?","options":[{"t":"지유 — 「3시간 10분 − 1시간 30분 = 2시간 20분」","correct":true,"mis_target":"M3-1-u5-X17"},{"t":"하은 — 「3시간 10분 − 1시간 30분 = 1시간 40분」","mis":"M3-1-u5-X20"},{"t":"태오 — 「1분 − 40초 = 20초」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 빼고 모자라면 60을 빌려 와요.","빌려준 자리는 1 줄어요.","3시간 10분 − 1시간 30분 = 1시간 40분 — 지유는 잘못 계산했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시간 계산을 잘못한 친구는 누구인가요?","options":[{"t":"시우 — 「6시간 50분 − 1시간 55분 = 5시간 5분」","correct":true,"mis_target":"M3-1-u5-X17"},{"t":"민준 — 「6시간 50분 − 1시간 55분 = 4시간 55분」","mis":"M3-1-u5-X20"},{"t":"태오 — 「1시부터 5시까지는 4시간」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 빼고 모자라면 60을 빌려 와요.","빌려준 자리는 1 줄어요.","6시간 50분 − 1시간 55분 = 4시간 55분 — 시우는 잘못 계산했어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 시간 계산을 잘못한 친구는 누구인가요?","options":[{"t":"하랑 — 「8시간 20분 − 45분 = 8시간 25분」","correct":true,"mis_target":"M3-1-u5-X17"},{"t":"시우 — 「8시간 20분 − 45분 = 7시간 35분」","mis":"M3-1-u5-X20"},{"t":"서윤 — 「1분 − 40초 = 20초」","mis":"M3-1-u5-X20"}],"explanation":["같은 단위끼리 빼고 모자라면 60을 빌려 와요.","빌려준 자리는 1 줄어요.","8시간 20분 − 45분 = 7시간 35분 — 하랑은 잘못 계산했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#6','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',3,'mc','auto','숲 해설이 2시 30분에 시작해서 3시 20분 15초에 끝났어요. 얼마 동안 했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":6,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"숲 해설이 2시 30분에 시작해서 3시 20분 15초에 끝났어요. 얼마 동안 했나요?","options":[{"t":"50분 15초","correct":true},{"t":"1시간 10분 15초","mis":"M3-1-u5-X17"},{"t":"1시간 50분 15초","mis":"M3-1-u5-X16"},{"t":"90분 15초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 20분 15초 − 2시 30분 — 같은 단위끼리, 모자라면 빌려 와요.","50분 15초 동안 했어요."],"variant_rule":{"alt":[{"stem":"동굴 체험이 2시 55분 40초에 시작해서 5시 20분 45초에 끝났어요. 얼마 동안 했나요?","options":[{"t":"2시간 25분 5초","correct":true},{"t":"3시간 35분 5초","mis":"M3-1-u5-X17"},{"t":"3시간 25분 5초","mis":"M3-1-u5-X16"},{"t":"2시간 65분 5초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 20분 45초 − 2시 55분 40초 — 같은 단위끼리, 모자라면 빌려 와요.","2시간 25분 5초 동안 했어요."],"asset":null},{"stem":"환경 인형극이 2시 35분 5초에 시작해서 6시 10분 55초에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 35분 50초","correct":true},{"t":"4시간 25분 50초","mis":"M3-1-u5-X17"},{"t":"4시간 35분 50초","mis":"M3-1-u5-X16"},{"t":"3시간 75분 50초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","6시 10분 55초 − 2시 35분 5초 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 35분 50초 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#7','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',3,'mc','auto','1시 15분부터 4시 15분까지는 몇 시간인가요?',ARRAY['M3-1-u5-X18','M3-1-u5-X15']::text[],true,'{"seq":7,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"1시 15분부터 4시 15분까지는 몇 시간인가요?","options":[{"t":"3시간","correct":true},{"t":"4시간","mis":"M3-1-u5-X18"},{"t":"3시간 15분","mis":"M3-1-u5-X15"},{"t":"5시간","mis":"M3-1-u5-X15"}],"explanation":["분이 같으니 시끼리 빼요.","4 − 1 = 3.","3시간이에요."],"variant_rule":{"alt":[{"stem":"3시 25분부터 10시 25분까지는 몇 시간인가요?","options":[{"t":"7시간","correct":true},{"t":"8시간","mis":"M3-1-u5-X18"},{"t":"7시간 25분","mis":"M3-1-u5-X15"},{"t":"13시간","mis":"M3-1-u5-X15"}],"explanation":["분이 같으니 시끼리 빼요.","10 − 3 = 7.","7시간이에요."],"asset":null},{"stem":"2시 20분부터 10시 20분까지는 몇 시간인가요?","options":[{"t":"8시간","correct":true},{"t":"9시간","mis":"M3-1-u5-X18"},{"t":"8시간 20분","mis":"M3-1-u5-X15"},{"t":"12시간","mis":"M3-1-u5-X15"}],"explanation":["분이 같으니 시끼리 빼요.","10 − 2 = 8.","8시간이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#8','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',4,'essay','teacher','9시간 20분 30초 − 7시간 10분 40초를 계산하는 방법을 쓰고, 받아내림을 어떻게 했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C8","difficulty":4,"kind":"essay","stem":"9시간 20분 30초 − 7시간 10분 40초를 계산하는 방법을 쓰고, 받아내림을 어떻게 했는지 설명해 보세요.","answer_guide":{"answer":"예: 초끼리 30 − 40은 뺄 수 없으므로 20분에서 1분(60초)을 빌려 와 90 − 40 = 50초이다. 분은 1 줄어 19 − 10 = 9분, 시간은 9 − 7 = 2시간이다. 답은 2시간 9분 50초이다.","scoring_points":["초가 모자라 1분(60초)을 빌려 왔는가","빌려준 분을 1 줄였는가","2시간 9분 50초를 구했는가"]},"explanation":["초: 30 + 60 − 40 = 50.","분: 19 − 10 = 9.","2시간 9분 50초."],"asset":{"type":"expr_grid","rows":[["","9시간","20분","30초"],["−","7시간","10분","40초"],["",null,null,null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#9','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',4,'essay','teacher','태오는 「1시부터 4시까지는 4시간이야.」라고 했어요. 태오의 말이 맞는지 판단하고, 걸린 시간을 바르게 구하는 방법을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C8","difficulty":4,"kind":"essay","stem":"태오는 「1시부터 4시까지는 4시간이야.」라고 했어요. 태오의 말이 맞는지 판단하고, 걸린 시간을 바르게 구하는 방법을 써 보세요.","answer_guide":{"answer":"예: 틀렸다. 걸린 시간은 끝난 시각에서 시작 시각을 빼서 구한다. 4 − 1 = 3이므로 1시부터 4시까지는 3시간이다. 1, 2, 3, 4 숫자 개수를 세면 안 된다.","scoring_points":["틀렸다고 판단했는가","끝난 시각 − 시작 시각으로 구했는가","3시간을 구했는가"]},"explanation":["끝난 시각 − 시작 시각.","4 − 1 = 3.","3시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L08_challenge#10','math',3,1,'u5','L08','g3_1_math_u5_L08_challenge','lesson_challenge','M3-1-u5-C8',4,'sa','auto','영화 가는 1시 55분에 시작해 3시 25분에 끝났고, 영화 나는 1시 25분에 시작해 2시 45분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u5-C8","difficulty":4,"kind":"sa","stem":"영화 가는 1시 55분에 시작해 3시 25분에 끝났고, 영화 나는 1시 25분에 시작해 2시 45분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가: 3시 25분 − 1시 55분 = 1시간 30분.","나: 2시 45분 − 1시 25분 = 1시간 20분.","1시간 30분과 1시간 20분의 차 — 10분."],"variant_rule":{"alt":[{"stem":"영화 가는 1시 55분에 시작해 4시 35분에 끝났고, 영화 나는 1시 25분에 시작해 3시 45분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가: 4시 35분 − 1시 55분 = 2시간 40분.","나: 3시 45분 − 1시 25분 = 2시간 20분.","2시간 40분과 2시간 20분의 차 — 20분."],"asset":null},{"stem":"영화 가는 1시 15분에 시작해 3시 5분에 끝났고, 영화 나는 1시 45분에 시작해 3시 15분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가: 3시 5분 − 1시 15분 = 1시간 50분.","나: 3시 15분 − 1시 45분 = 1시간 30분.","1시간 50분과 1시간 30분의 차 — 20분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#1','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',1,'mc','auto','친구의 발 길이를 나타내기에 알맞은 것은 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":1,"concept":"M3-1-u5-C9","difficulty":1,"kind":"mc","stem":"친구의 발 길이를 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"약 220 mm","correct":true},{"t":"약 220 km","mis":"M3-1-u5-X06"},{"t":"약 220 m","mis":"M3-1-u5-X06"},{"t":"약 220 cm","mis":"M3-1-u5-X06"}],"explanation":["발 길이는 손 한 뼘쯤 되는 작은 길이예요.","약 220 mm = 약 22 cm.","220 cm·220 m·220 km는 너무 길어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 친구의 발 길이를 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"약 210 mm","correct":true},{"t":"약 210 km","mis":"M3-1-u5-X06"},{"t":"약 210 m","mis":"M3-1-u5-X06"},{"t":"약 210 cm","mis":"M3-1-u5-X06"}],"explanation":["발 길이는 손 한 뼘쯤 되는 작은 길이예요.","약 210 mm = 약 21 cm.","210 cm·210 m·210 km는 너무 길어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 친구의 발 길이를 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"약 200 mm","correct":true},{"t":"약 200 km","mis":"M3-1-u5-X06"},{"t":"약 200 m","mis":"M3-1-u5-X06"},{"t":"약 200 cm","mis":"M3-1-u5-X06"}],"explanation":["발 길이는 손 한 뼘쯤 되는 작은 길이예요.","약 200 mm = 약 20 cm.","200 cm·200 m·200 km는 너무 길어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#2','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',1,'mc','auto','태민이 산책을 마친 시각이에요. 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11']::text[],true,'{"seq":2,"concept":"M3-1-u5-C9","difficulty":1,"kind":"mc","stem":"태민이 산책을 마친 시각이에요. 몇 시 몇 분 몇 초인가요?","options":[{"t":"3시 20분 15초","correct":true},{"t":"3시 15분 20초","mis":"M3-1-u5-X10"},{"t":"3시 20분 3초","mis":"M3-1-u5-X11"},{"t":"4시 15분 15초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 3과 4 사이 — 3시.","긴바늘은 20분, 가는 빨간 초바늘은 15초를 가리켜요.","3시 20분 15초예요."],"asset":{"type":"clock3","h":3,"m":20,"s":15},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 태민이 산책을 마친 시각이에요. 몇 시 몇 분 몇 초인가요?","options":[{"t":"10시 53분 22초","correct":true},{"t":"10시 22분 53초","mis":"M3-1-u5-X10"},{"t":"10시 53분 23초","mis":"M3-1-u5-X21"},{"t":"10시 50분 22초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 10과 11 사이 — 10시.","긴바늘은 53분, 가는 빨간 초바늘은 22초를 가리켜요.","10시 53분 22초예요."],"asset":{"type":"clock3","h":10,"m":53,"s":22}},{"stem":"이번에는 다른 문제예요. 태민이 산책을 마친 시각이에요. 몇 시 몇 분 몇 초인가요?","options":[{"t":"2시 6분 54초","correct":true},{"t":"2시 54분 6초","mis":"M3-1-u5-X10"},{"t":"2시 6분 55초","mis":"M3-1-u5-X21"},{"t":"1시 10분 54초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 2와 3 사이 — 2시.","긴바늘은 6분, 가는 빨간 초바늘은 54초를 가리켜요.","2시 6분 54초예요."],"asset":{"type":"clock3","h":2,"m":6,"s":54}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#3','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',1,'mc','auto','수빈은 3시에 나가서 3시 45분에 돌아왔어요. 얼마 동안 산책했나요?',ARRAY['M3-1-u5-X18','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C9","difficulty":1,"kind":"mc","stem":"수빈은 3시에 나가서 3시 45분에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"45분","correct":true},{"t":"1시간 45분","mis":"M3-1-u5-X18"},{"t":"55분","mis":"M3-1-u5-X21"},{"t":"35분","mis":"M3-1-u5-X21"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 45분 − 3시 — 같은 단위끼리, 모자라면 빌려 와요.","45분 동안 했어요."],"variant_rule":{"alt":[{"stem":"수빈은 2시 5분에 나가서 3시 30분에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"1시간 25분","correct":true},{"t":"2시간 25분","mis":"M3-1-u5-X18"},{"t":"1시간 35분","mis":"M3-1-u5-X21"},{"t":"1시간 15분","mis":"M3-1-u5-X21"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 30분 − 2시 5분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 25분 동안 했어요."],"asset":null},{"stem":"수빈은 2시 15분에 나가서 5시 45분에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"3시간 30분","correct":true},{"t":"4시간 30분","mis":"M3-1-u5-X18"},{"t":"3시간 40분","mis":"M3-1-u5-X21"},{"t":"3시간 20분","mis":"M3-1-u5-X21"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 45분 − 2시 15분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 30분 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#4','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',1,'mc','auto','발 길이가 190 mm인 친구는 누구인가요?',ARRAY['M3-1-u5-X20']::text[],true,'{"seq":4,"concept":"M3-1-u5-C9","difficulty":1,"kind":"mc","stem":"발 길이가 190 mm인 친구는 누구인가요?","options":[{"t":"지아","correct":true},{"t":"태민","mis":"M3-1-u5-X20"},{"t":"현우","mis":"M3-1-u5-X20"},{"t":"수빈","mis":"M3-1-u5-X20"}],"explanation":["표의 발 길이 칸을 봐요.","태민 195 mm, 지아 190 mm, 현우 235 mm, 수빈 225 mm.","190 mm인 친구는 지아예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","195 mm","45분"],["지아","190 mm","15분"],["현우","235 mm","20분"],["수빈","225 mm","40분"]]},"variant_rule":{"alt":[{"stem":"발 길이가 240 mm인 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"태민","mis":"M3-1-u5-X20"},{"t":"지아","mis":"M3-1-u5-X20"},{"t":"수빈","mis":"M3-1-u5-X20"}],"explanation":["표의 발 길이 칸을 봐요.","태민 200 mm, 지아 220 mm, 현우 240 mm, 수빈 235 mm.","240 mm인 친구는 현우예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","200 mm","50분"],["지아","220 mm","25분"],["현우","240 mm","20분"],["수빈","235 mm","40분"]]}},{"stem":"발 길이가 230 mm인 친구는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"하랑","mis":"M3-1-u5-X20"},{"t":"서윤","mis":"M3-1-u5-X20"},{"t":"도윤","mis":"M3-1-u5-X20"}],"explanation":["표의 발 길이 칸을 봐요.","하랑 205 mm, 서윤 220 mm, 도윤 240 mm, 지유 230 mm.","230 mm인 친구는 지유예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["하랑","205 mm","50분"],["서윤","220 mm","30분"],["도윤","240 mm","15분"],["지유","230 mm","55분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#5','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',2,'mc','auto','태민은 2시 30분에 나가서 3시 20분 15초에 돌아왔어요. 얼마 동안 산책했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":5,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"태민은 2시 30분에 나가서 3시 20분 15초에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"50분 15초","correct":true},{"t":"1시간 10분 15초","mis":"M3-1-u5-X17"},{"t":"1시간 50분 15초","mis":"M3-1-u5-X16"},{"t":"90분 15초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 20분 15초 − 2시 30분 — 같은 단위끼리, 모자라면 빌려 와요.","50분 15초 동안 했어요."],"variant_rule":{"alt":[{"stem":"태민은 1시 55분 10초에 나가서 3시 15분 45초에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"1시간 20분 35초","correct":true},{"t":"2시간 40분 35초","mis":"M3-1-u5-X17"},{"t":"2시간 20분 35초","mis":"M3-1-u5-X16"},{"t":"1시간 60분 35초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 15분 45초 − 1시 55분 10초 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 20분 35초 동안 했어요."],"asset":null},{"stem":"태민은 2시 45분 40초에 나가서 5시 20분 55초에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"2시간 35분 15초","correct":true},{"t":"3시간 25분 15초","mis":"M3-1-u5-X17"},{"t":"3시간 35분 15초","mis":"M3-1-u5-X16"},{"t":"2시간 75분 15초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 20분 55초 − 2시 45분 40초 — 같은 단위끼리, 모자라면 빌려 와요.","2시간 35분 15초 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#6','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',2,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":6,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"은우","correct":true},{"t":"하린","mis":"M3-1-u5-X19"},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 220 mm보다 긴 친구: 은우, 하린.","단서 ② 45분보다 오래 산책한 친구: 은우, 태오.","두 단서를 모두 만족하는 친구는 은우예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","230 mm","55분"],["하린","240 mm","35분"],["태오","205 mm","50분"],["민준","215 mm","25분"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"민준","correct":true},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"하린","mis":"M3-1-u5-X19"},{"t":"은우","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 태오, 민준.","단서 ② 30분보다 오래 산책한 친구: 하린, 민준.","두 단서를 모두 만족하는 친구는 민준이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","220 mm","20분"],["하린","215 mm","45분"],["태오","240 mm","25분"],["민준","230 mm","50분"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 205 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"은우","correct":true},{"t":"하린","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X19"},{"t":"태오","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 205 mm보다 긴 친구: 은우, 하린.","단서 ② 45분보다 오래 산책한 친구: 은우, 민준.","두 단서를 모두 만족하는 친구는 은우예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","230 mm","50분"],["하린","235 mm","20분"],["태오","195 mm","25분"],["민준","190 mm","55분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#7','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',2,'ox','auto','단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 은우는 두 단서를 모두 만족해요.',ARRAY['M3-1-u5-X19']::text[],true,'{"seq":7,"concept":"M3-1-u5-C9","difficulty":2,"kind":"ox","stem":"단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 은우는 두 단서를 모두 만족해요.","answer":"X","reason_options":[{"t":"발 길이는 맞지만 산책 시간이 15분이라 단서 ②에 맞지 않아서","correct":true},{"t":"단서 하나만 맞아도 되어서","mis":"M3-1-u5-X19"}],"mis":"M3-1-u5-X19","explanation":["은우의 발 길이 240 mm — 단서 ①은 맞아요.","산책 시간 15분 — 30분보다 짧아 단서 ②는 틀려요.","두 단서를 모두 만족하지 않아요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","240 mm","15분"],["하린","195 mm","20분"],["태오","205 mm","45분"],["민준","230 mm","55분"]]},"variant_rule":{"alt":[{"stem":"단서 ① 발 길이가 215 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 하린은 두 단서를 모두 만족해요.","answer":"X","reason_options":[{"t":"발 길이는 맞지만 산책 시간이 40분이라 단서 ②에 맞지 않아서","correct":true},{"t":"단서 하나만 맞아도 되어서","mis":"M3-1-u5-X19"}],"explanation":["하린의 발 길이 230 mm — 단서 ①은 맞아요.","산책 시간 40분 — 45분보다 짧아 단서 ②는 틀려요.","두 단서를 모두 만족하지 않아요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","190 mm","50분"],["하린","230 mm","40분"],["태오","220 mm","55분"],["민준","195 mm","15분"]]}},{"stem":"단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 민준은 두 단서를 모두 만족해요.","answer":"X","reason_options":[{"t":"발 길이는 맞지만 산책 시간이 20분이라 단서 ②에 맞지 않아서","correct":true},{"t":"단서 하나만 맞아도 되어서","mis":"M3-1-u5-X19"}],"explanation":["민준의 발 길이 230 mm — 단서 ①은 맞아요.","산책 시간 20분 — 35분보다 짧아 단서 ②는 틀려요.","두 단서를 모두 만족하지 않아요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","235 mm","45분"],["하린","190 mm","40분"],["태오","200 mm","25분"],["민준","230 mm","20분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#8','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',2,'error','auto','단위나 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X20']::text[],true,'{"seq":8,"concept":"M3-1-u5-C9","difficulty":2,"kind":"error","stem":"단위나 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「내 발 길이는 약 235 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"서윤 — 「내 발 길이는 약 205 mm야」","mis":"M3-1-u5-X20"},{"t":"도윤 — 「3시 5분에 나가 3시 20분에 와서 15분 걸렸어」","mis":"M3-1-u5-X20"}],"explanation":["발 길이는 mm·cm로 나타내요.","도윤의 걸린 시간 3시 20분 − 3시 5분 = 15분 — 맞아요.","하랑은 km를 잘못 썼어요 — 약 235 mm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 단위나 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「내 발 길이는 약 220 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"도윤 — 「내 발 길이는 약 190 mm야」","mis":"M3-1-u5-X20"},{"t":"지유 — 「1시 35분에 나가 2시 20분에 와서 45분 걸렸어」","mis":"M3-1-u5-X20"}],"explanation":["발 길이는 mm·cm로 나타내요.","지유의 걸린 시간 2시 20분 − 1시 35분 = 45분 — 맞아요.","서윤은 km를 잘못 썼어요 — 약 220 mm예요."],"asset":null},{"stem":"이번에는 다른 문제예요. 단위나 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「내 발 길이는 약 200 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"민준 — 「내 발 길이는 약 240 mm야」","mis":"M3-1-u5-X20"},{"t":"은우 — 「3시 10분에 나가 3시 30분에 와서 20분 걸렸어」","mis":"M3-1-u5-X20"}],"explanation":["발 길이는 mm·cm로 나타내요.","은우의 걸린 시간 3시 30분 − 3시 10분 = 20분 — 맞아요.","태오는 km를 잘못 썼어요 — 약 200 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#9','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',2,'mc','auto','발 길이가 20 cm 5 mm인 친구는 누구인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X04']::text[],true,'{"seq":9,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"발 길이가 20 cm 5 mm인 친구는 누구인가요?","options":[{"t":"민준","correct":true},{"t":"은우","mis":"M3-1-u5-X01"},{"t":"하린","mis":"M3-1-u5-X04"},{"t":"태오","mis":"M3-1-u5-X01"}],"explanation":["표는 mm로 적혀 있어요 — 20 cm 5 mm를 mm로 바꿔요.","20 cm 5 mm = 205 mm예요.","205 mm인 친구는 민준이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","240 mm","25분"],["하린","220 mm","20분"],["태오","235 mm","40분"],["민준","205 mm","55분"]]},"variant_rule":{"alt":[{"stem":"발 길이가 22 cm 5 mm인 친구는 누구인가요?","options":[{"t":"하랑","correct":true},{"t":"서윤","mis":"M3-1-u5-X01"},{"t":"도윤","mis":"M3-1-u5-X04"},{"t":"지유","mis":"M3-1-u5-X01"}],"explanation":["표는 mm로 적혀 있어요 — 22 cm 5 mm를 mm로 바꿔요.","22 cm 5 mm = 225 mm예요.","225 mm인 친구는 하랑이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["하랑","225 mm","45분"],["서윤","195 mm","30분"],["도윤","215 mm","20분"],["지유","190 mm","50분"]]}},{"stem":"발 길이가 21 cm인 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"은우","mis":"M3-1-u5-X04"},{"t":"태오","mis":"M3-1-u5-X01"},{"t":"민준","mis":"M3-1-u5-X04"}],"explanation":["표는 mm로 적혀 있어요 — 21 cm를 mm로 바꿔요.","21 cm = 210 mm예요.","210 mm인 친구는 하린이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","190 mm","55분"],["하린","210 mm","15분"],["태오","240 mm","20분"],["민준","230 mm","50분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_basic#10','math',3,1,'u5','L09','g3_1_math_u5_L09_basic','lesson_basic','M3-1-u5-C9',3,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 215 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":10,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 215 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"서윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 215 mm보다 긴 친구: 도윤, 지유.","단서 ② 45분보다 오래 산책한 친구: 하랑(1시간 11분 45초), 도윤(1시간 3분 30초).","두 단서를 모두 만족하는 친구는 도윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","205 mm","2시 35분","3시 46분 45초"],["서윤","195 mm","1시 50분","2시 34분 20초"],["도윤","220 mm","2시 20분","3시 23분 30초"],["지유","240 mm","2시 15분","2시 53분"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 하랑, 서윤.","단서 ② 40분보다 오래 산책한 친구: 서윤(50분 15초), 도윤(1시간 6분 45초).","두 단서를 모두 만족하는 친구는 서윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","235 mm","2시 50분","3시 24분 20초"],["서윤","230 mm","2시 35분","3시 25분 15초"],["도윤","190 mm","3시 15분","4시 21분 45초"],["지유","205 mm","2시 40분","3시 6분 15초"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 230 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"서윤","mis":"M3-1-u5-X19"},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 230 mm보다 긴 친구: 서윤, 지유.","단서 ② 35분보다 오래 산책한 친구: 하랑(49분 20초), 지유(1시간 13분 30초).","두 단서를 모두 만족하는 친구는 지유예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","215 mm","4시 30분","5시 19분 20초"],["서윤","240 mm","1시 15분","1시 32분"],["도윤","190 mm","3시 40분","4시 12분 20초"],["지유","235 mm","4시 10분","5시 23분 30초"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
