INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#2','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',2,'mc','auto','지아는 1시 50분에 나가서 2시 30분 20초에 돌아왔어요. 얼마 동안 산책했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":2,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"지아는 1시 50분에 나가서 2시 30분 20초에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"40분 20초","correct":true},{"t":"1시간 20분 20초","mis":"M3-1-u5-X17"},{"t":"1시간 40분 20초","mis":"M3-1-u5-X16"},{"t":"80분 20초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","2시 30분 20초 − 1시 50분 — 같은 단위끼리, 모자라면 빌려 와요.","40분 20초 동안 했어요."],"variant_rule":{"alt":[{"stem":"지아는 1시 40분 20초에 나가서 3시 25분 45초에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"1시간 45분 25초","correct":true},{"t":"2시간 15분 25초","mis":"M3-1-u5-X17"},{"t":"2시간 45분 25초","mis":"M3-1-u5-X16"},{"t":"1시간 85분 25초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 25분 45초 − 1시 40분 20초 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 45분 25초 동안 했어요."],"asset":null},{"stem":"지아는 1시 50분 15초에 나가서 5시 10분 55초에 돌아왔어요. 얼마 동안 산책했나요?","options":[{"t":"3시간 20분 40초","correct":true},{"t":"4시간 40분 40초","mis":"M3-1-u5-X17"},{"t":"4시간 20분 40초","mis":"M3-1-u5-X16"},{"t":"3시간 60분 40초","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 10분 55초 − 1시 50분 15초 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 20분 40초 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#3','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',3,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":3,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"태오","correct":true},{"t":"은우","mis":"M3-1-u5-X19"},{"t":"하린","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 220 mm보다 긴 친구: 은우, 태오.","단서 ② 30분보다 오래 산책한 친구: 하린(44분 20초), 태오(40분).","두 단서를 모두 만족하는 친구는 태오예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["은우","230 mm","2시 35분","2시 52분"],["하린","195 mm","2시 50분","3시 34분 20초"],["태오","240 mm","3시 15분","3시 55분"],["민준","190 mm","3시 30분","3시 50분 30초"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"민준","correct":true},{"t":"은우","mis":"M3-1-u5-X19"},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"하린","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 은우, 민준.","단서 ② 30분보다 오래 산책한 친구: 태오(1시간 19분 30초), 민준(50분 20초).","두 단서를 모두 만족하는 친구는 민준이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["은우","215 mm","1시 45분","2시 6분 15초"],["하린","195 mm","3시 15분","3시 33분 30초"],["태오","205 mm","2시 55분","4시 14분 30초"],["민준","220 mm","1시 50분","2시 40분 20초"]]}},{"stem":"이번에는 다른 문제예요. 야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"서윤","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 220 mm보다 긴 친구: 하랑, 지유.","단서 ② 30분보다 오래 산책한 친구: 서윤(59분 45초), 지유(1시간 13분 20초).","두 단서를 모두 만족하는 친구는 지유예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","235 mm","2시 10분","2시 33분"],["서윤","195 mm","4시 15분","5시 14분 45초"],["도윤","200 mm","4시 10분","4시 34분"],["지유","240 mm","1시 55분","3시 8분 20초"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#4','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',3,'mc','auto','현우는 40분 동안 산책하고 2시 30분에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X17','M3-1-u5-X16']::text[],true,'{"seq":4,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"현우는 40분 동안 산책하고 2시 30분에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분인가요?","options":[{"t":"1시 50분","correct":true},{"t":"3시 10분","mis":"M3-1-u5-X20"},{"t":"2시 10분","mis":"M3-1-u5-X17"},{"t":"2시 50분","mis":"M3-1-u5-X16"}],"explanation":["나간 시각 = 돌아온 시각 − 산책한 시간이에요.","2시 30분 − 40분 — 분이 모자라면 1시간(60분)을 빌려 와요.","나간 시각은 1시 50분이에요."],"variant_rule":{"alt":[{"stem":"지유는 2시간 50분 동안 산책하고 9시 30분에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분인가요?","options":[{"t":"6시 40분","correct":true},{"t":"12시 20분","mis":"M3-1-u5-X20"},{"t":"7시 20분","mis":"M3-1-u5-X17"},{"t":"7시 40분","mis":"M3-1-u5-X16"}],"explanation":["나간 시각 = 돌아온 시각 − 산책한 시간이에요.","9시 30분 − 2시간 50분 — 분이 모자라면 1시간(60분)을 빌려 와요.","나간 시각은 6시 40분이에요."],"asset":null},{"stem":"은우는 1시간 50분 동안 산책하고 4시 35분에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 45분","correct":true},{"t":"6시 25분","mis":"M3-1-u5-X20"},{"t":"3시 15분","mis":"M3-1-u5-X17"},{"t":"3시 45분","mis":"M3-1-u5-X16"}],"explanation":["나간 시각 = 돌아온 시각 − 산책한 시간이에요.","4시 35분 − 1시간 50분 — 분이 모자라면 1시간(60분)을 빌려 와요.","나간 시각은 2시 45분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#5','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',3,'error','auto','단위나 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X20']::text[],true,'{"seq":5,"concept":"M3-1-u5-C9","difficulty":3,"kind":"error","stem":"단위나 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「내 발 길이는 약 195 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"은우 — 「내 발 길이는 약 235 mm야」","mis":"M3-1-u5-X20"},{"t":"하린 — 「1시 30분에 나가 2시 5분에 와서 35분 걸렸어」","mis":"M3-1-u5-X20"}],"explanation":["발 길이는 mm·cm로 나타내요.","하린의 걸린 시간 2시 5분 − 1시 30분 = 35분 — 맞아요.","민준은 km를 잘못 썼어요 — 약 195 mm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 단위나 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「내 발 길이는 약 195 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"서윤 — 「내 발 길이는 약 190 mm야」","mis":"M3-1-u5-X20"},{"t":"도윤 — 「3시 25분에 나가 4시에 와서 35분 걸렸어」","mis":"M3-1-u5-X20"}],"explanation":["발 길이는 mm·cm로 나타내요.","도윤의 걸린 시간 4시 − 3시 25분 = 35분 — 맞아요.","하랑은 km를 잘못 썼어요 — 약 195 mm예요."],"asset":null},{"stem":"이번에는 다른 문제예요. 단위나 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「내 발 길이는 약 195 km야」","correct":true,"mis_target":"M3-1-u5-X06"},{"t":"현우 — 「내 발 길이는 약 225 mm야」","mis":"M3-1-u5-X20"},{"t":"수빈 — 「1시 45분에 나가 2시 30분에 와서 45분 걸렸어」","mis":"M3-1-u5-X20"}],"explanation":["발 길이는 mm·cm로 나타내요.","수빈의 걸린 시간 2시 30분 − 1시 45분 = 45분 — 맞아요.","지아는 km를 잘못 썼어요 — 약 195 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#6','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',3,'mc','auto','발 길이가 19 cm인 친구는 누구인가요?',ARRAY['M3-1-u5-X04','M3-1-u5-X01']::text[],true,'{"seq":6,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"발 길이가 19 cm인 친구는 누구인가요?","options":[{"t":"태오","correct":true},{"t":"은우","mis":"M3-1-u5-X04"},{"t":"하린","mis":"M3-1-u5-X01"},{"t":"민준","mis":"M3-1-u5-X01"}],"explanation":["표는 mm로 적혀 있어요 — 19 cm를 mm로 바꿔요.","19 cm = 190 mm예요.","190 mm인 친구는 태오예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","210 mm","20분"],["하린","240 mm","40분"],["태오","190 mm","45분"],["민준","235 mm","15분"]]},"variant_rule":{"alt":[{"stem":"발 길이가 22 cm인 친구는 누구인가요?","options":[{"t":"수빈","correct":true},{"t":"태민","mis":"M3-1-u5-X01"},{"t":"지아","mis":"M3-1-u5-X04"},{"t":"현우","mis":"M3-1-u5-X01"}],"explanation":["표는 mm로 적혀 있어요 — 22 cm를 mm로 바꿔요.","22 cm = 220 mm예요.","220 mm인 친구는 수빈이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","210 mm","25분"],["지아","225 mm","45분"],["현우","200 mm","55분"],["수빈","220 mm","30분"]]}},{"stem":"이번에는 다른 문제예요. 발 길이가 19 cm인 친구는 누구인가요?","options":[{"t":"은우","correct":true},{"t":"하린","mis":"M3-1-u5-X01"},{"t":"태오","mis":"M3-1-u5-X01"},{"t":"민준","mis":"M3-1-u5-X04"}],"explanation":["표는 mm로 적혀 있어요 — 19 cm를 mm로 바꿔요.","19 cm = 190 mm예요.","190 mm인 친구는 은우예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","190 mm","35분"],["하린","225 mm","25분"],["태오","230 mm","55분"],["민준","205 mm","50분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#7','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',3,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 50분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":7,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 50분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"도윤","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"하랑","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 서윤, 도윤.","단서 ② 50분보다 오래 산책한 친구: 서윤(1시간), 지유(1시간 11분).","두 단서를 모두 만족하는 친구는 서윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","190 mm","3시 25분","4시 9분 15초"],["서윤","235 mm","4시 25분","5시 25분"],["도윤","240 mm","1시 50분","2시 15분 20초"],["지유","210 mm","3시 30분","4시 41분"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"은우","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 하린, 태오.","단서 ② 30분보다 오래 산책한 친구: 은우(47분 30초), 하린(33분 20초).","두 단서를 모두 만족하는 친구는 하린이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["은우","195 mm","2시 25분","3시 12분 30초"],["하린","240 mm","4시 35분","5시 8분 20초"],["태오","235 mm","1시 55분","2시 10분 20초"],["민준","200 mm","1시 55분","2시 12분 30초"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 50분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"수빈","correct":true},{"t":"지아","mis":"M3-1-u5-X19"},{"t":"태민","mis":"M3-1-u5-X19"},{"t":"현우","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 지아, 수빈.","단서 ② 50분보다 오래 산책한 친구: 태민(52분 30초), 수빈(59분 20초).","두 단서를 모두 만족하는 친구는 수빈이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["태민","195 mm","3시 50분","4시 42분 30초"],["지아","230 mm","1시 25분","2시 5분 15초"],["현우","205 mm","4시 15분","4시 50분 15초"],["수빈","235 mm","2시 20분","3시 19분 20초"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#8','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',4,'essay','teacher','네 친구 중 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 약 220 mm, 단서 ② 산책을 50분보다 오래 했어요. 태민이는 발 길이 220 mm이고 2시 30분에 나가 3시 20분 15초에 돌아왔어요. 태민이가 정리한 친구인지 단서를 하나씩 확인해 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u5-C9","difficulty":4,"kind":"essay","stem":"네 친구 중 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 약 220 mm, 단서 ② 산책을 50분보다 오래 했어요. 태민이는 발 길이 220 mm이고 2시 30분에 나가 3시 20분 15초에 돌아왔어요. 태민이가 정리한 친구인지 단서를 하나씩 확인해 설명해 보세요.","answer_guide":{"answer":"예: 단서 ① 태민이의 발 길이는 220 mm로 맞다. 단서 ② 3시 20분 15초 − 2시 30분은 분이 모자라 1시간(60분)을 빌려 오면 80 − 30 = 50분, 초는 15초이므로 50분 15초이다. 50분보다 오래 했으므로 맞다. 두 단서를 모두 만족하므로 태민이가 정리한 친구이다.","scoring_points":["단서 ①을 확인했는가","산책 시간 50분 15초를 받아내림으로 구했는가","두 단서를 모두 확인해 결론을 냈는가"]},"explanation":["발 220 mm — 단서 ① 맞음.","3시 20분 15초 − 2시 30분 = 50분 15초.","두 단서 모두 — 태민."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#9','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',4,'essay','teacher','길이 단서 하나와 시간 단서 하나를 넣어 「누구일까요」 문제를 만들어 보세요. 단서에 알맞은 단위를 쓰고, 답이 한 명으로 정해지는지 확인해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u5-C9","difficulty":4,"kind":"essay","stem":"길이 단서 하나와 시간 단서 하나를 넣어 「누구일까요」 문제를 만들어 보세요. 단서에 알맞은 단위를 쓰고, 답이 한 명으로 정해지는지 확인해 보세요.","answer_guide":{"answer":"예: 「발 길이가 215 mm보다 길고, 산책을 40분보다 오래 한 친구는?」 — 표에서 두 단서를 모두 만족하는 친구가 한 명뿐인지 확인한다. 발 길이는 mm, 산책 시간은 분으로 나타낸다.","scoring_points":["길이 단서에 알맞은 단위(mm·cm)를 썼는가","시간 단서를 썼는가","답이 한 명으로 정해지는지 확인했는가"]},"explanation":["길이 단서는 mm·cm.","시간 단서는 분·초.","두 단서를 모두 만족하는 친구가 한 명인지 확인."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_L09_challenge#10','math',3,1,'u5','L09','g3_1_math_u5_L09_challenge','lesson_challenge','M3-1-u5-C9',4,'mc','auto','태오는 45분 30초 동안 산책하고 3시 20분 10초에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X17','M3-1-u5-X16']::text[],true,'{"seq":10,"concept":"M3-1-u5-C9","difficulty":4,"kind":"mc","stem":"태오는 45분 30초 동안 산책하고 3시 20분 10초에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"2시 34분 40초","correct":true},{"t":"4시 5분 40초","mis":"M3-1-u5-X20"},{"t":"3시 25분 20초","mis":"M3-1-u5-X17"},{"t":"3시 35분 40초","mis":"M3-1-u5-X16"}],"explanation":["나간 시각 = 돌아온 시각 − 산책한 시간이에요.","3시 20분 10초 − 45분 30초 — 분이 모자라면 1시간(60분)을 빌려 와요.","나간 시각은 2시 34분 40초예요."],"variant_rule":{"alt":[{"stem":"수빈은 25분 55초 동안 산책하고 8시 25분 30초에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"7시 59분 35초","correct":true},{"t":"8시 51분 25초","mis":"M3-1-u5-X20"},{"t":"8시 0분 25초","mis":"M3-1-u5-X17"},{"t":"8시 60분 35초","mis":"M3-1-u5-X16"}],"explanation":["나간 시각 = 돌아온 시각 − 산책한 시간이에요.","8시 25분 30초 − 25분 55초 — 분이 모자라면 1시간(60분)을 빌려 와요.","나간 시각은 7시 59분 35초예요."],"asset":null},{"stem":"하랑은 2시간 55분 55초 동안 산책하고 7시 25분 5초에 돌아왔어요. 산책하러 나간 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"4시 29분 10초","correct":true},{"t":"10시 21분","mis":"M3-1-u5-X20"},{"t":"5시 30분 50초","mis":"M3-1-u5-X17"},{"t":"5시 30분 10초","mis":"M3-1-u5-X16"}],"explanation":["나간 시각 = 돌아온 시각 − 산책한 시간이에요.","7시 25분 5초 − 2시간 55분 55초 — 분이 모자라면 1시간(60분)을 빌려 와요.","나간 시각은 4시 29분 10초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#1','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C1',1,'sa','auto','잎자루의 길이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u5-C1","difficulty":1,"kind":"sa","stem":"잎자루의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","잎자루 끝은 3 cm에서 작은 눈금 6칸 더 간 곳이에요.","3 cm 6 mm = 36 mm예요."],"asset":{"type":"mmruler","len":36,"label":"잎자루"},"variant_rule":{"alt":[{"stem":"씨앗의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["88"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","씨앗 끝은 8 cm에서 작은 눈금 8칸 더 간 곳이에요.","8 cm 8 mm = 88 mm예요."],"asset":{"type":"mmruler","len":88,"label":"씨앗"}},{"stem":"나뭇잎의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","나뭇잎 끝은 2 cm에서 작은 눈금 8칸 더 간 곳이에요.","2 cm 8 mm = 28 mm예요."],"asset":{"type":"mmruler","len":28,"label":"나뭇잎"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#2','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C2',1,'sa','auto','4 cm 5 mm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u5-C2","difficulty":1,"kind":"sa","stem":"4 cm 5 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["1 cm = 10 mm예요.","4 cm = 40 mm, 여기에 5 mm를 더해요.","4 cm 5 mm = 45 mm예요."],"variant_rule":{"alt":[{"stem":"6 cm 2 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["1 cm = 10 mm예요.","6 cm = 60 mm, 여기에 2 mm를 더해요.","6 cm 2 mm = 62 mm예요."],"asset":null},{"stem":"8 cm 4 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["1 cm = 10 mm예요.","8 cm = 80 mm, 여기에 4 mm를 더해요.","8 cm 4 mm = 84 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#3','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C3',1,'mc','auto','엄지손가락 너비는 약 1 cm예요. 엄지가 8번쯤 들어가는 필통의 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X01','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 8번쯤 들어가는 필통의 길이는 약 얼마인가요?","options":[{"t":"약 8 cm","correct":true},{"t":"약 8 mm","mis":"M3-1-u5-X06"},{"t":"약 80 cm","mis":"M3-1-u5-X01"},{"t":"약 18 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","8번이면 약 8 cm.","어림한 길이라 앞에 「약」을 붙여 약 8 cm라고 해요."],"variant_rule":{"alt":[{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 17번쯤 들어가는 자의 길이는 약 얼마인가요?","options":[{"t":"약 17 cm","correct":true},{"t":"약 17 mm","mis":"M3-1-u5-X06"},{"t":"약 170 cm","mis":"M3-1-u5-X01"},{"t":"약 27 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","17번이면 약 17 cm.","어림한 길이라 앞에 「약」을 붙여 약 17 cm라고 해요."],"asset":null},{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 11번쯤 들어가는 색연필의 길이는 약 얼마인가요?","options":[{"t":"약 11 cm","correct":true},{"t":"약 11 mm","mis":"M3-1-u5-X06"},{"t":"약 110 cm","mis":"M3-1-u5-X01"},{"t":"약 21 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","11번이면 약 11 cm.","어림한 길이라 앞에 「약」을 붙여 약 11 cm라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#4','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C4',1,'mc','auto','4 km 56 m는 몇 m인가요?',ARRAY['M3-1-u5-X03','M3-1-u5-X02']::text[],true,'{"seq":4,"concept":"M3-1-u5-C4","difficulty":1,"kind":"mc","stem":"4 km 56 m는 몇 m인가요?","options":[{"t":"4056 m","correct":true},{"t":"456 m","mis":"M3-1-u5-X03"},{"t":"4560 m","mis":"M3-1-u5-X03"},{"t":"60 m","mis":"M3-1-u5-X02"}],"explanation":["1 km = 1000 m — 4 km = 4000 m.","4000 m + 56 m.","4 km 56 m = 4056 m예요."],"variant_rule":{"alt":[{"stem":"2 km 961 m는 몇 m인가요?","options":[{"t":"2961 m","correct":true},{"t":"1161 m","mis":"M3-1-u5-X01"},{"t":"963 m","mis":"M3-1-u5-X02"},{"t":"3061 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 2 km = 2000 m.","2000 m + 961 m.","2 km 961 m = 2961 m예요."],"asset":null},{"stem":"8 km 458 m는 몇 m인가요?","options":[{"t":"8458 m","correct":true},{"t":"1258 m","mis":"M3-1-u5-X01"},{"t":"466 m","mis":"M3-1-u5-X02"},{"t":"8558 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 8 km = 8000 m.","8000 m + 458 m.","8 km 458 m = 8458 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#5','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C5',1,'mc','auto','우리 동네에서 옆 도시까지의 거리는 약 15 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":5,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"우리 동네에서 옆 도시까지의 거리는 약 15 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","우리 동네에서 옆 도시까지의 거리는 약 15 km가 알맞아요."],"variant_rule":{"alt":[{"stem":"서울에서 제주도까지의 거리는 약 460 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","서울에서 제주도까지의 거리는 약 460 km가 알맞아요."],"asset":null},{"stem":"세계 온실까지의 거리는 약 1500 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","세계 온실까지의 거리는 약 1500 m가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#6','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C6',1,'sa','auto','1분 36초는 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u5-C6","difficulty":1,"kind":"sa","stem":"1분 36초는 몇 초인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 36초 = 60 + 36 = 96초예요."],"variant_rule":{"alt":[{"stem":"1분 38초는 몇 초인가요? 숫자로 쓰세요.","answer":["98"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 38초 = 60 + 38 = 98초예요."],"asset":null},{"stem":"1분 6초는 몇 초인가요? 숫자로 쓰세요.","answer":["66"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 6초 = 60 + 6 = 66초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#7','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C7',1,'mc','auto','8시간 20분 + 35분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":7,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"8시간 20분 + 35분은 얼마인가요?","options":[{"t":"8시간 55분","correct":true},{"t":"8시간 45분","mis":"M3-1-u5-X21"},{"t":"9시간 55분","mis":"M3-1-u5-X21"},{"t":"7시간 55분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 20 + 35 = 55.","8시간 20분 + 35분 = 8시간 55분이에요."],"variant_rule":{"alt":[{"stem":"3시간 10분 + 7시간 5분은 얼마인가요?","options":[{"t":"10시간 15분","correct":true},{"t":"10시간 25분","mis":"M3-1-u5-X21"},{"t":"10시간 5분","mis":"M3-1-u5-X21"},{"t":"11시간 15분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 10 + 5 = 15.","3시간 10분 + 7시간 5분 = 10시간 15분이에요."],"asset":null},{"stem":"1시간 5분 + 5시간 20분은 얼마인가요?","options":[{"t":"6시간 25분","correct":true},{"t":"6시간 35분","mis":"M3-1-u5-X21"},{"t":"6시간 15분","mis":"M3-1-u5-X21"},{"t":"7시간 25분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 5 + 20 = 25.","1시간 5분 + 5시간 20분 = 6시간 25분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#8','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C8',1,'mc','auto','6시간 50분 − 10분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":8,"concept":"M3-1-u5-C8","difficulty":1,"kind":"mc","stem":"6시간 50분 − 10분은 얼마인가요?","options":[{"t":"6시간 40분","correct":true},{"t":"6시간 50분","mis":"M3-1-u5-X21"},{"t":"6시간 30분","mis":"M3-1-u5-X21"},{"t":"7시간 40분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","6시간 50분 − 10분 = 6시간 40분이에요."],"variant_rule":{"alt":[{"stem":"4시간 40분 − 3시간 15분은 얼마인가요?","options":[{"t":"1시간 25분","correct":true},{"t":"1시간 35분","mis":"M3-1-u5-X21"},{"t":"1시간 15분","mis":"M3-1-u5-X21"},{"t":"2시간 25분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","4시간 40분 − 3시간 15분 = 1시간 25분이에요."],"asset":null},{"stem":"8시간 45분 − 40분은 얼마인가요?","options":[{"t":"8시간 5분","correct":true},{"t":"8시간 15분","mis":"M3-1-u5-X21"},{"t":"9시간 5분","mis":"M3-1-u5-X21"},{"t":"7시간 5분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","8시간 45분 − 40분 = 8시간 5분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#9','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C2',2,'mc','auto','31 mm는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X04']::text[],true,'{"seq":9,"concept":"M3-1-u5-C2","difficulty":2,"kind":"mc","stem":"31 mm는 몇 cm 몇 mm인가요?","options":[{"t":"3 cm 1 mm","correct":true},{"t":"1 cm 3 mm","mis":"M3-1-u5-X04"},{"t":"31 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 11 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","31 mm = 30 mm + 1 mm.","31 mm = 3 cm 1 mm예요."],"variant_rule":{"alt":[{"stem":"17 mm는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 7 mm","correct":true},{"t":"7 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"17 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 7 mm","mis":"M3-1-u5-X21"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","17 mm = 10 mm + 7 mm.","17 mm = 1 cm 7 mm예요."],"asset":null},{"stem":"94 mm는 몇 cm 몇 mm인가요?","options":[{"t":"9 cm 4 mm","correct":true},{"t":"4 cm 9 mm","mis":"M3-1-u5-X04"},{"t":"94 cm","mis":"M3-1-u5-X04"},{"t":"8 cm 14 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","94 mm = 90 mm + 4 mm.","94 mm = 9 cm 4 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#10','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C3',2,'mc','auto','잎자루의 길이는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X05','M3-1-u5-X04']::text[],true,'{"seq":10,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"잎자루의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"6 cm 7 mm","correct":true},{"t":"8 cm 7 mm","mis":"M3-1-u5-X05"},{"t":"7 cm 7 mm","mis":"M3-1-u5-X05"},{"t":"7 cm 6 mm","mis":"M3-1-u5-X04"}],"explanation":["잎자루의 왼쪽 끝이 2에 있어요 — 0이 아니에요.","2에서 8 cm 7 mm 눈금까지 큰 눈금 6칸·작은 눈금 7칸.","길이는 6 cm 7 mm = 67 mm예요."],"asset":{"type":"mmruler","len":67,"label":"잎자루","s":2},"variant_rule":{"alt":[{"stem":"씨앗의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 8 mm","correct":true},{"t":"4 cm 8 mm","mis":"M3-1-u5-X05"},{"t":"2 cm 8 mm","mis":"M3-1-u5-X05"},{"t":"8 cm 1 mm","mis":"M3-1-u5-X04"}],"explanation":["씨앗의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 4 cm 8 mm 눈금까지 큰 눈금 1칸·작은 눈금 8칸.","길이는 1 cm 8 mm = 18 mm예요."],"asset":{"type":"mmruler","len":18,"label":"씨앗","s":3}},{"stem":"나뭇잎의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 4 mm","correct":true},{"t":"2 cm 4 mm","mis":"M3-1-u5-X05"},{"t":"4 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"1 cm 5 mm","mis":"M3-1-u5-X05"}],"explanation":["나뭇잎의 왼쪽 끝이 1에 있어요 — 0이 아니에요.","1에서 2 cm 4 mm 눈금까지 큰 눈금 1칸·작은 눈금 4칸.","길이는 1 cm 4 mm = 14 mm예요."],"asset":{"type":"mmruler","len":14,"label":"나뭇잎","s":1}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#11','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C4',2,'mc','auto','7674 m는 몇 km 몇 m인가요?',ARRAY['M3-1-u5-X04','M3-1-u5-X03','M3-1-u5-X01']::text[],true,'{"seq":11,"concept":"M3-1-u5-C4","difficulty":2,"kind":"mc","stem":"7674 m는 몇 km 몇 m인가요?","options":[{"t":"7 km 674 m","correct":true},{"t":"76 km 74 m","mis":"M3-1-u5-X04"},{"t":"7 km 67 m","mis":"M3-1-u5-X03"},{"t":"767 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","7674 m = 7000 m + 674 m.","7674 m = 7 km 674 m예요."],"variant_rule":{"alt":[{"stem":"7326 m는 몇 km 몇 m인가요?","options":[{"t":"7 km 326 m","correct":true},{"t":"73 km 26 m","mis":"M3-1-u5-X04"},{"t":"7 km 32 m","mis":"M3-1-u5-X03"},{"t":"732 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","7326 m = 7000 m + 326 m.","7326 m = 7 km 326 m예요."],"asset":null},{"stem":"1236 m는 몇 km 몇 m인가요?","options":[{"t":"1 km 236 m","correct":true},{"t":"12 km 36 m","mis":"M3-1-u5-X04"},{"t":"1 km 23 m","mis":"M3-1-u5-X03"},{"t":"123 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","1236 m = 1000 m + 236 m.","1236 m = 1 km 236 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#12','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C5',2,'mc','auto','지도에서 약 250 m인 거리가 5번 들어가는 곳까지의 거리는 약 얼마인가요?',ARRAY['M3-1-u5-X08']::text[],true,'{"seq":12,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"지도에서 약 250 m인 거리가 5번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 250 m","correct":true},{"t":"약 5 km","mis":"M3-1-u5-X08"},{"t":"약 125 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m = 1250 m.","1250 m = 1 km 250 m — 어림한 거리라 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"지도에서 약 250 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 6 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m + 250 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"asset":null},{"stem":"지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 3 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m + 500 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#13','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C6',2,'mc','auto','시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11']::text[],true,'{"seq":13,"concept":"M3-1-u5-C6","difficulty":2,"kind":"mc","stem":"시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"3시 14분 40초","correct":true},{"t":"3시 40분 14초","mis":"M3-1-u5-X10"},{"t":"3시 14분 8초","mis":"M3-1-u5-X11"},{"t":"2시 15분 40초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 3과 4 사이 — 3시.","긴바늘은 14분, 가는 빨간 초바늘은 40초를 가리켜요.","3시 14분 40초예요."],"asset":{"type":"clock3","h":3,"m":14,"s":40},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"10시 41분 25초","correct":true},{"t":"10시 25분 41초","mis":"M3-1-u5-X10"},{"t":"10시 41분 5초","mis":"M3-1-u5-X11"},{"t":"8시 50분 25초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 10과 11 사이 — 10시.","긴바늘은 41분, 가는 빨간 초바늘은 25초를 가리켜요.","10시 41분 25초예요."],"asset":{"type":"clock3","h":10,"m":41,"s":25}},{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"6시 52분 27초","correct":true},{"t":"6시 27분 52초","mis":"M3-1-u5-X10"},{"t":"6시 52분 28초","mis":"M3-1-u5-X21"},{"t":"10시 30분 27초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 6과 7 사이 — 6시.","긴바늘은 52분, 가는 빨간 초바늘은 27초를 가리켜요.","6시 52분 27초예요."],"asset":{"type":"clock3","h":6,"m":52,"s":27}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#14','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C7',2,'mc','auto','씨앗 심기를 7시 30분에 시작해서 35분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":14,"concept":"M3-1-u5-C7","difficulty":2,"kind":"mc","stem":"씨앗 심기를 7시 30분에 시작해서 35분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 5분","correct":true},{"t":"7시 5분","mis":"M3-1-u5-X14"},{"t":"9시 5분","mis":"M3-1-u5-X14"},{"t":"8시 15분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","7시 30분 + 35분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 8시 5분이에요."],"variant_rule":{"alt":[{"stem":"나무 이름표 달기를 1시 10분에 시작해서 55분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 5분","correct":true},{"t":"1시 5분","mis":"M3-1-u5-X14"},{"t":"3시 5분","mis":"M3-1-u5-X14"},{"t":"2시 15분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","1시 10분 + 55분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 2시 5분이에요."],"asset":null},{"stem":"쓰레기 줍기를 5시 50분에 시작해서 50분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"6시 40분","correct":true},{"t":"5시 40분","mis":"M3-1-u5-X14"},{"t":"7시 40분","mis":"M3-1-u5-X14"},{"t":"6시 50분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","5시 50분 + 50분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 6시 40분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#15','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C8',2,'mc','auto','동굴 체험이 1시 55분에 시작해서 3시 5분에 끝났어요. 얼마 동안 했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":15,"concept":"M3-1-u5-C8","difficulty":2,"kind":"mc","stem":"동굴 체험이 1시 55분에 시작해서 3시 5분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 10분","correct":true},{"t":"2시간 50분","mis":"M3-1-u5-X17"},{"t":"2시간 10분","mis":"M3-1-u5-X16"},{"t":"1시간 50분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 5분 − 1시 55분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 10분 동안 했어요."],"variant_rule":{"alt":[{"stem":"환경 인형극이 1시 20분에 시작해서 3시 5분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 45분","correct":true},{"t":"2시간 15분","mis":"M3-1-u5-X17"},{"t":"2시간 45분","mis":"M3-1-u5-X16"},{"t":"1시간 85분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 5분 − 1시 20분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 45분 동안 했어요."],"asset":null},{"stem":"불 끄기 캠페인 영화가 2시 40분에 시작해서 6시 25분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 45분","correct":true},{"t":"4시간 15분","mis":"M3-1-u5-X17"},{"t":"4시간 45분","mis":"M3-1-u5-X16"},{"t":"3시간 85분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","6시 25분 − 2시 40분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 45분 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#16','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C9',2,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":16,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"민준","mis":"M3-1-u5-X19"},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"은우","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 하린, 민준.","단서 ② 35분보다 오래 산책한 친구: 하린, 태오.","두 단서를 모두 만족하는 친구는 하린이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","195 mm","15분"],["하린","230 mm","45분"],["태오","215 mm","50분"],["민준","235 mm","25분"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"수빈","mis":"M3-1-u5-X19"},{"t":"태민","mis":"M3-1-u5-X19"},{"t":"지아","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 현우, 수빈.","단서 ② 45분보다 오래 산책한 친구: 태민, 현우.","두 단서를 모두 만족하는 친구는 현우예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","220 mm","55분"],["지아","190 mm","25분"],["현우","235 mm","50분"],["수빈","230 mm","20분"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"수빈","correct":true},{"t":"지아","mis":"M3-1-u5-X19"},{"t":"현우","mis":"M3-1-u5-X19"},{"t":"태민","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 220 mm보다 긴 친구: 지아, 수빈.","단서 ② 30분보다 오래 산책한 친구: 현우, 수빈.","두 단서를 모두 만족하는 친구는 수빈이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","190 mm","15분"],["지아","235 mm","25분"],["현우","210 mm","35분"],["수빈","230 mm","45분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#17','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C2',3,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 2 cm 3 mm ○ 32 mm',ARRAY['M3-1-u5-X04','M3-1-u5-X02','M3-1-u5-X20']::text[],true,'{"seq":17,"concept":"M3-1-u5-C2","difficulty":3,"kind":"mc","stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 2 cm 3 mm ○ 32 mm","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","2 cm 3 mm = 23 mm예요.","23 < 32 — <예요."],"variant_rule":{"alt":[{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 9 cm 6 mm ○ 89 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","9 cm 6 mm = 96 mm예요.","96 > 89 — >예요."],"asset":null},{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 4 cm 5 mm ○ 38 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","4 cm 5 mm = 45 mm예요.","45 > 38 — >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#18','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C4',3,'error','auto','km와 m의 관계를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X20']::text[],true,'{"seq":18,"concept":"M3-1-u5-C4","difficulty":3,"kind":"error","stem":"km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「2 km = 200 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"은우 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"민준 — 「2007 m = 2 km 7 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","2 km = 2000 m예요.","태오는 1 km를 100 m로 잘못 알았어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「3 km = 300 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"하은 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"태오 — 「3 km 288 m = 3288 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","3 km = 3000 m예요.","서윤은 1 km를 100 m로 잘못 알았어요."],"asset":null},{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「9 km = 900 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"도윤 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"하랑 — 「9281 m = 9 km 281 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","9 km = 9000 m예요.","하은은 1 km를 100 m로 잘못 알았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#19','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C6',3,'mc','auto','289초는 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X04']::text[],true,'{"seq":19,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"289초는 몇 분 몇 초인가요?","options":[{"t":"4분 49초","correct":true},{"t":"2분 89초","mis":"M3-1-u5-X09"},{"t":"28분 9초","mis":"M3-1-u5-X04"},{"t":"3분 49초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","289 = 60 + 60 + 60 + 60 + 49.","289초 = 4분 49초예요."],"variant_rule":{"alt":[{"stem":"265초는 몇 분 몇 초인가요?","options":[{"t":"4분 25초","correct":true},{"t":"2분 65초","mis":"M3-1-u5-X09"},{"t":"26분 5초","mis":"M3-1-u5-X04"},{"t":"3분 25초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","265 = 60 + 60 + 60 + 60 + 25.","265초 = 4분 25초예요."],"asset":null},{"stem":"234초는 몇 분 몇 초인가요?","options":[{"t":"3분 54초","correct":true},{"t":"2분 34초","mis":"M3-1-u5-X09"},{"t":"23분 4초","mis":"M3-1-u5-X04"},{"t":"2분 54초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","234 = 60 + 60 + 60 + 54.","234초 = 3분 54초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#20','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C7',3,'mc','auto','5시간 50분 40초 + 7시간 55분 55초는 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":20,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"5시간 50분 40초 + 7시간 55분 55초는 얼마인가요?","options":[{"t":"13시간 46분 35초","correct":true},{"t":"12시간 45분 35초","mis":"M3-1-u5-X14"},{"t":"14시간 46분 35초","mis":"M3-1-u5-X14"},{"t":"13시간 46분 45초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 40 + 55 = 95 → 60초를 1분으로 받아올림, 분끼리 106 → 1시간으로 받아올림.","5시간 50분 40초 + 7시간 55분 55초 = 13시간 46분 35초예요."],"variant_rule":{"alt":[{"stem":"7시간 45분 45초 + 35분 25초는 얼마인가요?","options":[{"t":"8시간 21분 10초","correct":true},{"t":"7시간 20분 10초","mis":"M3-1-u5-X14"},{"t":"9시간 21분 10초","mis":"M3-1-u5-X14"},{"t":"8시간 21분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 45 + 25 = 70 → 60초를 1분으로 받아올림, 분끼리 81 → 1시간으로 받아올림.","7시간 45분 45초 + 35분 25초 = 8시간 21분 10초예요."],"asset":null},{"stem":"8시간 25분 30초 + 3시간 55분 35초는 얼마인가요?","options":[{"t":"12시간 21분 5초","correct":true},{"t":"11시간 20분 5초","mis":"M3-1-u5-X14"},{"t":"13시간 21분 5초","mis":"M3-1-u5-X14"},{"t":"12시간 21분 15초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 30 + 35 = 65 → 60초를 1분으로 받아올림, 분끼리 81 → 1시간으로 받아올림.","8시간 25분 30초 + 3시간 55분 35초 = 12시간 21분 5초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#21','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C8',3,'mc','auto','동굴 체험을 55분 동안 하고 9시 35분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X17','M3-1-u5-X16']::text[],true,'{"seq":21,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"동굴 체험을 55분 동안 하고 9시 35분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 40분","correct":true},{"t":"10시 30분","mis":"M3-1-u5-X20"},{"t":"9시 20분","mis":"M3-1-u5-X17"},{"t":"9시 40분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","9시 35분 − 55분 — 모자라면 60을 빌려 와요.","시작한 시각은 8시 40분이에요."],"variant_rule":{"alt":[{"stem":"환경 인형극을 45분 동안 하고 5시 20분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"4시 35분","correct":true},{"t":"6시 5분","mis":"M3-1-u5-X20"},{"t":"5시 25분","mis":"M3-1-u5-X17"},{"t":"5시 35분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","5시 20분 − 45분 — 모자라면 60을 빌려 와요.","시작한 시각은 4시 35분이에요."],"asset":null},{"stem":"숲 해설을 2시간 50분 동안 하고 8시 10분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 20분","correct":true},{"t":"11시","mis":"M3-1-u5-X20"},{"t":"6시 40분","mis":"M3-1-u5-X17"},{"t":"6시 20분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","8시 10분 − 2시간 50분 — 모자라면 60을 빌려 와요.","시작한 시각은 5시 20분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#22','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C9',3,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 230 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":22,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 230 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"서윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 230 mm보다 긴 친구: 도윤, 지유.","단서 ② 40분보다 오래 산책한 친구: 하랑(1시간 5분 30초), 도윤(1시간 6분 30초).","두 단서를 모두 만족하는 친구는 도윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","210 mm","1시 55분","3시 0분 30초"],["서윤","205 mm","2시 20분","2시 57분 15초"],["도윤","240 mm","1시 20분","2시 26분 30초"],["지유","235 mm","2시 5분","2시 27분"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 215 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"은우","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 215 mm보다 긴 친구: 하린, 태오.","단서 ② 45분보다 오래 산책한 친구: 은우(57분 30초), 하린(1시간 6분 15초).","두 단서를 모두 만족하는 친구는 하린이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["은우","210 mm","4시 25분","5시 22분 30초"],["하린","235 mm","1시 15분","2시 21분 15초"],["태오","220 mm","2시 40분","2시 58분 30초"],["민준","200 mm","4시 30분","4시 51분 30초"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X19"},{"t":"서윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 하랑, 지유.","단서 ② 40분보다 오래 산책한 친구: 도윤(52분 45초), 지유(1시간 6분 45초).","두 단서를 모두 만족하는 친구는 지유예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","235 mm","2시 5분","2시 43분 15초"],["서윤","205 mm","4시 20분","4시 50분 15초"],["도윤","210 mm","4시 20분","5시 12분 45초"],["지유","230 mm","3시 25분","4시 31분 45초"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#23','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C8',4,'sa','auto','영화 가는 2시 50분에 시작해 4시 25분에 끝났고, 영화 나는 2시 50분에 시작해 4시 45분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u5-C8","difficulty":4,"kind":"sa","stem":"영화 가는 2시 50분에 시작해 4시 25분에 끝났고, 영화 나는 2시 50분에 시작해 4시 45분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가: 4시 25분 − 2시 50분 = 1시간 35분.","나: 4시 45분 − 2시 50분 = 1시간 55분.","1시간 35분과 1시간 55분의 차 — 20분."],"variant_rule":{"alt":[{"stem":"영화 가는 2시 40분에 시작해 4시 20분에 끝났고, 영화 나는 2시 20분에 시작해 3시 25분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["가: 4시 20분 − 2시 40분 = 1시간 40분.","나: 3시 25분 − 2시 20분 = 1시간 5분.","1시간 40분과 1시간 5분의 차 — 35분."],"asset":null},{"stem":"영화 가는 2시 50분에 시작해 6시 30분에 끝났고, 영화 나는 1시 5분에 시작해 4시 15분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["가: 6시 30분 − 2시 50분 = 3시간 40분.","나: 4시 15분 − 1시 5분 = 3시간 10분.","3시간 40분과 3시간 10분의 차 — 30분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#24','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C7',4,'mc','auto','2시 35분에 숲 해설을 듣기 시작해서 35분 동안 듣고, 바로 이어서 1시간 40분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X14']::text[],true,'{"seq":24,"concept":"M3-1-u5-C7","difficulty":4,"kind":"mc","stem":"2시 35분에 숲 해설을 듣기 시작해서 35분 동안 듣고, 바로 이어서 1시간 40분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"4시 50분","correct":true},{"t":"3시 10분","mis":"M3-1-u5-X19"},{"t":"4시 15분","mis":"M3-1-u5-X19"},{"t":"3시 50분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","2시 35분 + 35분 = 3시 10분.","3시 10분 + 1시간 40분 = 4시 50분이에요."],"variant_rule":{"alt":[{"stem":"6시 40분에 숲 해설을 듣기 시작해서 40분 동안 듣고, 바로 이어서 50분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 10분","correct":true},{"t":"7시 20분","mis":"M3-1-u5-X19"},{"t":"7시 30분","mis":"M3-1-u5-X19"},{"t":"7시 10분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","6시 40분 + 40분 = 7시 20분.","7시 20분 + 50분 = 8시 10분이에요."],"asset":null},{"stem":"8시 15분에 숲 해설을 듣기 시작해서 30분 동안 듣고, 바로 이어서 55분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 40분","correct":true},{"t":"8시 45분","mis":"M3-1-u5-X19"},{"t":"9시 10분","mis":"M3-1-u5-X19"},{"t":"8시 40분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","8시 15분 + 30분 = 8시 45분.","8시 45분 + 55분 = 9시 40분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_a#25','math',3,1,'u5','','g3_1_math_u5_review_a','unit_review','M3-1-u5-C7',4,'essay','teacher','영화가 1시 50분에 시작해 1시간 25분 동안 상영됐어요. 끝난 시각을 구하는 과정을 쓰고, 받아올림을 어디에서 했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u5-C7","difficulty":4,"kind":"essay","stem":"영화가 1시 50분에 시작해 1시간 25분 동안 상영됐어요. 끝난 시각을 구하는 과정을 쓰고, 받아올림을 어디에서 했는지 설명해 보세요.","answer_guide":{"answer":"예: 시작 시각 + 걸린 시간 = 끝난 시각이다. 분끼리 50 + 25 = 75분이고 60분은 1시간이므로 15분을 쓰고 1시간을 받아올린다. 시끼리 1 + 1 + 1 = 3시이다. 끝난 시각은 3시 15분이다.","scoring_points":["시작 시각 + 걸린 시간으로 식을 세웠는가","75분을 1시간 15분으로 받아올렸는가","3시 15분을 구했는가"]},"explanation":["1시 50분 + 1시간 25분.","75분 → 1시간 15분.","3시 15분."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#1','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C1',1,'sa','auto','씨앗의 길이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u5-C1","difficulty":1,"kind":"sa","stem":"씨앗의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","씨앗 끝은 2 cm에서 작은 눈금 5칸 더 간 곳이에요.","2 cm 5 mm = 25 mm예요."],"asset":{"type":"mmruler","len":25,"label":"씨앗"},"variant_rule":{"alt":[{"stem":"나뭇잎의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["97"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","나뭇잎 끝은 9 cm에서 작은 눈금 7칸 더 간 곳이에요.","9 cm 7 mm = 97 mm예요."],"asset":{"type":"mmruler","len":97,"label":"나뭇잎"}},{"stem":"솔방울의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","솔방울 끝은 4 cm에서 작은 눈금 9칸 더 간 곳이에요.","4 cm 9 mm = 49 mm예요."],"asset":{"type":"mmruler","len":49,"label":"솔방울"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#2','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C2',1,'sa','auto','2 cm 8 mm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u5-C2","difficulty":1,"kind":"sa","stem":"2 cm 8 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["1 cm = 10 mm예요.","2 cm = 20 mm, 여기에 8 mm를 더해요.","2 cm 8 mm = 28 mm예요."],"variant_rule":{"alt":[{"stem":"5 cm 7 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["1 cm = 10 mm예요.","5 cm = 50 mm, 여기에 7 mm를 더해요.","5 cm 7 mm = 57 mm예요."],"asset":null},{"stem":"4 cm 7 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["1 cm = 10 mm예요.","4 cm = 40 mm, 여기에 7 mm를 더해요.","4 cm 7 mm = 47 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#3','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C3',1,'mc','auto','엄지손가락 너비는 약 1 cm예요. 엄지가 10번쯤 들어가는 사인펜의 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X01','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 10번쯤 들어가는 사인펜의 길이는 약 얼마인가요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 10 mm","mis":"M3-1-u5-X06"},{"t":"약 100 cm","mis":"M3-1-u5-X01"},{"t":"약 20 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","10번이면 약 10 cm.","어림한 길이라 앞에 「약」을 붙여 약 10 cm라고 해요."],"variant_rule":{"alt":[{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 8번쯤 들어가는 필통의 길이는 약 얼마인가요?","options":[{"t":"약 8 cm","correct":true},{"t":"약 8 mm","mis":"M3-1-u5-X06"},{"t":"약 80 cm","mis":"M3-1-u5-X01"},{"t":"약 18 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","8번이면 약 8 cm.","어림한 길이라 앞에 「약」을 붙여 약 8 cm라고 해요."],"asset":null},{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 4번쯤 들어가는 자의 길이는 약 얼마인가요?","options":[{"t":"약 4 cm","correct":true},{"t":"약 4 mm","mis":"M3-1-u5-X06"},{"t":"약 40 cm","mis":"M3-1-u5-X01"},{"t":"약 14 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","4번이면 약 4 cm.","어림한 길이라 앞에 「약」을 붙여 약 4 cm라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#4','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C4',1,'mc','auto','5 km 910 m는 몇 m인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X02','M3-1-u5-X21']::text[],true,'{"seq":4,"concept":"M3-1-u5-C4","difficulty":1,"kind":"mc","stem":"5 km 910 m는 몇 m인가요?","options":[{"t":"5910 m","correct":true},{"t":"1410 m","mis":"M3-1-u5-X01"},{"t":"915 m","mis":"M3-1-u5-X02"},{"t":"6010 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 5 km = 5000 m.","5000 m + 910 m.","5 km 910 m = 5910 m예요."],"variant_rule":{"alt":[{"stem":"4 km 610 m는 몇 m인가요?","options":[{"t":"4610 m","correct":true},{"t":"1010 m","mis":"M3-1-u5-X01"},{"t":"614 m","mis":"M3-1-u5-X02"},{"t":"4710 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 4 km = 4000 m.","4000 m + 610 m.","4 km 610 m = 4610 m예요."],"asset":null},{"stem":"7 km 978 m는 몇 m인가요?","options":[{"t":"7978 m","correct":true},{"t":"1678 m","mis":"M3-1-u5-X01"},{"t":"985 m","mis":"M3-1-u5-X02"},{"t":"8078 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 7 km = 7000 m.","7000 m + 978 m.","7 km 978 m = 7978 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#5','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C5',1,'mc','auto','서울에서 부산까지의 거리는 약 400 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":5,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"서울에서 부산까지의 거리는 약 400 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","서울에서 부산까지의 거리는 약 400 km가 알맞아요."],"variant_rule":{"alt":[{"stem":"나무의 높이는 약 12 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","나무의 높이는 약 12 m가 알맞아요."],"asset":null},{"stem":"운동장 한 바퀴는 약 200 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","운동장 한 바퀴는 약 200 m가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#6','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C6',1,'sa','auto','1분 5초는 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u5-C6","difficulty":1,"kind":"sa","stem":"1분 5초는 몇 초인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 5초 = 60 + 5 = 65초예요."],"variant_rule":{"alt":[{"stem":"1분 37초는 몇 초인가요? 숫자로 쓰세요.","answer":["97"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 37초 = 60 + 37 = 97초예요."],"asset":null},{"stem":"1분 28초는 몇 초인가요? 숫자로 쓰세요.","answer":["88"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 28초 = 60 + 28 = 88초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#7','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C7',1,'mc','auto','8시간 30분 + 2시간 25분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":7,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"8시간 30분 + 2시간 25분은 얼마인가요?","options":[{"t":"10시간 55분","correct":true},{"t":"10시간 45분","mis":"M3-1-u5-X21"},{"t":"11시간 55분","mis":"M3-1-u5-X21"},{"t":"9시간 55분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 30 + 25 = 55.","8시간 30분 + 2시간 25분 = 10시간 55분이에요."],"variant_rule":{"alt":[{"stem":"8시간 10분 + 5시간 35분은 얼마인가요?","options":[{"t":"13시간 45분","correct":true},{"t":"13시간 55분","mis":"M3-1-u5-X21"},{"t":"13시간 35분","mis":"M3-1-u5-X21"},{"t":"14시간 45분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 10 + 35 = 45.","8시간 10분 + 5시간 35분 = 13시간 45분이에요."],"asset":null},{"stem":"6시간 15분 + 5분은 얼마인가요?","options":[{"t":"6시간 20분","correct":true},{"t":"6시간 30분","mis":"M3-1-u5-X21"},{"t":"6시간 10분","mis":"M3-1-u5-X21"},{"t":"7시간 20분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 15 + 5 = 20.","6시간 15분 + 5분 = 6시간 20분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#8','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C8',1,'mc','auto','7시간 45분 − 15분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":8,"concept":"M3-1-u5-C8","difficulty":1,"kind":"mc","stem":"7시간 45분 − 15분은 얼마인가요?","options":[{"t":"7시간 30분","correct":true},{"t":"7시간 40분","mis":"M3-1-u5-X21"},{"t":"7시간 20분","mis":"M3-1-u5-X21"},{"t":"8시간 30분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","7시간 45분 − 15분 = 7시간 30분이에요."],"variant_rule":{"alt":[{"stem":"1시간 40분 − 35분은 얼마인가요?","options":[{"t":"1시간 5분","correct":true},{"t":"1시간 15분","mis":"M3-1-u5-X21"},{"t":"2시간 5분","mis":"M3-1-u5-X21"},{"t":"5분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","1시간 40분 − 35분 = 1시간 5분이에요."],"asset":null},{"stem":"5시간 30분 − 5분은 얼마인가요?","options":[{"t":"5시간 25분","correct":true},{"t":"5시간 35분","mis":"M3-1-u5-X21"},{"t":"5시간 15분","mis":"M3-1-u5-X21"},{"t":"6시간 25분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","5시간 30분 − 5분 = 5시간 25분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#9','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C2',2,'mc','auto','79 mm는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X04']::text[],true,'{"seq":9,"concept":"M3-1-u5-C2","difficulty":2,"kind":"mc","stem":"79 mm는 몇 cm 몇 mm인가요?","options":[{"t":"7 cm 9 mm","correct":true},{"t":"9 cm 7 mm","mis":"M3-1-u5-X04"},{"t":"79 cm","mis":"M3-1-u5-X04"},{"t":"6 cm 19 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","79 mm = 70 mm + 9 mm.","79 mm = 7 cm 9 mm예요."],"variant_rule":{"alt":[{"stem":"17 mm는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 7 mm","correct":true},{"t":"7 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"17 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 7 mm","mis":"M3-1-u5-X21"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","17 mm = 10 mm + 7 mm.","17 mm = 1 cm 7 mm예요."],"asset":null},{"stem":"12 mm는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 2 mm","correct":true},{"t":"2 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"12 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 2 mm","mis":"M3-1-u5-X21"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","12 mm = 10 mm + 2 mm.","12 mm = 1 cm 2 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#10','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C3',2,'mc','auto','씨앗의 길이는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X05','M3-1-u5-X04']::text[],true,'{"seq":10,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"씨앗의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 6 mm","correct":true},{"t":"4 cm 6 mm","mis":"M3-1-u5-X05"},{"t":"2 cm 6 mm","mis":"M3-1-u5-X05"},{"t":"6 cm 1 mm","mis":"M3-1-u5-X04"}],"explanation":["씨앗의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 4 cm 6 mm 눈금까지 큰 눈금 1칸·작은 눈금 6칸.","길이는 1 cm 6 mm = 16 mm예요."],"asset":{"type":"mmruler","len":16,"label":"씨앗","s":3},"variant_rule":{"alt":[{"stem":"나뭇잎의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"6 cm 6 mm","correct":true},{"t":"8 cm 6 mm","mis":"M3-1-u5-X05"},{"t":"7 cm 6 mm","mis":"M3-1-u5-X05"},{"t":"6 cm 7 mm","mis":"M3-1-u5-X05"}],"explanation":["나뭇잎의 왼쪽 끝이 2에 있어요 — 0이 아니에요.","2에서 8 cm 6 mm 눈금까지 큰 눈금 6칸·작은 눈금 6칸.","길이는 6 cm 6 mm = 66 mm예요."],"asset":{"type":"mmruler","len":66,"label":"나뭇잎","s":2}},{"stem":"솔방울의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"3 cm 1 mm","correct":true},{"t":"6 cm 1 mm","mis":"M3-1-u5-X05"},{"t":"4 cm 1 mm","mis":"M3-1-u5-X05"},{"t":"1 cm 3 mm","mis":"M3-1-u5-X04"}],"explanation":["솔방울의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 6 cm 1 mm 눈금까지 큰 눈금 3칸·작은 눈금 1칸.","길이는 3 cm 1 mm = 31 mm예요."],"asset":{"type":"mmruler","len":31,"label":"솔방울","s":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#11','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C4',2,'mc','auto','3408 m는 몇 km 몇 m인가요?',ARRAY['M3-1-u5-X04','M3-1-u5-X03','M3-1-u5-X01']::text[],true,'{"seq":11,"concept":"M3-1-u5-C4","difficulty":2,"kind":"mc","stem":"3408 m는 몇 km 몇 m인가요?","options":[{"t":"3 km 408 m","correct":true},{"t":"34 km 8 m","mis":"M3-1-u5-X04"},{"t":"3 km 40 m","mis":"M3-1-u5-X03"},{"t":"340 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","3408 m = 3000 m + 408 m.","3408 m = 3 km 408 m예요."],"variant_rule":{"alt":[{"stem":"8960 m는 몇 km 몇 m인가요?","options":[{"t":"8 km 960 m","correct":true},{"t":"89 km 60 m","mis":"M3-1-u5-X04"},{"t":"8 km 96 m","mis":"M3-1-u5-X03"},{"t":"896 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","8960 m = 8000 m + 960 m.","8960 m = 8 km 960 m예요."],"asset":null},{"stem":"2134 m는 몇 km 몇 m인가요?","options":[{"t":"2 km 134 m","correct":true},{"t":"21 km 34 m","mis":"M3-1-u5-X04"},{"t":"2 km 13 m","mis":"M3-1-u5-X03"},{"t":"213 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","2134 m = 2000 m + 134 m.","2134 m = 2 km 134 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#12','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C5',2,'mc','auto','지도에서 약 250 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?',ARRAY['M3-1-u5-X08']::text[],true,'{"seq":12,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"지도에서 약 250 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 6 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m + 250 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"지도에서 약 200 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 200 m","correct":true},{"t":"약 6 km","mis":"M3-1-u5-X08"},{"t":"약 120 m","mis":"M3-1-u5-X08"},{"t":"약 200 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 200 m가 몇 번 들어가는지 세어요.","200 m + 200 m + 200 m + 200 m + 200 m + 200 m = 1200 m.","1200 m = 1 km 200 m — 어림한 거리라 「약」을 붙여요."],"asset":null},{"stem":"지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 3 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m + 500 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#13','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C6',2,'mc','auto','시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11']::text[],true,'{"seq":13,"concept":"M3-1-u5-C6","difficulty":2,"kind":"mc","stem":"시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"3시 1분 45초","correct":true},{"t":"3시 45분 1초","mis":"M3-1-u5-X10"},{"t":"3시 1분 9초","mis":"M3-1-u5-X11"},{"t":"12시 15분 45초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 3과 4 사이 — 3시.","긴바늘은 1분, 가는 빨간 초바늘은 45초를 가리켜요.","3시 1분 45초예요."],"asset":{"type":"clock3","h":3,"m":1,"s":45},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"5시 18분 30초","correct":true},{"t":"5시 30분 18초","mis":"M3-1-u5-X10"},{"t":"5시 18분 6초","mis":"M3-1-u5-X11"},{"t":"3시 25분 30초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 5와 6 사이 — 5시.","긴바늘은 18분, 가는 빨간 초바늘은 30초를 가리켜요.","5시 18분 30초예요."],"asset":{"type":"clock3","h":5,"m":18,"s":30}},{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"1시 49분 35초","correct":true},{"t":"1시 35분 49초","mis":"M3-1-u5-X10"},{"t":"1시 49분 7초","mis":"M3-1-u5-X11"},{"t":"9시 5분 35초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 1과 2 사이 — 1시.","긴바늘은 49분, 가는 빨간 초바늘은 35초를 가리켜요.","1시 49분 35초예요."],"asset":{"type":"clock3","h":1,"m":49,"s":35}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#14','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C7',2,'mc','auto','숲 해설 듣기를 1시 35분에 시작해서 1시간 35분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":14,"concept":"M3-1-u5-C7","difficulty":2,"kind":"mc","stem":"숲 해설 듣기를 1시 35분에 시작해서 1시간 35분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"3시 10분","correct":true},{"t":"2시 10분","mis":"M3-1-u5-X14"},{"t":"4시 10분","mis":"M3-1-u5-X14"},{"t":"3시 20분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","1시 35분 + 1시간 35분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 3시 10분이에요."],"variant_rule":{"alt":[{"stem":"씨앗 심기를 2시 55분에 시작해서 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"3시 25분","correct":true},{"t":"2시 25분","mis":"M3-1-u5-X14"},{"t":"4시 25분","mis":"M3-1-u5-X14"},{"t":"3시 35분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","2시 55분 + 30분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 3시 25분이에요."],"asset":null},{"stem":"나무 이름표 달기를 7시 45분에 시작해서 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 15분","correct":true},{"t":"7시 15분","mis":"M3-1-u5-X14"},{"t":"9시 15분","mis":"M3-1-u5-X14"},{"t":"8시 25분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","7시 45분 + 30분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 8시 15분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#15','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C8',2,'mc','auto','동굴 체험이 1시 55분에 시작해서 5시 35분에 끝났어요. 얼마 동안 했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":15,"concept":"M3-1-u5-C8","difficulty":2,"kind":"mc","stem":"동굴 체험이 1시 55분에 시작해서 5시 35분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 40분","correct":true},{"t":"4시간 20분","mis":"M3-1-u5-X17"},{"t":"4시간 40분","mis":"M3-1-u5-X16"},{"t":"3시간 80분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 35분 − 1시 55분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 40분 동안 했어요."],"variant_rule":{"alt":[{"stem":"환경 인형극이 1시 50분에 시작해서 3시 45분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 55분","correct":true},{"t":"2시간 5분","mis":"M3-1-u5-X17"},{"t":"2시간 55분","mis":"M3-1-u5-X16"},{"t":"1시간 95분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","3시 45분 − 1시 50분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 55분 동안 했어요."],"asset":null},{"stem":"불 끄기 캠페인 영화가 2시 40분에 시작해서 6시 20분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 40분","correct":true},{"t":"4시간 20분","mis":"M3-1-u5-X17"},{"t":"4시간 40분","mis":"M3-1-u5-X16"},{"t":"3시간 80분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","6시 20분 − 2시 40분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 40분 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#16','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C9',2,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":16,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"도윤","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"하랑","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 서윤, 도윤.","단서 ② 35분보다 오래 산책한 친구: 서윤, 지유.","두 단서를 모두 만족하는 친구는 서윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["하랑","210 mm","25분"],["서윤","240 mm","45분"],["도윤","235 mm","15분"],["지유","220 mm","40분"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 215 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X19"},{"t":"은우","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 215 mm보다 긴 친구: 하린, 태오.","단서 ② 45분보다 오래 산책한 친구: 하린, 민준.","두 단서를 모두 만족하는 친구는 하린이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","200 mm","20분"],["하린","220 mm","55분"],["태오","225 mm","35분"],["민준","205 mm","50분"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X19"},{"t":"은우","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 하린, 태오.","단서 ② 45분보다 오래 산책한 친구: 하린, 민준.","두 단서를 모두 만족하는 친구는 하린이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","205 mm","30분"],["하린","240 mm","50분"],["태오","235 mm","20분"],["민준","190 mm","55분"]]}}]}}'::jsonb) ON CONFLIC