INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#17','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C2',3,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 5 cm 2 mm ○ 45 mm',ARRAY['M3-1-u5-X04','M3-1-u5-X02','M3-1-u5-X20']::text[],true,'{"seq":17,"concept":"M3-1-u5-C2","difficulty":3,"kind":"mc","stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 5 cm 2 mm ○ 45 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","5 cm 2 mm = 52 mm예요.","52 > 45 — >예요."],"variant_rule":{"alt":[{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 6 cm 3 mm ○ 72 mm","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","6 cm 3 mm = 63 mm예요.","63 < 72 — <예요."],"asset":null},{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 9 cm 6 mm ○ 86 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","9 cm 6 mm = 96 mm예요.","96 > 86 — >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#18','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C4',3,'error','auto','km와 m의 관계를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X20']::text[],true,'{"seq":18,"concept":"M3-1-u5-C4","difficulty":3,"kind":"error","stem":"km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「9 km = 900 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"태오 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"지유 — 「9 km 98 m = 9098 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","9 km = 9000 m예요.","서윤은 1 km를 100 m로 잘못 알았어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「8 km = 800 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"은우 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"하린 — 「8228 m = 8 km 228 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","8 km = 8000 m예요.","서윤은 1 km를 100 m로 잘못 알았어요."],"asset":null},{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「6 km = 600 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"도윤 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"은우 — 「6 km 889 m = 6889 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","6 km = 6000 m예요.","서윤은 1 km를 100 m로 잘못 알았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#19','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C6',3,'mc','auto','244초는 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X04','M3-1-u5-X03']::text[],true,'{"seq":19,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"244초는 몇 분 몇 초인가요?","options":[{"t":"4분 4초","correct":true},{"t":"2분 44초","mis":"M3-1-u5-X09"},{"t":"24분 4초","mis":"M3-1-u5-X04"},{"t":"4분 40초","mis":"M3-1-u5-X03"}],"explanation":["60초 = 1분 — 60씩 묶어요.","244 = 60 + 60 + 60 + 60 + 4.","244초 = 4분 4초예요."],"variant_rule":{"alt":[{"stem":"149초는 몇 분 몇 초인가요?","options":[{"t":"2분 29초","correct":true},{"t":"1분 49초","mis":"M3-1-u5-X09"},{"t":"14분 9초","mis":"M3-1-u5-X04"},{"t":"1분 29초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","149 = 60 + 60 + 29.","149초 = 2분 29초예요."],"asset":null},{"stem":"176초는 몇 분 몇 초인가요?","options":[{"t":"2분 56초","correct":true},{"t":"1분 76초","mis":"M3-1-u5-X09"},{"t":"17분 6초","mis":"M3-1-u5-X04"},{"t":"1분 56초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","176 = 60 + 60 + 56.","176초 = 2분 56초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#20','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C7',3,'mc','auto','1시간 40분 55초 + 8시간 25분 15초는 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":20,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"1시간 40분 55초 + 8시간 25분 15초는 얼마인가요?","options":[{"t":"10시간 6분 10초","correct":true},{"t":"9시간 5분 10초","mis":"M3-1-u5-X14"},{"t":"11시간 6분 10초","mis":"M3-1-u5-X14"},{"t":"10시간 6분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 55 + 15 = 70 → 60초를 1분으로 받아올림, 분끼리 66 → 1시간으로 받아올림.","1시간 40분 55초 + 8시간 25분 15초 = 10시간 6분 10초예요."],"variant_rule":{"alt":[{"stem":"1시간 10분 50초 + 3시간 55분 25초는 얼마인가요?","options":[{"t":"5시간 6분 15초","correct":true},{"t":"4시간 5분 15초","mis":"M3-1-u5-X14"},{"t":"6시간 6분 15초","mis":"M3-1-u5-X14"},{"t":"5시간 6분 25초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 50 + 25 = 75 → 60초를 1분으로 받아올림, 분끼리 66 → 1시간으로 받아올림.","1시간 10분 50초 + 3시간 55분 25초 = 5시간 6분 15초예요."],"asset":null},{"stem":"2시간 55분 15초 + 35분 55초는 얼마인가요?","options":[{"t":"3시간 31분 10초","correct":true},{"t":"2시간 30분 10초","mis":"M3-1-u5-X14"},{"t":"4시간 31분 10초","mis":"M3-1-u5-X14"},{"t":"3시간 31분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 15 + 55 = 70 → 60초를 1분으로 받아올림, 분끼리 91 → 1시간으로 받아올림.","2시간 55분 15초 + 35분 55초 = 3시간 31분 10초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#21','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C8',3,'mc','auto','환경 인형극을 45분 동안 하고 3시 30분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X17','M3-1-u5-X16']::text[],true,'{"seq":21,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"환경 인형극을 45분 동안 하고 3시 30분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 45분","correct":true},{"t":"4시 15분","mis":"M3-1-u5-X20"},{"t":"3시 15분","mis":"M3-1-u5-X17"},{"t":"3시 45분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","3시 30분 − 45분 — 모자라면 60을 빌려 와요.","시작한 시각은 2시 45분이에요."],"variant_rule":{"alt":[{"stem":"숲 해설을 55분 동안 하고 5시 50분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"4시 55분","correct":true},{"t":"6시 45분","mis":"M3-1-u5-X20"},{"t":"5시 5분","mis":"M3-1-u5-X17"},{"t":"5시 55분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","5시 50분 − 55분 — 모자라면 60을 빌려 와요.","시작한 시각은 4시 55분이에요."],"asset":null},{"stem":"새 관찰을 40분 동안 하고 6시 35분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 55분","correct":true},{"t":"7시 15분","mis":"M3-1-u5-X20"},{"t":"6시 5분","mis":"M3-1-u5-X17"},{"t":"6시 55분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","6시 35분 − 40분 — 모자라면 60을 빌려 와요.","시작한 시각은 5시 55분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#22','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C9',3,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":22,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 45분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 하랑, 서윤.","단서 ② 45분보다 오래 산책한 친구: 서윤(50분 30초), 지유(1시간 9분 15초).","두 단서를 모두 만족하는 친구는 서윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","235 mm","4시 25분","5시 7분 30초"],["서윤","240 mm","3시 45분","4시 35분 30초"],["도윤","200 mm","2시 20분","2시 48분"],["지유","195 mm","1시 50분","2시 59분 15초"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X19"},{"t":"서윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 하랑, 지유.","단서 ② 35분보다 오래 산책한 친구: 도윤(56분 15초), 지유(1시간 13분).","두 단서를 모두 만족하는 친구는 지유예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","235 mm","2시 30분","2시 46분"],["서윤","190 mm","3시 5분","3시 31분 15초"],["도윤","205 mm","3시 5분","4시 1분 15초"],["지유","220 mm","4시 20분","5시 33분"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 205 mm보다 길어요. 단서 ② 산책을 50분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 205 mm보다 긴 친구: 하랑, 서윤.","단서 ② 50분보다 오래 산책한 친구: 서윤(57분 15초), 지유(1시간).","두 단서를 모두 만족하는 친구는 서윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","240 mm","2시 40분","3시 13분 45초"],["서윤","210 mm","1시 10분","2시 7분 15초"],["도윤","190 mm","3시 40분","4시 29분 20초"],["지유","195 mm","3시 10분","4시 10분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#23','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C8',4,'sa','auto','영화 가는 2시 30분에 시작해 4시 10분에 끝났고, 영화 나는 1시 55분에 시작해 3시 20분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u5-C8","difficulty":4,"kind":"sa","stem":"영화 가는 2시 30분에 시작해 4시 10분에 끝났고, 영화 나는 1시 55분에 시작해 3시 20분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["가: 4시 10분 − 2시 30분 = 1시간 40분.","나: 3시 20분 − 1시 55분 = 1시간 25분.","1시간 40분과 1시간 25분의 차 — 15분."],"variant_rule":{"alt":[{"stem":"영화 가는 1시 25분에 시작해 3시 15분에 끝났고, 영화 나는 2시 25분에 시작해 3시 35분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["가: 3시 15분 − 1시 25분 = 1시간 50분.","나: 3시 35분 − 2시 25분 = 1시간 10분.","1시간 50분과 1시간 10분의 차 — 40분."],"asset":null},{"stem":"영화 가는 1시 55분에 시작해 5시 35분에 끝났고, 영화 나는 2시 30분에 시작해 5시 20분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["가: 5시 35분 − 1시 55분 = 3시간 40분.","나: 5시 20분 − 2시 30분 = 2시간 50분.","3시간 40분과 2시간 50분의 차 — 50분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#24','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C7',4,'mc','auto','6시 25분에 숲 해설을 듣기 시작해서 30분 동안 듣고, 바로 이어서 1시간 50분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X14']::text[],true,'{"seq":24,"concept":"M3-1-u5-C7","difficulty":4,"kind":"mc","stem":"6시 25분에 숲 해설을 듣기 시작해서 30분 동안 듣고, 바로 이어서 1시간 50분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 45분","correct":true},{"t":"6시 55분","mis":"M3-1-u5-X19"},{"t":"8시 15분","mis":"M3-1-u5-X19"},{"t":"7시 45분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","6시 25분 + 30분 = 6시 55분.","6시 55분 + 1시간 50분 = 8시 45분이에요."],"variant_rule":{"alt":[{"stem":"7시 10분에 숲 해설을 듣기 시작해서 40분 동안 듣고, 바로 이어서 25분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 15분","correct":true},{"t":"7시 50분","mis":"M3-1-u5-X19"},{"t":"7시 35분","mis":"M3-1-u5-X19"},{"t":"7시 15분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","7시 10분 + 40분 = 7시 50분.","7시 50분 + 25분 = 8시 15분이에요."],"asset":null},{"stem":"7시 25분에 숲 해설을 듣기 시작해서 25분 동안 듣고, 바로 이어서 1시간 30분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 20분","correct":true},{"t":"7시 50분","mis":"M3-1-u5-X19"},{"t":"8시 55분","mis":"M3-1-u5-X19"},{"t":"8시 20분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","7시 25분 + 25분 = 7시 50분.","7시 50분 + 1시간 30분 = 9시 20분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_b#25','math',3,1,'u5','','g3_1_math_u5_review_b','unit_review','M3-1-u5-C8',4,'essay','teacher','기차가 3시 10분에 출발해 5시 5분에 도착했어요. 걸린 시간을 구하는 과정을 쓰고, 받아내림을 어떻게 했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u5-C8","difficulty":4,"kind":"essay","stem":"기차가 3시 10분에 출발해 5시 5분에 도착했어요. 걸린 시간을 구하는 과정을 쓰고, 받아내림을 어떻게 했는지 설명해 보세요.","answer_guide":{"answer":"예: 도착 시각 − 출발 시각 = 걸린 시간이다. 분끼리 5 − 10은 뺄 수 없으므로 5시에서 1시간(60분)을 빌려 와 65 − 10 = 55분이다. 시는 1 줄어 4 − 3 = 1시간이다. 걸린 시간은 1시간 55분이다.","scoring_points":["끝난 시각 − 시작 시각으로 식을 세웠는가","1시간(60분)을 빌려 오고 시를 1 줄였는가","1시간 55분을 구했는가"]},"explanation":["5시 5분 − 3시 10분.","65 − 10 = 55분, 4 − 3 = 1시간.","1시간 55분."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#1','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C1',1,'sa','auto','나뭇잎의 길이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u5-C1","difficulty":1,"kind":"sa","stem":"나뭇잎의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","나뭇잎 끝은 5 cm에서 작은 눈금 5칸 더 간 곳이에요.","5 cm 5 mm = 55 mm예요."],"asset":{"type":"mmruler","len":55,"label":"나뭇잎"},"variant_rule":{"alt":[{"stem":"솔방울의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","솔방울 끝은 3 cm에서 작은 눈금 8칸 더 간 곳이에요.","3 cm 8 mm = 38 mm예요."],"asset":{"type":"mmruler","len":38,"label":"솔방울"}},{"stem":"도토리의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","도토리 끝은 5 cm에서 작은 눈금 4칸 더 간 곳이에요.","5 cm 4 mm = 54 mm예요."],"asset":{"type":"mmruler","len":54,"label":"도토리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#2','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C2',1,'sa','auto','8 cm 7 mm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u5-C2","difficulty":1,"kind":"sa","stem":"8 cm 7 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["1 cm = 10 mm예요.","8 cm = 80 mm, 여기에 7 mm를 더해요.","8 cm 7 mm = 87 mm예요."],"variant_rule":{"alt":[{"stem":"5 cm 3 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["53"],"explanation":["1 cm = 10 mm예요.","5 cm = 50 mm, 여기에 3 mm를 더해요.","5 cm 3 mm = 53 mm예요."],"asset":null},{"stem":"7 cm 2 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["1 cm = 10 mm예요.","7 cm = 70 mm, 여기에 2 mm를 더해요.","7 cm 2 mm = 72 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#3','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C3',1,'mc','auto','엄지손가락 너비는 약 1 cm예요. 엄지가 18번쯤 들어가는 막대의 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X01','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 18번쯤 들어가는 막대의 길이는 약 얼마인가요?","options":[{"t":"약 18 cm","correct":true},{"t":"약 18 mm","mis":"M3-1-u5-X06"},{"t":"약 180 cm","mis":"M3-1-u5-X01"},{"t":"약 28 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","18번이면 약 18 cm.","어림한 길이라 앞에 「약」을 붙여 약 18 cm라고 해요."],"variant_rule":{"alt":[{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 4번쯤 들어가는 사인펜의 길이는 약 얼마인가요?","options":[{"t":"약 4 cm","correct":true},{"t":"약 4 mm","mis":"M3-1-u5-X06"},{"t":"약 40 cm","mis":"M3-1-u5-X01"},{"t":"약 14 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","4번이면 약 4 cm.","어림한 길이라 앞에 「약」을 붙여 약 4 cm라고 해요."],"asset":null},{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 15번쯤 들어가는 필통의 길이는 약 얼마인가요?","options":[{"t":"약 15 cm","correct":true},{"t":"약 15 mm","mis":"M3-1-u5-X06"},{"t":"약 150 cm","mis":"M3-1-u5-X01"},{"t":"약 25 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","15번이면 약 15 cm.","어림한 길이라 앞에 「약」을 붙여 약 15 cm라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#4','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C4',1,'mc','auto','3 km 850 m는 몇 m인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X02','M3-1-u5-X21']::text[],true,'{"seq":4,"concept":"M3-1-u5-C4","difficulty":1,"kind":"mc","stem":"3 km 850 m는 몇 m인가요?","options":[{"t":"3850 m","correct":true},{"t":"1150 m","mis":"M3-1-u5-X01"},{"t":"853 m","mis":"M3-1-u5-X02"},{"t":"3950 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 3 km = 3000 m.","3000 m + 850 m.","3 km 850 m = 3850 m예요."],"variant_rule":{"alt":[{"stem":"2 km 1 m는 몇 m인가요?","options":[{"t":"2001 m","correct":true},{"t":"21 m","mis":"M3-1-u5-X03"},{"t":"201 m","mis":"M3-1-u5-X01"},{"t":"2010 m","mis":"M3-1-u5-X03"}],"explanation":["1 km = 1000 m — 2 km = 2000 m.","2000 m + 1 m.","2 km 1 m = 2001 m예요."],"asset":null},{"stem":"1 km 903 m는 몇 m인가요?","options":[{"t":"1903 m","correct":true},{"t":"1003 m","mis":"M3-1-u5-X01"},{"t":"904 m","mis":"M3-1-u5-X02"},{"t":"2003 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 1 km = 1000 m.","1000 m + 903 m.","1 km 903 m = 1903 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#5','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C5',1,'mc','auto','운동장 한 바퀴는 약 200 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":5,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"운동장 한 바퀴는 약 200 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","운동장 한 바퀴는 약 200 m가 알맞아요."],"variant_rule":{"alt":[{"stem":"서울에서 제주도까지의 거리는 약 460 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","서울에서 제주도까지의 거리는 약 460 km가 알맞아요."],"asset":null},{"stem":"세계 온실까지의 거리는 약 1500 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","세계 온실까지의 거리는 약 1500 m가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#6','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C6',1,'sa','auto','1분 7초는 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u5-C6","difficulty":1,"kind":"sa","stem":"1분 7초는 몇 초인가요? 숫자로 쓰세요.","answer":["67"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 7초 = 60 + 7 = 67초예요."],"variant_rule":{"alt":[{"stem":"1분 21초는 몇 초인가요? 숫자로 쓰세요.","answer":["81"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 21초 = 60 + 21 = 81초예요."],"asset":null},{"stem":"1분 27초는 몇 초인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 27초 = 60 + 27 = 87초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#7','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C7',1,'mc','auto','1시간 20분 + 30분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":7,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"1시간 20분 + 30분은 얼마인가요?","options":[{"t":"1시간 50분","correct":true},{"t":"1시간 40분","mis":"M3-1-u5-X21"},{"t":"2시간 50분","mis":"M3-1-u5-X21"},{"t":"50분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 20 + 30 = 50.","1시간 20분 + 30분 = 1시간 50분이에요."],"variant_rule":{"alt":[{"stem":"6시간 5분 + 50분은 얼마인가요?","options":[{"t":"6시간 55분","correct":true},{"t":"6시간 45분","mis":"M3-1-u5-X21"},{"t":"7시간 55분","mis":"M3-1-u5-X21"},{"t":"5시간 55분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 5 + 50 = 55.","6시간 5분 + 50분 = 6시간 55분이에요."],"asset":null},{"stem":"8시간 10분 + 45분은 얼마인가요?","options":[{"t":"8시간 55분","correct":true},{"t":"8시간 45분","mis":"M3-1-u5-X21"},{"t":"9시간 55분","mis":"M3-1-u5-X21"},{"t":"7시간 55분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 10 + 45 = 55.","8시간 10분 + 45분 = 8시간 55분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#8','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C8',1,'mc','auto','5시간 25분 − 10분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":8,"concept":"M3-1-u5-C8","difficulty":1,"kind":"mc","stem":"5시간 25분 − 10분은 얼마인가요?","options":[{"t":"5시간 15분","correct":true},{"t":"5시간 25분","mis":"M3-1-u5-X21"},{"t":"5시간 5분","mis":"M3-1-u5-X21"},{"t":"6시간 15분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","5시간 25분 − 10분 = 5시간 15분이에요."],"variant_rule":{"alt":[{"stem":"4시간 55분 − 3시간 45분은 얼마인가요?","options":[{"t":"1시간 10분","correct":true},{"t":"1시간 20분","mis":"M3-1-u5-X21"},{"t":"1시간","mis":"M3-1-u5-X21"},{"t":"2시간 10분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","4시간 55분 − 3시간 45분 = 1시간 10분이에요."],"asset":null},{"stem":"2시간 15분 − 1시간 5분은 얼마인가요?","options":[{"t":"1시간 10분","correct":true},{"t":"1시간 20분","mis":"M3-1-u5-X21"},{"t":"1시간","mis":"M3-1-u5-X21"},{"t":"2시간 10분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","2시간 15분 − 1시간 5분 = 1시간 10분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#9','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C2',2,'mc','auto','79 mm는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X04']::text[],true,'{"seq":9,"concept":"M3-1-u5-C2","difficulty":2,"kind":"mc","stem":"79 mm는 몇 cm 몇 mm인가요?","options":[{"t":"7 cm 9 mm","correct":true},{"t":"9 cm 7 mm","mis":"M3-1-u5-X04"},{"t":"79 cm","mis":"M3-1-u5-X04"},{"t":"6 cm 19 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","79 mm = 70 mm + 9 mm.","79 mm = 7 cm 9 mm예요."],"variant_rule":{"alt":[{"stem":"12 mm는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 2 mm","correct":true},{"t":"2 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"12 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 2 mm","mis":"M3-1-u5-X21"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","12 mm = 10 mm + 2 mm.","12 mm = 1 cm 2 mm예요."],"asset":null},{"stem":"96 mm는 몇 cm 몇 mm인가요?","options":[{"t":"9 cm 6 mm","correct":true},{"t":"6 cm 9 mm","mis":"M3-1-u5-X04"},{"t":"96 cm","mis":"M3-1-u5-X04"},{"t":"8 cm 16 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","96 mm = 90 mm + 6 mm.","96 mm = 9 cm 6 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#10','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C3',2,'mc','auto','막대의 길이는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X05','M3-1-u5-X04']::text[],true,'{"seq":10,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"막대의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"5 cm 3 mm","correct":true},{"t":"7 cm 3 mm","mis":"M3-1-u5-X05"},{"t":"6 cm 3 mm","mis":"M3-1-u5-X05"},{"t":"3 cm 5 mm","mis":"M3-1-u5-X04"}],"explanation":["막대의 왼쪽 끝이 2에 있어요 — 0이 아니에요.","2에서 7 cm 3 mm 눈금까지 큰 눈금 5칸·작은 눈금 3칸.","길이는 5 cm 3 mm = 53 mm예요."],"asset":{"type":"mmruler","len":53,"label":"막대","s":2},"variant_rule":{"alt":[{"stem":"리본의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"2 cm 6 mm","correct":true},{"t":"5 cm 6 mm","mis":"M3-1-u5-X05"},{"t":"3 cm 6 mm","mis":"M3-1-u5-X05"},{"t":"6 cm 2 mm","mis":"M3-1-u5-X04"}],"explanation":["리본의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 5 cm 6 mm 눈금까지 큰 눈금 2칸·작은 눈금 6칸.","길이는 2 cm 6 mm = 26 mm예요."],"asset":{"type":"mmruler","len":26,"label":"리본","s":3}},{"stem":"색 테이프의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"6 cm 7 mm","correct":true},{"t":"8 cm 7 mm","mis":"M3-1-u5-X05"},{"t":"7 cm 7 mm","mis":"M3-1-u5-X05"},{"t":"7 cm 6 mm","mis":"M3-1-u5-X04"}],"explanation":["색 테이프의 왼쪽 끝이 2에 있어요 — 0이 아니에요.","2에서 8 cm 7 mm 눈금까지 큰 눈금 6칸·작은 눈금 7칸.","길이는 6 cm 7 mm = 67 mm예요."],"asset":{"type":"mmruler","len":67,"label":"색 테이프","s":2}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#11','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C4',2,'mc','auto','9244 m는 몇 km 몇 m인가요?',ARRAY['M3-1-u5-X04','M3-1-u5-X03','M3-1-u5-X01']::text[],true,'{"seq":11,"concept":"M3-1-u5-C4","difficulty":2,"kind":"mc","stem":"9244 m는 몇 km 몇 m인가요?","options":[{"t":"9 km 244 m","correct":true},{"t":"92 km 44 m","mis":"M3-1-u5-X04"},{"t":"9 km 24 m","mis":"M3-1-u5-X03"},{"t":"924 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","9244 m = 9000 m + 244 m.","9244 m = 9 km 244 m예요."],"variant_rule":{"alt":[{"stem":"1838 m는 몇 km 몇 m인가요?","options":[{"t":"1 km 838 m","correct":true},{"t":"18 km 38 m","mis":"M3-1-u5-X04"},{"t":"1 km 83 m","mis":"M3-1-u5-X03"},{"t":"183 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","1838 m = 1000 m + 838 m.","1838 m = 1 km 838 m예요."],"asset":null},{"stem":"3989 m는 몇 km 몇 m인가요?","options":[{"t":"3 km 989 m","correct":true},{"t":"39 km 89 m","mis":"M3-1-u5-X04"},{"t":"3 km 98 m","mis":"M3-1-u5-X03"},{"t":"398 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","3989 m = 3000 m + 989 m.","3989 m = 3 km 989 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#12','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C5',2,'mc','auto','지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?',ARRAY['M3-1-u5-X08']::text[],true,'{"seq":12,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 3 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m + 500 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"지도에서 약 250 m인 거리가 5번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 250 m","correct":true},{"t":"약 5 km","mis":"M3-1-u5-X08"},{"t":"약 125 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m = 1250 m.","1250 m = 1 km 250 m — 어림한 거리라 「약」을 붙여요."],"asset":null},{"stem":"지도에서 약 200 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 200 m","correct":true},{"t":"약 6 km","mis":"M3-1-u5-X08"},{"t":"약 120 m","mis":"M3-1-u5-X08"},{"t":"약 200 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 200 m가 몇 번 들어가는지 세어요.","200 m + 200 m + 200 m + 200 m + 200 m + 200 m = 1200 m.","1200 m = 1 km 200 m — 어림한 거리라 「약」을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#13','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C6',2,'mc','auto','시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11']::text[],true,'{"seq":13,"concept":"M3-1-u5-C6","difficulty":2,"kind":"mc","stem":"시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"2시 33분 50초","correct":true},{"t":"2시 50분 33초","mis":"M3-1-u5-X10"},{"t":"2시 33분 10초","mis":"M3-1-u5-X11"},{"t":"6시 10분 50초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 2와 3 사이 — 2시.","긴바늘은 33분, 가는 빨간 초바늘은 50초를 가리켜요.","2시 33분 50초예요."],"asset":{"type":"clock3","h":2,"m":33,"s":50},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"11시 21분 30초","correct":true},{"t":"11시 30분 21초","mis":"M3-1-u5-X10"},{"t":"11시 21분 6초","mis":"M3-1-u5-X11"},{"t":"4시 55분 30초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 11과 12 사이 — 11시.","긴바늘은 21분, 가는 빨간 초바늘은 30초를 가리켜요.","11시 21분 30초예요."],"asset":{"type":"clock3","h":11,"m":21,"s":30}},{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"8시 42분 25초","correct":true},{"t":"8시 25분 42초","mis":"M3-1-u5-X10"},{"t":"8시 42분 5초","mis":"M3-1-u5-X11"},{"t":"8시 40분 25초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 8과 9 사이 — 8시.","긴바늘은 42분, 가는 빨간 초바늘은 25초를 가리켜요.","8시 42분 25초예요."],"asset":{"type":"clock3","h":8,"m":42,"s":25}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#14','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C7',2,'mc','auto','동굴 체험을 3시 55분에 시작해서 25분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":14,"concept":"M3-1-u5-C7","difficulty":2,"kind":"mc","stem":"동굴 체험을 3시 55분에 시작해서 25분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"4시 20분","correct":true},{"t":"3시 20분","mis":"M3-1-u5-X14"},{"t":"5시 20분","mis":"M3-1-u5-X14"},{"t":"4시 30분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","3시 55분 + 25분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 4시 20분이에요."],"variant_rule":{"alt":[{"stem":"숲 해설 듣기를 1시 40분에 시작해서 40분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 20분","correct":true},{"t":"1시 20분","mis":"M3-1-u5-X14"},{"t":"3시 20분","mis":"M3-1-u5-X14"},{"t":"2시 30분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","1시 40분 + 40분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 2시 20분이에요."],"asset":null},{"stem":"씨앗 심기를 7시 30분에 시작해서 50분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 20분","correct":true},{"t":"7시 20분","mis":"M3-1-u5-X14"},{"t":"9시 20분","mis":"M3-1-u5-X14"},{"t":"8시 30분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","7시 30분 + 50분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 8시 20분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#15','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C8',2,'mc','auto','환경 인형극이 2시 45분에 시작해서 6시 10분에 끝났어요. 얼마 동안 했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":15,"concept":"M3-1-u5-C8","difficulty":2,"kind":"mc","stem":"환경 인형극이 2시 45분에 시작해서 6시 10분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 25분","correct":true},{"t":"4시간 35분","mis":"M3-1-u5-X17"},{"t":"4시간 25분","mis":"M3-1-u5-X16"},{"t":"3시간 65분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","6시 10분 − 2시 45분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 25분 동안 했어요."],"variant_rule":{"alt":[{"stem":"불 끄기 캠페인 영화가 1시 55분에 시작해서 4시 5분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"2시간 10분","correct":true},{"t":"3시간 50분","mis":"M3-1-u5-X17"},{"t":"3시간 10분","mis":"M3-1-u5-X16"},{"t":"2시간 50분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","4시 5분 − 1시 55분 — 같은 단위끼리, 모자라면 빌려 와요.","2시간 10분 동안 했어요."],"asset":null},{"stem":"숲 해설이 1시 10분에 시작해서 5시 5분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 55분","correct":true},{"t":"4시간 5분","mis":"M3-1-u5-X17"},{"t":"4시간 55분","mis":"M3-1-u5-X16"},{"t":"3시간 95분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 5분 − 1시 10분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 55분 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#16','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C9',2,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":16,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"지아","mis":"M3-1-u5-X19"},{"t":"태민","mis":"M3-1-u5-X19"},{"t":"수빈","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 지아, 현우.","단서 ② 40분보다 오래 산책한 친구: 태민, 현우.","두 단서를 모두 만족하는 친구는 현우예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","210 mm","55분"],["지아","230 mm","20분"],["현우","235 mm","50분"],["수빈","195 mm","35분"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하랑","correct":true},{"t":"도윤","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"서윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 하랑, 도윤.","단서 ② 30분보다 오래 산책한 친구: 하랑, 지유.","두 단서를 모두 만족하는 친구는 하랑이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["하랑","230 mm","50분"],["서윤","215 mm","20분"],["도윤","240 mm","25분"],["지유","200 mm","40분"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"태민","mis":"M3-1-u5-X19"},{"t":"수빈","mis":"M3-1-u5-X19"},{"t":"지아","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 태민, 현우.","단서 ② 30분보다 오래 산책한 친구: 현우, 수빈.","두 단서를 모두 만족하는 친구는 현우예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","240 mm","20분"],["지아","195 mm","15분"],["현우","235 mm","55분"],["수빈","210 mm","45분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#17','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C2',3,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 9 cm 3 mm ○ 89 mm',ARRAY['M3-1-u5-X04','M3-1-u5-X02','M3-1-u5-X20']::text[],true,'{"seq":17,"concept":"M3-1-u5-C2","difficulty":3,"kind":"mc","stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 9 cm 3 mm ○ 89 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","9 cm 3 mm = 93 mm예요.","93 > 89 — >예요."],"variant_rule":{"alt":[{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 5 cm 7 mm ○ 64 mm","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","5 cm 7 mm = 57 mm예요.","57 < 64 — <예요."],"asset":null},{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 5 cm 2 mm ○ 45 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","5 cm 2 mm = 52 mm예요.","52 > 45 — >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#18','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C4',3,'error','auto','km와 m의 관계를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X20']::text[],true,'{"seq":18,"concept":"M3-1-u5-C4","difficulty":3,"kind":"error","stem":"km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「3 km = 300 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"도윤 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"시우 — 「3691 m = 3 km 691 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","3 km = 3000 m예요.","태오는 1 km를 100 m로 잘못 알았어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「7 km = 700 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"태오 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"서윤 — 「7 km 510 m = 7510 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","7 km = 7000 m예요.","하린은 1 km를 100 m로 잘못 알았어요."],"asset":null},{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「6 km = 600 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"하랑 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"시우 — 「6940 m = 6 km 940 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","6 km = 6000 m예요.","서윤은 1 km를 100 m로 잘못 알았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#19','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C6',3,'mc','auto','232초는 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X04']::text[],true,'{"seq":19,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"232초는 몇 분 몇 초인가요?","options":[{"t":"3분 52초","correct":true},{"t":"2분 32초","mis":"M3-1-u5-X09"},{"t":"23분 2초","mis":"M3-1-u5-X04"},{"t":"2분 52초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","232 = 60 + 60 + 60 + 52.","232초 = 3분 52초예요."],"variant_rule":{"alt":[{"stem":"62초는 몇 분 몇 초인가요?","options":[{"t":"1분 2초","correct":true},{"t":"0분 62초","mis":"M3-1-u5-X09"},{"t":"6분 2초","mis":"M3-1-u5-X04"},{"t":"1분 20초","mis":"M3-1-u5-X03"}],"explanation":["60초 = 1분 — 60씩 묶어요.","62 = 60 + 2.","62초 = 1분 2초예요."],"asset":null},{"stem":"281초는 몇 분 몇 초인가요?","options":[{"t":"4분 41초","correct":true},{"t":"2분 81초","mis":"M3-1-u5-X09"},{"t":"28분 1초","mis":"M3-1-u5-X04"},{"t":"3분 41초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","281 = 60 + 60 + 60 + 60 + 41.","281초 = 4분 41초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#20','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C7',3,'mc','auto','8시간 25분 45초 + 45분 30초는 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":20,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"8시간 25분 45초 + 45분 30초는 얼마인가요?","options":[{"t":"9시간 11분 15초","correct":true},{"t":"8시간 10분 15초","mis":"M3-1-u5-X14"},{"t":"10시간 11분 15초","mis":"M3-1-u5-X14"},{"t":"9시간 11분 25초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 45 + 30 = 75 → 60초를 1분으로 받아올림, 분끼리 71 → 1시간으로 받아올림.","8시간 25분 45초 + 45분 30초 = 9시간 11분 15초예요."],"variant_rule":{"alt":[{"stem":"2시간 30분 25초 + 55분 55초는 얼마인가요?","options":[{"t":"3시간 26분 20초","correct":true},{"t":"2시간 25분 20초","mis":"M3-1-u5-X14"},{"t":"4시간 26분 20초","mis":"M3-1-u5-X14"},{"t":"3시간 26분 30초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 25 + 55 = 80 → 60초를 1분으로 받아올림, 분끼리 86 → 1시간으로 받아올림.","2시간 30분 25초 + 55분 55초 = 3시간 26분 20초예요."],"asset":null},{"stem":"1시간 50분 15초 + 10분 55초는 얼마인가요?","options":[{"t":"2시간 1분 10초","correct":true},{"t":"1시간 10초","mis":"M3-1-u5-X14"},{"t":"3시간 1분 10초","mis":"M3-1-u5-X14"},{"t":"2시간 1분 20초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 15 + 55 = 70 → 60초를 1분으로 받아올림, 분끼리 61 → 1시간으로 받아올림.","1시간 50분 15초 + 10분 55초 = 2시간 1분 10초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#21','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C8',3,'mc','auto','숲 해설을 25분 동안 하고 4시 15분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X17','M3-1-u5-X16']::text[],true,'{"seq":21,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"숲 해설을 25분 동안 하고 4시 15분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"3시 50분","correct":true},{"t":"4시 40분","mis":"M3-1-u5-X20"},{"t":"4시 10분","mis":"M3-1-u5-X17"},{"t":"4시 50분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","4시 15분 − 25분 — 모자라면 60을 빌려 와요.","시작한 시각은 3시 50분이에요."],"variant_rule":{"alt":[{"stem":"새 관찰을 50분 동안 하고 6시 15분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 25분","correct":true},{"t":"7시 5분","mis":"M3-1-u5-X20"},{"t":"6시 35분","mis":"M3-1-u5-X17"},{"t":"6시 25분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","6시 15분 − 50분 — 모자라면 60을 빌려 와요.","시작한 시각은 5시 25분이에요."],"asset":null},{"stem":"동굴 체험을 35분 동안 하고 10시 30분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 55분","correct":true},{"t":"11시 5분","mis":"M3-1-u5-X20"},{"t":"10시 5분","mis":"M3-1-u5-X17"},{"t":"10시 55분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","10시 30분 − 35분 — 모자라면 60을 빌려 와요.","시작한 시각은 9시 55분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#22','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C9',3,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":22,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 225 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"태민","correct":true},{"t":"수빈","mis":"M3-1-u5-X19"},{"t":"지아","mis":"M3-1-u5-X19"},{"t":"현우","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 225 mm보다 긴 친구: 태민, 수빈.","단서 ② 40분보다 오래 산책한 친구: 태민(54분 20초), 지아(55분 15초).","두 단서를 모두 만족하는 친구는 태민이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["태민","235 mm","1시 50분","2시 44분 20초"],["지아","220 mm","4시 50분","5시 45분 15초"],["현우","190 mm","4시 40분","5시 3분 20초"],["수빈","230 mm","3시 10분","3시 44분 30초"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 30분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하랑","correct":true},{"t":"서윤","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 220 mm보다 긴 친구: 하랑, 서윤.","단서 ② 30분보다 오래 산책한 친구: 하랑(54분 30초), 도윤(31분 45초).","두 단서를 모두 만족하는 친구는 하랑이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","235 mm","4시 30분","5시 24분 30초"],["서윤","240 mm","4시 10분","4시 34분 15초"],["도윤","200 mm","2시 55분","3시 26분 45초"],["지유","190 mm","2시 45분","3시 0분 30초"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 230 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"태민","correct":true},{"t":"수빈","mis":"M3-1-u5-X19"},{"t":"지아","mis":"M3-1-u5-X19"},{"t":"현우","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 230 mm보다 긴 친구: 태민, 수빈.","단서 ② 40분보다 오래 산책한 친구: 태민(59분 20초), 지아(53분 30초).","두 단서를 모두 만족하는 친구는 태민이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["태민","240 mm","4시 20분","5시 19분 20초"],["지아","220 mm","1시 30분","2시 23분 30초"],["현우","225 mm","1시 25분","1시 42분 15초"],["수빈","235 mm","3시 20분","3시 49분 30초"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#23','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C8',4,'sa','auto','영화 가는 1시 30분에 시작해 3시 20분에 끝났고, 영화 나는 1시 25분에 시작해 2시 50분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u5-C8","difficulty":4,"kind":"sa","stem":"영화 가는 1시 30분에 시작해 3시 20분에 끝났고, 영화 나는 1시 25분에 시작해 2시 50분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["가: 3시 20분 − 1시 30분 = 1시간 50분.","나: 2시 50분 − 1시 25분 = 1시간 25분.","1시간 50분과 1시간 25분의 차 — 25분."],"variant_rule":{"alt":[{"stem":"영화 가는 2시 35분에 시작해 5시 20분에 끝났고, 영화 나는 1시 35분에 시작해 3시 40분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["가: 5시 20분 − 2시 35분 = 2시간 45분.","나: 3시 40분 − 1시 35분 = 2시간 5분.","2시간 45분과 2시간 5분의 차 — 40분."],"asset":null},{"stem":"영화 가는 2시 55분에 시작해 6시 10분에 끝났고, 영화 나는 1시 50분에 시작해 4시 45분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가: 6시 10분 − 2시 55분 = 3시간 15분.","나: 4시 45분 − 1시 50분 = 2시간 55분.","3시간 15분과 2시간 55분의 차 — 20분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#24','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C7',4,'mc','auto','6시 55분에 숲 해설을 듣기 시작해서 20분 동안 듣고, 바로 이어서 1시간 15분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X14']::text[],true,'{"seq":24,"concept":"M3-1-u5-C7","difficulty":4,"kind":"mc","stem":"6시 55분에 숲 해설을 듣기 시작해서 20분 동안 듣고, 바로 이어서 1시간 15분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 30분","correct":true},{"t":"7시 15분","mis":"M3-1-u5-X19"},{"t":"8시 10분","mis":"M3-1-u5-X19"},{"t":"7시 30분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","6시 55분 + 20분 = 7시 15분.","7시 15분 + 1시간 15분 = 8시 30분이에요."],"variant_rule":{"alt":[{"stem":"7시 50분에 숲 해설을 듣기 시작해서 35분 동안 듣고, 바로 이어서 50분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 15분","correct":true},{"t":"8시 25분","mis":"M3-1-u5-X19"},{"t":"8시 40분","mis":"M3-1-u5-X19"},{"t":"8시 15분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","7시 50분 + 35분 = 8시 25분.","8시 25분 + 50분 = 9시 15분이에요."],"asset":null},{"stem":"3시 50분에 숲 해설을 듣기 시작해서 25분 동안 듣고, 바로 이어서 30분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"4시 45분","correct":true},{"t":"4시 15분","mis":"M3-1-u5-X19"},{"t":"4시 20분","mis":"M3-1-u5-X19"},{"t":"3시 45분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","3시 50분 + 25분 = 4시 15분.","4시 15분 + 30분 = 4시 45분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_c#25','math',3,1,'u5','','g3_1_math_u5_review_c','unit_review','M3-1-u5-C4',4,'essay','teacher','집에서 도서관까지는 3 km 70 m, 공원까지는 3700 m예요. 어느 곳이 더 먼지 단위를 맞추어 견주는 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u5-C4","difficulty":4,"kind":"essay","stem":"집에서 도서관까지는 3 km 70 m, 공원까지는 3700 m예요. 어느 곳이 더 먼지 단위를 맞추어 견주는 방법을 써 보세요.","answer_guide":{"answer":"예: 3 km 70 m를 m로 바꾸면 3000 m + 70 m = 3070 m이다. 3070 m와 3700 m를 견주면 3700 m가 더 길다. 그래서 공원이 더 멀다.","scoring_points":["3 km 70 m = 3070 m로 바꾸었는가","두 거리를 m로 견주었는가","공원이 더 멀다고 답했는가"]},"explanation":["3 km 70 m = 3070 m.","3070 m < 3700 m.","공원이 더 멀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#1','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C1',1,'sa','auto','솔방울의 길이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u5-C1","difficulty":1,"kind":"sa","stem":"솔방울의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","솔방울 끝은 5 cm에서 작은 눈금 4칸 더 간 곳이에요.","5 cm 4 mm = 54 mm예요."],"asset":{"type":"mmruler","len":54,"label":"솔방울"},"variant_rule":{"alt":[{"stem":"도토리의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","도토리 끝은 1 cm에서 작은 눈금 4칸 더 간 곳이에요.","1 cm 4 mm = 14 mm예요."],"asset":{"type":"mmruler","len":14,"label":"도토리"}},{"stem":"막대의 길이는 몇 mm인가요? 숫자로 쓰세요.","answer":["82"],"explanation":["작은 눈금 한 칸이 1 mm, 큰 눈금(숫자) 한 칸이 1 cm = 10 mm예요.","막대 끝은 8 cm에서 작은 눈금 2칸 더 간 곳이에요.","8 cm 2 mm = 82 mm예요."],"asset":{"type":"mmruler","len":82,"label":"막대"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#2','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C2',1,'sa','auto','3 cm 3 mm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u5-C2","difficulty":1,"kind":"sa","stem":"3 cm 3 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["1 cm = 10 mm예요.","3 cm = 30 mm, 여기에 3 mm를 더해요.","3 cm 3 mm = 33 mm예요."],"variant_rule":{"alt":[{"stem":"3 cm 9 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["1 cm = 10 mm예요.","3 cm = 30 mm, 여기에 9 mm를 더해요.","3 cm 9 mm = 39 mm예요."],"asset":null},{"stem":"4 cm 1 mm는 몇 mm인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["1 cm = 10 mm예요.","4 cm = 40 mm, 여기에 1 mm를 더해요.","4 cm 1 mm = 41 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#3','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C3',1,'mc','auto','엄지손가락 너비는 약 1 cm예요. 엄지가 14번쯤 들어가는 풀의 길이는 약 얼마인가요?',ARRAY['M3-1-u5-X06','M3-1-u5-X01','M3-1-u5-X21']::text[],true,'{"seq":3,"concept":"M3-1-u5-C3","difficulty":1,"kind":"mc","stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 14번쯤 들어가는 풀의 길이는 약 얼마인가요?","options":[{"t":"약 14 cm","correct":true},{"t":"약 14 mm","mis":"M3-1-u5-X06"},{"t":"약 140 cm","mis":"M3-1-u5-X01"},{"t":"약 24 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","14번이면 약 14 cm.","어림한 길이라 앞에 「약」을 붙여 약 14 cm라고 해요."],"variant_rule":{"alt":[{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 17번쯤 들어가는 막대의 길이는 약 얼마인가요?","options":[{"t":"약 17 cm","correct":true},{"t":"약 17 mm","mis":"M3-1-u5-X06"},{"t":"약 170 cm","mis":"M3-1-u5-X01"},{"t":"약 27 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","17번이면 약 17 cm.","어림한 길이라 앞에 「약」을 붙여 약 17 cm라고 해요."],"asset":null},{"stem":"엄지손가락 너비는 약 1 cm예요. 엄지가 12번쯤 들어가는 사인펜의 길이는 약 얼마인가요?","options":[{"t":"약 12 cm","correct":true},{"t":"약 12 mm","mis":"M3-1-u5-X06"},{"t":"약 120 cm","mis":"M3-1-u5-X01"},{"t":"약 22 cm","mis":"M3-1-u5-X21"}],"explanation":["엄지 한 번이 약 1 cm예요.","12번이면 약 12 cm.","어림한 길이라 앞에 「약」을 붙여 약 12 cm라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#4','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C4',1,'mc','auto','9 km 82 m는 몇 m인가요?',ARRAY['M3-1-u5-X03','M3-1-u5-X02']::text[],true,'{"seq":4,"concept":"M3-1-u5-C4","difficulty":1,"kind":"mc","stem":"9 km 82 m는 몇 m인가요?","options":[{"t":"9082 m","correct":true},{"t":"982 m","mis":"M3-1-u5-X03"},{"t":"9820 m","mis":"M3-1-u5-X03"},{"t":"91 m","mis":"M3-1-u5-X02"}],"explanation":["1 km = 1000 m — 9 km = 9000 m.","9000 m + 82 m.","9 km 82 m = 9082 m예요."],"variant_rule":{"alt":[{"stem":"9 km 140 m는 몇 m인가요?","options":[{"t":"9140 m","correct":true},{"t":"1040 m","mis":"M3-1-u5-X01"},{"t":"149 m","mis":"M3-1-u5-X02"},{"t":"9240 m","mis":"M3-1-u5-X21"}],"explanation":["1 km = 1000 m — 9 km = 9000 m.","9000 m + 140 m.","9 km 140 m = 9140 m예요."],"asset":null},{"stem":"3 km 28 m는 몇 m인가요?","options":[{"t":"3028 m","correct":true},{"t":"328 m","mis":"M3-1-u5-X03"},{"t":"3280 m","mis":"M3-1-u5-X03"},{"t":"31 m","mis":"M3-1-u5-X02"}],"explanation":["1 km = 1000 m — 3 km = 3000 m.","3000 m + 28 m.","3 km 28 m = 3028 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#5','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C5',1,'mc','auto','기차의 길이는 약 300 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?',ARRAY['M3-1-u5-X06']::text[],true,'{"seq":5,"concept":"M3-1-u5-C5","difficulty":1,"kind":"mc","stem":"기차의 길이는 약 300 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","기차의 길이는 약 300 m가 알맞아요."],"variant_rule":{"alt":[{"stem":"교실 긴 쪽의 길이는 약 9 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"m","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"km","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","교실 긴 쪽의 길이는 약 9 m가 알맞아요."],"asset":null},{"stem":"서울에서 부산까지의 거리는 약 400 ◯◯예요. ◯◯에 알맞은 단위는 어느 것인가요?","options":[{"t":"km","correct":true},{"t":"mm","mis":"M3-1-u5-X06"},{"t":"cm","mis":"M3-1-u5-X06"},{"t":"m","mis":"M3-1-u5-X06"}],"explanation":["대상의 크기를 떠올려 단위를 골라요.","작은 것은 mm·cm, 건물·산은 m, 도시 사이 거리는 km예요.","서울에서 부산까지의 거리는 약 400 km가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#6','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C6',1,'sa','auto','1분 14초는 몇 초인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u5-C6","difficulty":1,"kind":"sa","stem":"1분 14초는 몇 초인가요? 숫자로 쓰세요.","answer":["74"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 14초 = 60 + 14 = 74초예요."],"variant_rule":{"alt":[{"stem":"1분 37초는 몇 초인가요? 숫자로 쓰세요.","answer":["97"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 37초 = 60 + 37 = 97초예요."],"asset":null},{"stem":"1분 21초는 몇 초인가요? 숫자로 쓰세요.","answer":["81"],"explanation":["1분 = 60초예요.","1분 = 60초.","1분 21초 = 60 + 21 = 81초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#7','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C7',1,'mc','auto','8시간 50분 + 5시간 5분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":7,"concept":"M3-1-u5-C7","difficulty":1,"kind":"mc","stem":"8시간 50분 + 5시간 5분은 얼마인가요?","options":[{"t":"13시간 55분","correct":true},{"t":"13시간 45분","mis":"M3-1-u5-X21"},{"t":"14시간 55분","mis":"M3-1-u5-X21"},{"t":"12시간 55분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 50 + 5 = 55.","8시간 50분 + 5시간 5분 = 13시간 55분이에요."],"variant_rule":{"alt":[{"stem":"2시간 15분 + 20분은 얼마인가요?","options":[{"t":"2시간 35분","correct":true},{"t":"2시간 45분","mis":"M3-1-u5-X21"},{"t":"2시간 25분","mis":"M3-1-u5-X21"},{"t":"3시간 35분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 15 + 20 = 35.","2시간 15분 + 20분 = 2시간 35분이에요."],"asset":null},{"stem":"1시간 10분 + 7시간 45분은 얼마인가요?","options":[{"t":"8시간 55분","correct":true},{"t":"8시간 45분","mis":"M3-1-u5-X21"},{"t":"9시간 55분","mis":"M3-1-u5-X21"},{"t":"7시간 55분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","분끼리 10 + 45 = 55.","1시간 10분 + 7시간 45분 = 8시간 55분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#8','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C8',1,'mc','auto','7시간 40분 − 25분은 얼마인가요?',ARRAY['M3-1-u5-X21']::text[],true,'{"seq":8,"concept":"M3-1-u5-C8","difficulty":1,"kind":"mc","stem":"7시간 40분 − 25분은 얼마인가요?","options":[{"t":"7시간 15분","correct":true},{"t":"7시간 25분","mis":"M3-1-u5-X21"},{"t":"7시간 5분","mis":"M3-1-u5-X21"},{"t":"8시간 15분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","7시간 40분 − 25분 = 7시간 15분이에요."],"variant_rule":{"alt":[{"stem":"8시간 45분 − 4시간 40분은 얼마인가요?","options":[{"t":"4시간 5분","correct":true},{"t":"4시간 15분","mis":"M3-1-u5-X21"},{"t":"5시간 5분","mis":"M3-1-u5-X21"},{"t":"3시간 5분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","8시간 45분 − 4시간 40분 = 4시간 5분이에요."],"asset":null},{"stem":"8시간 50분 − 2시간 15분은 얼마인가요?","options":[{"t":"6시간 35분","correct":true},{"t":"6시간 45분","mis":"M3-1-u5-X21"},{"t":"6시간 25분","mis":"M3-1-u5-X21"},{"t":"7시간 35분","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 빼요.","받아내림 없이 같은 단위끼리 빼요.","8시간 50분 − 2시간 15분 = 6시간 35분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#9','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C2',2,'mc','auto','94 mm는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X04']::text[],true,'{"seq":9,"concept":"M3-1-u5-C2","difficulty":2,"kind":"mc","stem":"94 mm는 몇 cm 몇 mm인가요?","options":[{"t":"9 cm 4 mm","correct":true},{"t":"4 cm 9 mm","mis":"M3-1-u5-X04"},{"t":"94 cm","mis":"M3-1-u5-X04"},{"t":"8 cm 14 mm","mis":"M3-1-u5-X04"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","94 mm = 90 mm + 4 mm.","94 mm = 9 cm 4 mm예요."],"variant_rule":{"alt":[{"stem":"16 mm는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 6 mm","correct":true},{"t":"6 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"16 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 6 mm","mis":"M3-1-u5-X21"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","16 mm = 10 mm + 6 mm.","16 mm = 1 cm 6 mm예요."],"asset":null},{"stem":"15 mm는 몇 cm 몇 mm인가요?","options":[{"t":"1 cm 5 mm","correct":true},{"t":"5 cm 1 mm","mis":"M3-1-u5-X04"},{"t":"15 cm","mis":"M3-1-u5-X04"},{"t":"2 cm 5 mm","mis":"M3-1-u5-X21"}],"explanation":["10 mm = 1 cm — 10씩 묶어요.","15 mm = 10 mm + 5 mm.","15 mm = 1 cm 5 mm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#10','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C3',2,'mc','auto','리본의 길이는 몇 cm 몇 mm인가요?',ARRAY['M3-1-u5-X05','M3-1-u5-X04']::text[],true,'{"seq":10,"concept":"M3-1-u5-C3","difficulty":2,"kind":"mc","stem":"리본의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"6 cm 9 mm","correct":true},{"t":"7 cm 9 mm","mis":"M3-1-u5-X05"},{"t":"9 cm 6 mm","mis":"M3-1-u5-X04"},{"t":"6 cm 8 mm","mis":"M3-1-u5-X05"}],"explanation":["리본의 왼쪽 끝이 1에 있어요 — 0이 아니에요.","1에서 7 cm 9 mm 눈금까지 큰 눈금 6칸·작은 눈금 9칸.","길이는 6 cm 9 mm = 69 mm예요."],"asset":{"type":"mmruler","len":69,"label":"리본","s":1},"variant_rule":{"alt":[{"stem":"색 테이프의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"2 cm 3 mm","correct":true},{"t":"3 cm 3 mm","mis":"M3-1-u5-X05"},{"t":"3 cm 2 mm","mis":"M3-1-u5-X04"},{"t":"2 cm 4 mm","mis":"M3-1-u5-X05"}],"explanation":["색 테이프의 왼쪽 끝이 1에 있어요 — 0이 아니에요.","1에서 3 cm 3 mm 눈금까지 큰 눈금 2칸·작은 눈금 3칸.","길이는 2 cm 3 mm = 23 mm예요."],"asset":{"type":"mmruler","len":23,"label":"색 테이프","s":1}},{"stem":"잎자루의 길이는 몇 cm 몇 mm인가요?","options":[{"t":"2 cm 9 mm","correct":true},{"t":"5 cm 9 mm","mis":"M3-1-u5-X05"},{"t":"3 cm 9 mm","mis":"M3-1-u5-X05"},{"t":"9 cm 2 mm","mis":"M3-1-u5-X04"}],"explanation":["잎자루의 왼쪽 끝이 3에 있어요 — 0이 아니에요.","3에서 5 cm 9 mm 눈금까지 큰 눈금 2칸·작은 눈금 9칸.","길이는 2 cm 9 mm = 29 mm예요."],"asset":{"type":"mmruler","len":29,"label":"잎자루","s":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#11','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C4',2,'mc','auto','2254 m는 몇 km 몇 m인가요?',ARRAY['M3-1-u5-X04','M3-1-u5-X03','M3-1-u5-X01']::text[],true,'{"seq":11,"concept":"M3-1-u5-C4","difficulty":2,"kind":"mc","stem":"2254 m는 몇 km 몇 m인가요?","options":[{"t":"2 km 254 m","correct":true},{"t":"22 km 54 m","mis":"M3-1-u5-X04"},{"t":"2 km 25 m","mis":"M3-1-u5-X03"},{"t":"225 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","2254 m = 2000 m + 254 m.","2254 m = 2 km 254 m예요."],"variant_rule":{"alt":[{"stem":"6315 m는 몇 km 몇 m인가요?","options":[{"t":"6 km 315 m","correct":true},{"t":"63 km 15 m","mis":"M3-1-u5-X04"},{"t":"6 km 31 m","mis":"M3-1-u5-X03"},{"t":"631 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","6315 m = 6000 m + 315 m.","6315 m = 6 km 315 m예요."],"asset":null},{"stem":"7721 m는 몇 km 몇 m인가요?","options":[{"t":"7 km 721 m","correct":true},{"t":"77 km 21 m","mis":"M3-1-u5-X04"},{"t":"7 km 72 m","mis":"M3-1-u5-X03"},{"t":"772 m","mis":"M3-1-u5-X01"}],"explanation":["1000 m = 1 km — 1000씩 묶어요.","7721 m = 7000 m + 721 m.","7721 m = 7 km 721 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#12','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C5',2,'mc','auto','지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?',ARRAY['M3-1-u5-X08']::text[],true,'{"seq":12,"concept":"M3-1-u5-C5","difficulty":2,"kind":"mc","stem":"지도에서 약 500 m인 거리가 3번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 3 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 500 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 500 m가 몇 번 들어가는지 세어요.","500 m + 500 m + 500 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"지도에서 약 250 m인 거리가 5번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 250 m","correct":true},{"t":"약 5 km","mis":"M3-1-u5-X08"},{"t":"약 125 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m = 1250 m.","1250 m = 1 km 250 m — 어림한 거리라 「약」을 붙여요."],"asset":null},{"stem":"지도에서 약 250 m인 거리가 6번 들어가는 곳까지의 거리는 약 얼마인가요?","options":[{"t":"약 1 km 500 m","correct":true},{"t":"약 6 km","mis":"M3-1-u5-X08"},{"t":"약 150 m","mis":"M3-1-u5-X08"},{"t":"약 250 m","mis":"M3-1-u5-X08"}],"explanation":["단위 거리 약 250 m가 몇 번 들어가는지 세어요.","250 m + 250 m + 250 m + 250 m + 250 m + 250 m = 1500 m.","1500 m = 1 km 500 m — 어림한 거리라 「약」을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#13','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C6',2,'mc','auto','시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X10','M3-1-u5-X11']::text[],true,'{"seq":13,"concept":"M3-1-u5-C6","difficulty":2,"kind":"mc","stem":"시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"1시 58분 10초","correct":true},{"t":"1시 10분 58초","mis":"M3-1-u5-X10"},{"t":"1시 58분 2초","mis":"M3-1-u5-X11"},{"t":"11시 5분 10초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 1과 2 사이 — 1시.","긴바늘은 58분, 가는 빨간 초바늘은 10초를 가리켜요.","1시 58분 10초예요."],"asset":{"type":"clock3","h":1,"m":58,"s":10},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"1시 41분 49초","correct":true},{"t":"1시 49분 41초","mis":"M3-1-u5-X10"},{"t":"1시 41분 50초","mis":"M3-1-u5-X21"},{"t":"8시 5분 49초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 1과 2 사이 — 1시.","긴바늘은 41분, 가는 빨간 초바늘은 49초를 가리켜요.","1시 41분 49초예요."],"asset":{"type":"clock3","h":1,"m":41,"s":49}},{"stem":"이번에는 다른 문제예요. 시계가 가리키는 시각은 몇 시 몇 분 몇 초인가요?","options":[{"t":"6시 54분 10초","correct":true},{"t":"6시 10분 54초","mis":"M3-1-u5-X10"},{"t":"6시 54분 2초","mis":"M3-1-u5-X11"},{"t":"10시 30분 10초","mis":"M3-1-u5-X10"}],"explanation":["짧은바늘은 6과 7 사이 — 6시.","긴바늘은 54분, 가는 빨간 초바늘은 10초를 가리켜요.","6시 54분 10초예요."],"asset":{"type":"clock3","h":6,"m":54,"s":10}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#14','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C7',2,'mc','auto','새 관찰을 8시 55분에 시작해서 15분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X15']::text[],true,'{"seq":14,"concept":"M3-1-u5-C7","difficulty":2,"kind":"mc","stem":"새 관찰을 8시 55분에 시작해서 15분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 10분","correct":true},{"t":"8시 10분","mis":"M3-1-u5-X14"},{"t":"23시 55분","mis":"M3-1-u5-X15"},{"t":"10시 10분","mis":"M3-1-u5-X14"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","8시 55분 + 15분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 9시 10분이에요."],"variant_rule":{"alt":[{"stem":"동굴 체험을 4시 50분에 시작해서 40분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 30분","correct":true},{"t":"4시 30분","mis":"M3-1-u5-X14"},{"t":"6시 30분","mis":"M3-1-u5-X14"},{"t":"5시 40분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","4시 50분 + 40분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 5시 30분이에요."],"asset":null},{"stem":"숲 해설 듣기를 4시 15분에 시작해서 50분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 5분","correct":true},{"t":"4시 5분","mis":"M3-1-u5-X14"},{"t":"6시 5분","mis":"M3-1-u5-X14"},{"t":"5시 15분","mis":"M3-1-u5-X21"}],"explanation":["시작 시각 + 걸린 시간 = 끝난 시각이에요.","4시 15분 + 50분 — 같은 단위끼리 더하고 60이 넘으면 받아올림해요.","끝난 시각은 5시 5분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#15','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C8',2,'mc','auto','불 끄기 캠페인 영화가 1시 55분에 시작해서 5시 50분에 끝났어요. 얼마 동안 했나요?',ARRAY['M3-1-u5-X17','M3-1-u5-X16','M3-1-u5-X09']::text[],true,'{"seq":15,"concept":"M3-1-u5-C8","difficulty":2,"kind":"mc","stem":"불 끄기 캠페인 영화가 1시 55분에 시작해서 5시 50분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 55분","correct":true},{"t":"4시간 5분","mis":"M3-1-u5-X17"},{"t":"4시간 55분","mis":"M3-1-u5-X16"},{"t":"3시간 95분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","5시 50분 − 1시 55분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 55분 동안 했어요."],"variant_rule":{"alt":[{"stem":"숲 해설이 2시 45분에 시작해서 4시 40분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"1시간 55분","correct":true},{"t":"2시간 5분","mis":"M3-1-u5-X17"},{"t":"2시간 55분","mis":"M3-1-u5-X16"},{"t":"1시간 95분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","4시 40분 − 2시 45분 — 같은 단위끼리, 모자라면 빌려 와요.","1시간 55분 동안 했어요."],"asset":null},{"stem":"동굴 체험이 2시 40분에 시작해서 6시 20분에 끝났어요. 얼마 동안 했나요?","options":[{"t":"3시간 40분","correct":true},{"t":"4시간 20분","mis":"M3-1-u5-X17"},{"t":"4시간 40분","mis":"M3-1-u5-X16"},{"t":"3시간 80분","mis":"M3-1-u5-X09"}],"explanation":["걸린 시간 = 끝난 시각 − 시작 시각이에요.","6시 20분 − 2시 40분 — 같은 단위끼리, 모자라면 빌려 와요.","3시간 40분 동안 했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#16','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C9',2,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":16,"concept":"M3-1-u5-C9","difficulty":2,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"서윤","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 220 mm보다 긴 친구: 하랑, 도윤.","단서 ② 40분보다 오래 산책한 친구: 서윤, 도윤.","두 단서를 모두 만족하는 친구는 도윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["하랑","235 mm","25분"],["서윤","195 mm","45분"],["도윤","240 mm","50분"],["지유","190 mm","15분"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 220 mm보다 길어요. 단서 ② 산책을 40분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"수빈","correct":true},{"t":"태민","mis":"M3-1-u5-X19"},{"t":"현우","mis":"M3-1-u5-X19"},{"t":"지아","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 220 mm보다 긴 친구: 태민, 수빈.","단서 ② 40분보다 오래 산책한 친구: 현우, 수빈.","두 단서를 모두 만족하는 친구는 수빈이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["태민","240 mm","15분"],["지아","200 mm","20분"],["현우","210 mm","50분"],["수빈","230 mm","45분"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"은우","mis":"M3-1-u5-X19"},{"t":"태오","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 은우, 하린.","단서 ② 35분보다 오래 산책한 친구: 하린, 태오.","두 단서를 모두 만족하는 친구는 하린이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","산책 시간"],["은우","235 mm","30분"],["하린","215 mm","45분"],["태오","190 mm","50분"],["민준","205 mm","15분"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#17','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C2',3,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 5 cm 3 mm ○ 48 mm',ARRAY['M3-1-u5-X04','M3-1-u5-X02','M3-1-u5-X20']::text[],true,'{"seq":17,"concept":"M3-1-u5-C2","difficulty":3,"kind":"mc","stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 5 cm 3 mm ○ 48 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","5 cm 3 mm = 53 mm예요.","53 > 48 — >예요."],"variant_rule":{"alt":[{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 6 cm 5 mm ○ 55 mm","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","6 cm 5 mm = 65 mm예요.","65 > 55 — >예요."],"asset":null},{"stem":"두 길이를 견주어 ○ 안에 알맞은 것을 고르세요. 5 cm 9 mm ○ 62 mm","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u5-X04"},{"t":"=","mis":"M3-1-u5-X02"},{"t":"알 수 없다","mis":"M3-1-u5-X20"}],"explanation":["단위를 mm로 맞춰요.","5 cm 9 mm = 59 mm예요.","59 < 62 — <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#18','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C4',3,'error','auto','km와 m의 관계를 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u5-X01','M3-1-u5-X20']::text[],true,'{"seq":18,"concept":"M3-1-u5-C4","difficulty":3,"kind":"error","stem":"km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「9 km = 900 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"하은 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"태오 — 「9 km 790 m = 9790 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","9 km = 9000 m예요.","서윤은 1 km를 100 m로 잘못 알았어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「9 km = 900 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"은우 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"시우 — 「9431 m = 9 km 431 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","9 km = 9000 m예요.","하린은 1 km를 100 m로 잘못 알았어요."],"asset":null},{"stem":"이번에는 다른 문제예요. km와 m의 관계를 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「3 km = 300 m야」","correct":true,"mis_target":"M3-1-u5-X01"},{"t":"하랑 — 「1 km = 1000 m야」","mis":"M3-1-u5-X20"},{"t":"도윤 — 「3 km 695 m = 3695 m야」","mis":"M3-1-u5-X20"}],"explanation":["1 km = 1000 m예요.","3 km = 3000 m예요.","태오는 1 km를 100 m로 잘못 알았어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#19','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C6',3,'mc','auto','245초는 몇 분 몇 초인가요?',ARRAY['M3-1-u5-X09','M3-1-u5-X04','M3-1-u5-X03']::text[],true,'{"seq":19,"concept":"M3-1-u5-C6","difficulty":3,"kind":"mc","stem":"245초는 몇 분 몇 초인가요?","options":[{"t":"4분 5초","correct":true},{"t":"2분 45초","mis":"M3-1-u5-X09"},{"t":"24분 5초","mis":"M3-1-u5-X04"},{"t":"4분 50초","mis":"M3-1-u5-X03"}],"explanation":["60초 = 1분 — 60씩 묶어요.","245 = 60 + 60 + 60 + 60 + 5.","245초 = 4분 5초예요."],"variant_rule":{"alt":[{"stem":"285초는 몇 분 몇 초인가요?","options":[{"t":"4분 45초","correct":true},{"t":"2분 85초","mis":"M3-1-u5-X09"},{"t":"28분 5초","mis":"M3-1-u5-X04"},{"t":"3분 45초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","285 = 60 + 60 + 60 + 60 + 45.","285초 = 4분 45초예요."],"asset":null},{"stem":"252초는 몇 분 몇 초인가요?","options":[{"t":"4분 12초","correct":true},{"t":"2분 52초","mis":"M3-1-u5-X09"},{"t":"25분 2초","mis":"M3-1-u5-X04"},{"t":"3분 12초","mis":"M3-1-u5-X04"}],"explanation":["60초 = 1분 — 60씩 묶어요.","252 = 60 + 60 + 60 + 60 + 12.","252초 = 4분 12초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#20','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C7',3,'mc','auto','3시간 35분 35초 + 3시간 55분 45초는 얼마인가요?',ARRAY['M3-1-u5-X14','M3-1-u5-X21']::text[],true,'{"seq":20,"concept":"M3-1-u5-C7","difficulty":3,"kind":"mc","stem":"3시간 35분 35초 + 3시간 55분 45초는 얼마인가요?","options":[{"t":"7시간 31분 20초","correct":true},{"t":"6시간 30분 20초","mis":"M3-1-u5-X14"},{"t":"8시간 31분 20초","mis":"M3-1-u5-X14"},{"t":"7시간 31분 30초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 35 + 45 = 80 → 60초를 1분으로 받아올림, 분끼리 91 → 1시간으로 받아올림.","3시간 35분 35초 + 3시간 55분 45초 = 7시간 31분 20초예요."],"variant_rule":{"alt":[{"stem":"2시간 55분 35초 + 45분 45초는 얼마인가요?","options":[{"t":"3시간 41분 20초","correct":true},{"t":"2시간 40분 20초","mis":"M3-1-u5-X14"},{"t":"4시간 41분 20초","mis":"M3-1-u5-X14"},{"t":"3시간 41분 30초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 35 + 45 = 80 → 60초를 1분으로 받아올림, 분끼리 101 → 1시간으로 받아올림.","2시간 55분 35초 + 45분 45초 = 3시간 41분 20초예요."],"asset":null},{"stem":"6시간 35분 55초 + 45분 25초는 얼마인가요?","options":[{"t":"7시간 21분 20초","correct":true},{"t":"6시간 20분 20초","mis":"M3-1-u5-X14"},{"t":"8시간 21분 20초","mis":"M3-1-u5-X14"},{"t":"7시간 21분 30초","mis":"M3-1-u5-X21"}],"explanation":["시는 시끼리, 분은 분끼리, 초는 초끼리 더해요.","초끼리 55 + 25 = 80 → 60초를 1분으로 받아올림, 분끼리 81 → 1시간으로 받아올림.","6시간 35분 55초 + 45분 25초 = 7시간 21분 20초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#21','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C8',3,'mc','auto','새 관찰을 40분 동안 하고 9시 15분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X20','M3-1-u5-X17','M3-1-u5-X16']::text[],true,'{"seq":21,"concept":"M3-1-u5-C8","difficulty":3,"kind":"mc","stem":"새 관찰을 40분 동안 하고 9시 15분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 35분","correct":true},{"t":"9시 55분","mis":"M3-1-u5-X20"},{"t":"9시 25분","mis":"M3-1-u5-X17"},{"t":"9시 35분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","9시 15분 − 40분 — 모자라면 60을 빌려 와요.","시작한 시각은 8시 35분이에요."],"variant_rule":{"alt":[{"stem":"동굴 체험을 2시간 30분 동안 하고 4시 10분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"1시 40분","correct":true},{"t":"6시 40분","mis":"M3-1-u5-X20"},{"t":"2시 20분","mis":"M3-1-u5-X17"},{"t":"2시 40분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","4시 10분 − 2시간 30분 — 모자라면 60을 빌려 와요.","시작한 시각은 1시 40분이에요."],"asset":null},{"stem":"환경 인형극을 1시간 15분 동안 하고 6시 5분에 끝났어요. 시작한 시각은 몇 시 몇 분인가요?","options":[{"t":"4시 50분","correct":true},{"t":"7시 20분","mis":"M3-1-u5-X20"},{"t":"5시 10분","mis":"M3-1-u5-X17"},{"t":"5시 50분","mis":"M3-1-u5-X16"}],"explanation":["시작한 시각 = 끝난 시각 − 걸린 시간이에요.","6시 5분 − 1시간 15분 — 모자라면 60을 빌려 와요.","시작한 시각은 4시 50분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#22','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C9',3,'mc','auto','야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 50분보다 오래 했어요. 정리한 친구는 누구인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X20']::text[],true,'{"seq":22,"concept":"M3-1-u5-C9","difficulty":3,"kind":"mc","stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 210 mm보다 길어요. 단서 ② 산책을 50분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"하랑","correct":true},{"t":"서윤","mis":"M3-1-u5-X19"},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 210 mm보다 긴 친구: 하랑, 서윤.","단서 ② 50분보다 오래 산책한 친구: 하랑(52분 20초), 지유(1시간 9분 15초).","두 단서를 모두 만족하는 친구는 하랑이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","235 mm","3시 15분","4시 7분 20초"],["서윤","225 mm","3시 10분","3시 35분"],["도윤","200 mm","3시 5분","3시 32분"],["지유","205 mm","4시 50분","5시 59분 15초"]]},"variant_rule":{"alt":[{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 215 mm보다 길어요. 단서 ② 산책을 35분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"지유","mis":"M3-1-u5-X19"},{"t":"하랑","mis":"M3-1-u5-X19"},{"t":"도윤","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 215 mm보다 긴 친구: 서윤, 지유.","단서 ② 35분보다 오래 산책한 친구: 하랑(1시간 7분 15초), 서윤(46분 20초).","두 단서를 모두 만족하는 친구는 서윤이에요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["하랑","195 mm","3시 10분","4시 17분 15초"],["서윤","220 mm","3시 55분","4시 41분 20초"],["도윤","210 mm","2시 50분","3시 24분 30초"],["지유","225 mm","4시 20분","4시 47분"]]}},{"stem":"야영장 점심 자리를 정리한 친구를 찾아요. 단서 ① 발 길이가 215 mm보다 길어요. 단서 ② 산책을 50분보다 오래 했어요. 정리한 친구는 누구인가요?","options":[{"t":"태오","correct":true},{"t":"은우","mis":"M3-1-u5-X19"},{"t":"하린","mis":"M3-1-u5-X19"},{"t":"민준","mis":"M3-1-u5-X20"}],"explanation":["단서 ① 발이 215 mm보다 긴 친구: 은우, 태오.","단서 ② 50분보다 오래 산책한 친구: 하린(1시간 9분 15초), 태오(1시간 11분 20초).","두 단서를 모두 만족하는 친구는 태오예요."],"asset":{"type":"expr_grid","rows":[["친구","발 길이","나간 시각","돌아온 시각"],["은우","235 mm","1시 55분","2시 27분 20초"],["하린","205 mm","2시 55분","4시 4분 15초"],["태오","240 mm","4시 50분","6시 1분 20초"],["민준","190 mm","4시 25분","5시 5분 20초"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#23','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C8',4,'sa','auto','영화 가는 1시 50분에 시작해 5시 25분에 끝났고, 영화 나는 2시 5분에 시작해 5시 50분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u5-C8","difficulty":4,"kind":"sa","stem":"영화 가는 1시 50분에 시작해 5시 25분에 끝났고, 영화 나는 2시 5분에 시작해 5시 50분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가: 5시 25분 − 1시 50분 = 3시간 35분.","나: 5시 50분 − 2시 5분 = 3시간 45분.","3시간 35분과 3시간 45분의 차 — 10분."],"variant_rule":{"alt":[{"stem":"영화 가는 1시 55분에 시작해 4시 25분에 끝났고, 영화 나는 2시 35분에 시작해 5시 30분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["가: 4시 25분 − 1시 55분 = 2시간 30분.","나: 5시 30분 − 2시 35분 = 2시간 55분.","2시간 30분과 2시간 55분의 차 — 25분."],"asset":null},{"stem":"영화 가는 1시 45분에 시작해 5시 30분에 끝났고, 영화 나는 2시 15분에 시작해 5시 25분에 끝났어요. 두 영화의 상영 시간은 몇 분 차이인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["가: 5시 30분 − 1시 45분 = 3시간 45분.","나: 5시 25분 − 2시 15분 = 3시간 10분.","3시간 45분과 3시간 10분의 차 — 35분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#24','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C7',4,'mc','auto','4시 40분에 숲 해설을 듣기 시작해서 20분 동안 듣고, 바로 이어서 1시간 50분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M3-1-u5-X19','M3-1-u5-X14']::text[],true,'{"seq":24,"concept":"M3-1-u5-C7","difficulty":4,"kind":"mc","stem":"4시 40분에 숲 해설을 듣기 시작해서 20분 동안 듣고, 바로 이어서 1시간 50분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"6시 50분","correct":true},{"t":"5시","mis":"M3-1-u5-X19"},{"t":"6시 30분","mis":"M3-1-u5-X19"},{"t":"5시 50분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","4시 40분 + 20분 = 5시.","5시 + 1시간 50분 = 6시 50분이에요."],"variant_rule":{"alt":[{"stem":"1시 55분에 숲 해설을 듣기 시작해서 20분 동안 듣고, 바로 이어서 40분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 55분","correct":true},{"t":"2시 15분","mis":"M3-1-u5-X19"},{"t":"2시 35분","mis":"M3-1-u5-X19"},{"t":"1시 55분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","1시 55분 + 20분 = 2시 15분.","2시 15분 + 40분 = 2시 55분이에요."],"asset":null},{"stem":"6시 20분에 숲 해설을 듣기 시작해서 20분 동안 듣고, 바로 이어서 35분 동안 새를 관찰했어요. 새 관찰이 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 15분","correct":true},{"t":"6시 40분","mis":"M3-1-u5-X19"},{"t":"6시 55분","mis":"M3-1-u5-X19"},{"t":"6시 15분","mis":"M3-1-u5-X14"}],"explanation":["두 활동 시간을 차례로 더해요.","6시 20분 + 20분 = 6시 40분.","6시 40분 + 35분 = 7시 15분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u5_review_d#25','math',3,1,'u5','','g3_1_math_u5_review_d','unit_review','M3-1-u5-C2',4,'essay','teacher','크레파스의 길이를 재었더니 8 cm 5 mm였어요. 이 길이를 몇 mm로 나타내고, 85 cm라고 쓰면 왜 틀리는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u5-C2","difficulty":4,"kind":"essay","stem":"크레파스의 길이를 재었더니 8 cm 5 mm였어요. 이 길이를 몇 mm로 나타내고, 85 cm라고 쓰면 왜 틀리는지 설명해 보세요.","answer_guide":{"answer":"예: 1 cm = 10 mm이므로 8 cm는 80 mm이고, 5 mm를 더하면 85 mm이다. 85 cm는 85 mm의 10배인 아주 긴 길이라 단위를 잘못 쓴 것이다.","scoring_points":["8 cm = 80 mm로 바꾸었는가","85 mm를 구했는가","85 cm는 단위가 틀렸다고 설명했는가"]},"explanation":["8 cm = 80 mm.","80 + 5 = 85 mm.","85 cm는 10배 긴 길이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
